INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39904, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "像蛇一样弯弯曲曲地向前伸。", "primary_collocate": null, "pronunciation": "wān yán", "ipa": "wan˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "一条花蛇在树林里蜿蜒前行。", "target_word": "蜿蜒", "complexity_tier": "T3", "furigana": "yī tiáo huā shé zài shù lín lǐ wān yán qián xíng", "sentence_source": "generated"}, {"text": "一群孩子排成长队，蜿蜒着走过田埂。", "target_word": "蜿蜒", "complexity_tier": "T3", "furigana": "yī qún hái zi pái chéng cháng duì wān yán zhe zǒu guò tián gěng", "sentence_source": "generated"}, {"text": "一条大蟒蛇在河边的草丛中蜿蜒游走。", "target_word": "蜿蜒", "complexity_tier": "T3", "furigana": "yī tiáo dà mǎng shé zài hé biān de cǎo cóng zhōng wān yán yóu zǒu", "sentence_source": "generated"}, {"text": "一条长长的队伍沿着山路蜿蜒前进。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条黑蛇在石头间蜿蜒穿行。", "target_word": "蜿蜒", "complexity_tier": "T3", "furigana": "yī tiáo hēi shé zài shí tou jiān wān yán chuān xíng", "sentence_source": "generated"}, {"text": "一队骆驼沿着山脊蜿蜒前进。", "target_word": "蜿蜒", "complexity_tier": "T3", "furigana": "yī duì luò tuo yán zhe shān jǐ wān yán qián jìn", "sentence_source": "generated"}, {"text": "一条青蛇从台阶底下蜿蜒爬了上来。", "target_word": "蜿蜒", "complexity_tier": "T3", "furigana": "yī tiáo qīng shé cóng tái jiē dǐ xia wān yán pá le shàng lai", "sentence_source": "generated"}, {"text": "一条小蛇在草地上蜿蜒爬行。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里，车队沿着公路蜿蜒前行。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条毒蛇蜿蜒着游过了河面。", "target_word": "蜿蜒", "complexity_tier": "T3", "furigana": "yī tiáo dú shé wān yán zhe yóu guò le hé miàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜿蜒着", "label": "体标"}], "register": "书面", "sense_fingerprint": "像蛇一样弯弯曲曲地向前伸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c766053-6752-423e-a944-839af8b9813c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。蜿蜒 wān yán 指像蛇一样弯弯曲曲地向前伸。"}, {"text": "婉言", "is_correct": false, "explanation": "婉言 wǎn yán 第一个音节为第三声，与 wān yán（第一声）只有声调不同，意思是委婉的话。"}, {"text": "温言", "is_correct": false, "explanation": "温言 wēn yán 第一个音节韵母为 en，与 wān yán 的 an 不同，意思是温和的话语。"}, {"text": "万言", "is_correct": false, "explanation": "万言 wàn yán 第一个音节为第四声，与 wān yán（第一声）只有声调不同，意思是一万字，多指长篇文字。"}], "explanations": {"蜿蜒": "正确。蜿蜒 wān yán 指像蛇一样弯弯曲曲地向前伸。", "婉言": "婉言 wǎn yán 第一个音节为第三声，与 wān yán（第一声）只有声调不同，意思是委婉的话。", "温言": "温言 wēn yán 第一个音节韵母为 en，与 wān yán 的 an 不同，意思是温和的话语。", "万言": "万言 wàn yán 第一个音节为第四声，与 wān yán（第一声）只有声调不同，意思是一万字，多指长篇文字。"}, "sentence_index": null, "correct_answer": "蜿蜒"}, "level_3": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。“蜿蜒”描写花蛇在树林里弯曲前行，与句意相合。"}, {"text": "翱翔", "is_correct": false, "explanation": "搭配：“翱翔”多用于鸟类、飞机等在空中飞行，不能用来形容蛇在林中爬行。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：冻结表示凝固、静止，与句中“前行”的动作矛盾。"}, {"text": "编织", "is_correct": false, "explanation": "配价：“编织”需要宾语，如“编织毛衣”，这里缺少宾语，句子不完整。"}], "explanations": {"蜿蜒": "正确。“蜿蜒”描写花蛇在树林里弯曲前行，与句意相合。", "翱翔": "搭配：“翱翔”多用于鸟类、飞机等在空中飞行，不能用来形容蛇在林中爬行。", "冻结": "语义：冻结表示凝固、静止，与句中“前行”的动作矛盾。", "编织": "配价：“编织”需要宾语，如“编织毛衣”，这里缺少宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "蜿蜒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他蜿蜒地跑进了教室。", "explanation": "这里应该用〈直奔〉。蜿蜒指像蛇一样弯曲向前伸，“跑进教室”是快速移动，不描写弯曲的行进路线，应换为〈直奔〉之类表达。"}, {"text": "一张桌子蜿蜒地放在屋子中央。", "explanation": "这里混淆了〈弯曲〉的形状义。蜿蜒指像蛇一样弯曲伸展的动作，静止的桌子没有延伸，表示位置应换为〈摆放〉。"}, {"text": "他蜿蜒地数着钱。", "explanation": "这里混淆了〈逐张〉的逐一清点义。蜿蜒指弯曲伸展，数钱是逐张清点，应换为〈逐张〉之类表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39904, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。蜿蜒 wān yán 指像蛇一样弯弯曲曲地向前伸。"}, {"text": "完颜", "is_correct": false, "explanation": "完颜 wán yán 的第一个音节是第二声。它与 wān yán（第一声）只有声调不同。完颜是一个复姓。"}, {"text": "晚宴", "is_correct": false, "explanation": "晚宴 wǎn yàn 的两个音节分别是第三声和第四声。它与 wān yán 的声调不同。晚宴的意思是晚上举行的宴会。"}, {"text": "弯腰", "is_correct": false, "explanation": "弯腰 wān yāo 的第二个音节韵母是 ao，与 yán 的 an 不同。弯腰的意思是把身体向前弯下。"}], "explanations": {"蜿蜒": "正确。蜿蜒 wān yán 指像蛇一样弯弯曲曲地向前伸。", "完颜": "完颜 wán yán 的第一个音节是第二声。它与 wān yán（第一声）只有声调不同。完颜是一个复姓。", "晚宴": "晚宴 wǎn yàn 的两个音节分别是第三声和第四声。它与 wān yán 的声调不同。晚宴的意思是晚上举行的宴会。", "弯腰": "弯腰 wān yāo 的第二个音节韵母是 ao，与 yán 的 an 不同。弯腰的意思是把身体向前弯下。"}, "sentence_index": null, "correct_answer": "蜿蜒"}, "level_3": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。“蜿蜒”描写青蛇从台阶底下弯曲爬上来，与句意相合。"}, {"text": "遍布", "is_correct": false, "explanation": "配价：“遍布”需要表示范围的成分，如“遍布全国”，这里句子结构不成立。"}, {"text": "闪烁", "is_correct": false, "explanation": "搭配：“闪烁”多用于光线、眼神等，不能用来形容蛇爬行。"}, {"text": "唠叨", "is_correct": false, "explanation": "语义：唠叨指说话重复、啰嗦，与蛇爬行的动作毫不相关。"}], "explanations": {"蜿蜒": "正确。“蜿蜒”描写青蛇从台阶底下弯曲爬上来，与句意相合。", "遍布": "配价：“遍布”需要表示范围的成分，如“遍布全国”，这里句子结构不成立。", "闪烁": "搭配：“闪烁”多用于光线、眼神等，不能用来形容蛇爬行。", "唠叨": "语义：唠叨指说话重复、啰嗦，与蛇爬行的动作毫不相关。"}, "sentence_index": 6, "correct_answer": "蜿蜒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雄鹰在高空蜿蜒。", "explanation": "这里应该用〈盘旋〉。蜿蜒指像蛇一样弯曲伸展，雄鹰在高空回旋飞翔应该用盘旋。"}, {"text": "他蜿蜒地擦干净了窗户。", "explanation": "这里混淆了〈来回〉的往复义。蜿蜒指像蛇一样弯曲伸展，擦窗户是来回往复的动作，应换为〈来回〉之类表达。"}, {"text": "这块石头蜿蜒地压在箱子上。", "explanation": "这里混淆了〈搁〉的静止义。蜿蜒指弯曲伸展的动态，石头压在箱子上是静止状态，应换为〈搁〉之类表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条蛇蜿蜒得一会儿，就钻进了草丛。", "corrected_sentence": "那条蛇蜿蜒了一会儿，就钻进了草丛。", "error_description": "“了”紧跟动词表示动作已完成，写作“蜿蜒了一会儿”；“得”用于动词后的补语，不能直接接时量词，写成“蜿蜒得一会儿”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "黑蛇蜿蜒得钻进了石缝。", "corrected_sentence": "黑蛇蜿蜒地钻进了石缝。", "error_description": "“地”用在动词前作状语，修饰“钻进”，写作“蜿蜒地钻进了石缝”；“得”用在动词后引出补语，不能放在动词前，写成“蜿蜒得钻进了石缝”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
