INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39905, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容山脉、河流、道路等弯弯曲曲地延伸。", "primary_collocate": null, "pronunciation": "wān yán", "ipa": "wan˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "长城就像一条巨龙，在山上蜿蜒。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "一条小河在山谷里蜿蜒流过。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路沿着河边蜿蜒向前。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公路在大山中间蜿蜒着向远方伸去。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水蜿蜒了几十公里，才流进大海。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着蜿蜒的小路走上山顶。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长长的铁路在草原上蜿蜒。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从飞机上看，那条河蜿蜒得像一条蛇。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山间的小溪蜿蜒着流下山去。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路蜿蜒穿过树林，通向小村子。", "target_word": "蜿蜒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蜿蜒着", "label": "体标"}], "register": "书面", "sense_fingerprint": "山脉、河流、道路等弯弯曲曲地延伸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c766053-6752-423e-a944-839af8b9813c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39905, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。蜿蜒 wān yán 指山脉、河流、道路等弯弯曲曲地延伸。"}, {"text": "婉言", "is_correct": false, "explanation": "婉言 wǎn yán 第一个音节为第三声，与 wān yán（第一声）只有声调不同，意思是委婉的话。"}, {"text": "官盐", "is_correct": false, "explanation": "官盐 guān yán 第一个音节声母为 g，与 wān yán 的 w 不同，意思是官家专营的食盐。"}, {"text": "温言", "is_correct": false, "explanation": "温言 wēn yán 第一个音节韵母为 en，与 wān yán 的 an 不同，意思是温和的话语。"}], "explanations": {"蜿蜒": "正确。蜿蜒 wān yán 指山脉、河流、道路等弯弯曲曲地延伸。", "婉言": "婉言 wǎn yán 第一个音节为第三声，与 wān yán（第一声）只有声调不同，意思是委婉的话。", "官盐": "官盐 guān yán 第一个音节声母为 g，与 wān yán 的 w 不同，意思是官家专营的食盐。", "温言": "温言 wēn yán 第一个音节韵母为 en，与 wān yán 的 an 不同，意思是温和的话语。"}, "sentence_index": null, "correct_answer": "蜿蜒"}, "level_3": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。“蜿蜒”描写长城像巨龙一样在山上弯曲延伸，与句中的比喻相合。"}, {"text": "坍塌", "is_correct": false, "explanation": "语义：坍塌指倒塌、崩坏，与“像一条巨龙”的形象及在山上延伸的走向不符。"}, {"text": "生长", "is_correct": false, "explanation": "搭配：“生长”多用于植物和生物，不能说长城在山上生长。"}, {"text": "翻越", "is_correct": false, "explanation": "配价：“翻越”需要宾语，如“翻越山岭”，这里缺少宾语，句子不完整。"}], "explanations": {"蜿蜒": "正确。“蜿蜒”描写长城像巨龙一样在山上弯曲延伸，与句中的比喻相合。", "坍塌": "语义：坍塌指倒塌、崩坏，与“像一条巨龙”的形象及在山上延伸的走向不符。", "生长": "搭配：“生长”多用于植物和生物，不能说长城在山上生长。", "翻越": "配价：“翻越”需要宾语，如“翻越山岭”，这里缺少宾语，句子不完整。"}, "sentence_index": 0, "correct_answer": "蜿蜒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老鹰在天空中蜿蜒。", "explanation": "这里应该用〈盘旋〉。蜿蜒指长物弯弯曲曲地延伸，老鹰在空中回旋飞翔应该用盘旋。"}, {"text": "我们在咖啡馆里蜿蜒地聊天。", "explanation": "这里混淆了〈绵延〉的时间持续义。蜿蜒只指弯曲伸展的长物，不能形容“聊天”这类动作，应换为〈长谈〉之类表达。"}, {"text": "一座小房子蜿蜒着矗立在山上。", "explanation": "这里混淆了〈弯曲〉的形状义。蜿蜒指长物沿弯曲路线伸展，块状的房子没有延伸，应换为〈耸立〉之类表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39905, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。蜿蜒 wān yán 指山脉、河流、道路等弯弯曲曲地延伸。"}, {"text": "万言", "is_correct": false, "explanation": "万言 wàn yán 的第一个音节是第四声。它与 wān yán（第一声）只有声调不同。万言的意思是一万字，多指长篇文字。"}, {"text": "晚宴", "is_correct": false, "explanation": "晚宴 wǎn yàn 的两个音节分别是第三声和第四声。它与 wān yán 的声调不同。晚宴的意思是晚上举行的宴会。"}, {"text": "完颜", "is_correct": false, "explanation": "完颜 wán yán 的第一个音节是第二声。它与 wān yán（第一声）只有声调不同。完颜是一个复姓。"}], "explanations": {"蜿蜒": "正确。蜿蜒 wān yán 指山脉、河流、道路等弯弯曲曲地延伸。", "万言": "万言 wàn yán 的第一个音节是第四声。它与 wān yán（第一声）只有声调不同。万言的意思是一万字，多指长篇文字。", "晚宴": "晚宴 wǎn yàn 的两个音节分别是第三声和第四声。它与 wān yán 的声调不同。晚宴的意思是晚上举行的宴会。", "完颜": "完颜 wán yán 的第一个音节是第二声。它与 wān yán（第一声）只有声调不同。完颜是一个复姓。"}, "sentence_index": null, "correct_answer": "蜿蜒"}, "level_3": {"options": [{"text": "蜿蜒", "is_correct": true, "explanation": "正确。“蜿蜒”描写长长的铁路在草原上弯弯曲曲地延伸，与句意相合。"}, {"text": "盛开", "is_correct": false, "explanation": "搭配：“盛开”多用于花朵，不能用来描写铁路。"}, {"text": "融化", "is_correct": false, "explanation": "语义：融化指固体因受热变为液体，铁路在草原上不会融化，句意不通。"}, {"text": "熄灭", "is_correct": false, "explanation": "搭配：“熄灭”用于火、灯等，铁路不能熄灭，句意不通。"}], "explanations": {"蜿蜒": "正确。“蜿蜒”描写长长的铁路在草原上弯弯曲曲地延伸，与句意相合。", "盛开": "搭配：“盛开”多用于花朵，不能用来描写铁路。", "融化": "语义：融化指固体因受热变为液体，铁路在草原上不会融化，句意不通。", "熄灭": "搭配：“熄灭”用于火、灯等，铁路不能熄灭，句意不通。"}, "sentence_index": 6, "correct_answer": "蜿蜒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根铁丝被他蜿蜒成了一个圆圈。", "explanation": "这里应该用〈弯曲〉。蜿蜒指长物沿一定路线伸展，铁丝被人弄成圆圈是形状改变，不是延伸。"}, {"text": "他的剑蜿蜒地刺向敌人。", "explanation": "这里混淆了〈迂回〉的绕道义。刺是直线的动作，蜿蜒只描写像蛇一样弯曲伸展的样子，不能用于剑刺敌人。"}, {"text": "这颗钉子蜿蜒地钉进了墙里。", "explanation": "这里混淆了〈笔直〉的直线义。蜿蜒指弯曲延伸，钉子钉入墙面是直线运动，应换为〈笔直〉之类表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39905, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "溪水在草地上蜿蜒的流向远方。", "corrected_sentence": "溪水在草地上蜿蜒着流向远方。", "error_description": "“蜿蜒”后应用“着”表示伸展的状态，写作“蜿蜒着流向远方”；“的”只用在名词或形容词之前作定语，不能接在动词后，写成“蜿蜒的流向远方”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39905, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小河蜿蜒得流过村庄。", "corrected_sentence": "小河蜿蜒地流过村庄。", "error_description": "“地”用在动词前作状语，修饰“流过”，写作“蜿蜒地流过村庄”；“得”用在动词后引出补语，不能放在动词前作状语，写成“蜿蜒得流过村庄”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
