INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39909, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "象征指用具体事物表示某种抽象意义或概念。", "primary_collocate": null, "pronunciation": "xiàng zhēng", "ipa": "ɕjɑŋ˥˩ ʈʂɤŋ˥", "syllable_count": 2, "sentences": [{"text": "长城象征着中华民族的坚韧。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色在中国象征着好运。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白鸽象征和平。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆月象征着一家人在一起。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙在中国文化里象征力量。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在很多国家，白色象征纯洁。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵老树象征着这个村子的历史。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国旗上的星星象征着人民。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个故事里，大海象征自由。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼上的戒指象征着爱情。", "target_word": "象征", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "象征着", "label": "体标"}, {"form": "象征性", "label": "复合"}], "register": "书面", "sense_fingerprint": "用具体事物表示抽象意义或概念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c766053-6752-423e-a944-839af8b9813c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39909, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "象征", "is_correct": true, "explanation": "“象征”作动词，表示长城代表中华民族的坚韧，与后面的“着”和宾语搭配。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑等具体物体，不能以抽象的“坚韧”为宾语。"}, {"text": "砍伐", "is_correct": false, "explanation": "语义：“砍伐”指砍倒树木，不能用来代表抽象的“坚韧”。"}, {"text": "熬煮", "is_correct": false, "explanation": "搭配：“熬煮”的对象是食物，不能与抽象的“坚韧”搭配。"}], "explanations": {"象征": "“象征”作动词，表示长城代表中华民族的坚韧，与后面的“着”和宾语搭配。", "拆除": "搭配：“拆除”的对象是建筑等具体物体，不能以抽象的“坚韧”为宾语。", "砍伐": "语义：“砍伐”指砍倒树木，不能用来代表抽象的“坚韧”。", "熬煮": "搭配：“熬煮”的对象是食物，不能与抽象的“坚韧”搭配。"}, "sentence_index": 0, "correct_answer": "象征"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长象征全班的意见。", "explanation": "这里应该用〈代表〉。象征是用具体事物表示抽象意义，不能用来说人替全班表达意见。"}, {"text": "小王象征妈妈的工作。", "explanation": "这里应该用〈代替〉。象征不能用来说人顶替别人去做事或担任职务。"}, {"text": "医生象征病人的身体。", "explanation": "这里应该用〈检查〉。象征不能指医生对病人的身体进行检查这类具体行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "象征", "is_correct": true, "explanation": "“象征”表示老树代表村子的历史，与“着”和后面的宾语搭配。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶等具体部分，不能以抽象的“历史”为宾语。"}, {"text": "锯断", "is_correct": false, "explanation": "搭配：“锯断”的对象是树木等具体物体，不能以抽象的“历史”为宾语。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多用于火、灯等，不能与“历史”搭配。"}], "explanations": {"象征": "“象征”表示老树代表村子的历史，与“着”和后面的宾语搭配。", "修剪": "搭配：“修剪”的对象是枝叶等具体部分，不能以抽象的“历史”为宾语。", "锯断": "搭配：“锯断”的对象是树木等具体物体，不能以抽象的“历史”为宾语。", "点燃": "搭配：“点燃”多用于火、灯等，不能与“历史”搭配。"}, "sentence_index": 6, "correct_answer": "象征"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在考试中象征了好成绩。", "explanation": "这里应该用〈取得〉。象征表示用事物代表意义，不能用来说人获得成绩。"}, {"text": "妈妈每天象征房间。", "explanation": "这里应该用〈打扫〉。象征不能用于人对房间进行清理这类动作。"}, {"text": "爸爸象征了自行车。", "explanation": "这里应该用〈修理〉。象征不能用来说人对自行车进行修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这面旗帜很象征着勇气。", "corrected_sentence": "这面旗帜象征着勇气。", "error_description": "错误在“很”。“象征”是动词，不能受程度副词“很”修饰，应说“这面旗帜象征着勇气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节日把象征着团圆。", "corrected_sentence": "这个节日象征着团圆。", "error_description": "错误在“把”。“把”字句要求把字后有宾语，此句“把”后直接接“象征着团圆”，缺少宾语，应删去“把”，说“这个节日象征着团圆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35ac1b9-abef-4ff1-a5d8-06e6e1710e84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39910, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "正确：“短”与“长”相对，表示两头距离小，是反义词。"}, {"text": "窄", "is_correct": false, "explanation": "“窄”与“宽”相对，与“长”无反义关系。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”与“厚”相对，与“长”无反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”与“重”相对，与“长”无反义关系。"}], "correct_answer": "短", "explanations": {"短": "正确：“短”与“长”相对，表示两头距离小，是反义词。", "窄": "“窄”与“宽”相对，与“长”无反义关系。", "薄": "“薄”与“厚”相对，与“长”无反义关系。", "轻": "“轻”与“重”相对，与“长”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39910, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "短", "is_correct": true, "explanation": "正确：“短”与“长”相对，表示两头距离小，是反义词。"}, {"text": "矮", "is_correct": false, "explanation": "“矮”与“高”相对，与“长”无反义关系。"}, {"text": "浅", "is_correct": false, "explanation": "“浅”与“深”相对，与“长”无反义关系。"}, {"text": "低", "is_correct": false, "explanation": "“低”与“高”相对，与“长”无反义关系。"}], "correct_answer": "短", "explanations": {"短": "正确：“短”与“长”相对，表示两头距离小，是反义词。", "矮": "“矮”与“高”相对，与“长”无反义关系。", "浅": "“浅”与“深”相对，与“长”无反义关系。", "低": "“低”与“高”相对，与“长”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39910, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很长就是东西从一头到另一头很远。", "primary_collocate": null, "pronunciation": "hěn cháng", "ipa": "xən˨˩˦ tʂʰɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这根绳子很长，可以绑住那棵树。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子很长，坐得下十个人。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一条很长的围巾。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔很长，比我的手还长。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走廊很长，两边有很多门。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根竹子很长，一个人拿不动。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条蛇很长，从树上垂到地上。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用很长的尺子量了墙。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条毛巾很长，可以围两圈。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她有一条很长的辫子。", "target_word": "很长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更长", "label": "比较"}, {"form": "最长", "label": "最高级"}], "register": "中性", "sense_fingerprint": "东西两头之间距离大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe61e7f-e641-46d1-b96e-b3aaed6264ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很长", "is_correct": true, "explanation": "正确：绳子要能绑住树，需要很长。"}, {"text": "很高", "is_correct": false, "explanation": "搭配：“高”描述竖向高度，绳子两头之间的距离应说“长”。"}, {"text": "很快", "is_correct": false, "explanation": "语义：绳子不能用“快”形容。"}, {"text": "很宽", "is_correct": false, "explanation": "搭配：绳子一般不说“宽”，两头距离应说“长”。"}], "explanations": {"很长": "正确：绳子要能绑住树，需要很长。", "很高": "搭配：“高”描述竖向高度，绳子两头之间的距离应说“长”。", "很快": "语义：绳子不能用“快”形容。", "很宽": "搭配：绳子一般不说“宽”，两头距离应说“长”。"}, "sentence_index": 0, "correct_answer": "很长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔很长，站在下面要仰头。", "explanation": "这里应该用〈高〉。塔的竖向高度用“高”，“长”指横向的距离。"}, {"text": "这根蜡烛很长，一会儿就烧完了。", "explanation": "这里应该用〈短〉。蜡烛一会儿就烧完，说明它短；“很长”与“短”意思相反。"}, {"text": "这层冰很长，足有一尺厚。", "explanation": "这里应该用〈厚〉。冰层的厚度用“厚”，不用“长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很长", "is_correct": true, "explanation": "正确：蛇从树上垂到地上，所以很长。"}, {"text": "很短", "is_correct": false, "explanation": "语义：蛇很短，够不到地面，与“垂到地上”矛盾。"}, {"text": "很高", "is_correct": false, "explanation": "搭配：“高”描述竖向高度，蛇身的长短应说“长”。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：蛇不能用“甜”形容。"}], "explanations": {"很长": "正确：蛇从树上垂到地上，所以很长。", "很短": "语义：蛇很短，够不到地面，与“垂到地上”矛盾。", "很高": "搭配：“高”描述竖向高度，蛇身的长短应说“长”。", "很甜": "语义：蛇不能用“甜”形容。"}, "sentence_index": 6, "correct_answer": "很长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离学校很长，每天要走一个小时。", "explanation": "这里应该用〈远〉。两地之间的距离用“远”，“很长”不用于此。"}, {"text": "这口井很长，打上来的水很甜。", "explanation": "这里应该用〈深〉。井的深浅用“深”，“长”不适用。"}, {"text": "我爷爷的年纪很长，已经九十岁了。", "explanation": "这里应该用〈大〉。年龄的大小用“大”，“长”不用于年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一根很长木棍，正好能当拐杖用。", "corrected_sentence": "这是一根很长的木棍，正好能当拐杖用。", "error_description": "的字漏用：“很长”修饰名词时后面要加“的”，应说“一根很长的木棍”，不说“一根很长木棍”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根竹竿比较很长，正好够到树枝。", "corrected_sentence": "这根竹竿很长，正好够到树枝。", "error_description": "副词叠用错误：“比较”和“很”不能同时修饰形容词，应只说“很长”或“比较长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
