INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管道是长长的空心东西，水可以在里面流。", "primary_collocate": null, "pronunciation": "guǎn dào", "ipa": "kwan˨˩˦ taʊ˥˩", "syllable_count": 2, "sentences": [{"text": "水在管道里慢慢地流。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶的管道把雨水引到院子里。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根管道很细，一次只能通过一点水。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩把球扔进了管道里。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浴室的管道有点漏水。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸墙上的管道。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道是空的，里面没有水。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，管道里的水变成了冰。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道是铁做的。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家的管道出了问题，请人来修。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "输油管道", "label": "复合"}], "register": "中性", "sense_fingerprint": "水能在里面流的长长空心物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe61e7f-e641-46d1-b96e-b3aaed6264ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管道", "is_correct": true, "explanation": "guǎn dào，指长长的空心东西，水可以在里面流。"}, {"text": "感到", "is_correct": false, "explanation": "gǎn dào 与 guǎn dào 相差一个 u 音，意思是觉得、感觉到。"}, {"text": "短道", "is_correct": false, "explanation": "duǎn dào 与 guǎn dào 声母不同（d 与 g），指短道速滑用的短跑道。"}, {"text": "管套", "is_correct": false, "explanation": "guǎn tào 与 guǎn dào 第二个音节声母不同（t 与 d），意思是套在管子外面的套子。"}], "explanations": {"管道": "guǎn dào，指长长的空心东西，水可以在里面流。", "感到": "gǎn dào 与 guǎn dào 相差一个 u 音，意思是觉得、感觉到。", "短道": "duǎn dào 与 guǎn dào 声母不同（d 与 g），指短道速滑用的短跑道。", "管套": "guǎn tào 与 guǎn dào 第二个音节声母不同（t 与 d），意思是套在管子外面的套子。"}, "sentence_index": null, "correct_answer": "管道"}, "level_3": {"options": [{"text": "管道", "is_correct": true, "explanation": "“管道”是水能在里面流的空心物，“水在管道里慢慢地流”符合句意。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线不是空心的，水不能在里面流。"}, {"text": "木棍", "is_correct": false, "explanation": "体貌：木棍是实心的，水无法在里面流。"}, {"text": "绳子", "is_correct": false, "explanation": "语义：绳子不是中空的通道，水不能在绳子里流。"}], "explanations": {"管道": "“管道”是水能在里面流的空心物，“水在管道里慢慢地流”符合句意。", "电线": "语义：电线不是空心的，水不能在里面流。", "木棍": "体貌：木棍是实心的，水无法在里面流。", "绳子": "语义：绳子不是中空的通道，水不能在绳子里流。"}, "sentence_index": 0, "correct_answer": "管道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条管道很长，车子可以开进去。", "explanation": "这里应该用〈隧道〉。管道只让水或气体流过，车辆通行的要用“隧道”。"}, {"text": "这根管道很细，只能输送很小的电流。", "explanation": "这里应该用〈电线〉。管道只输送液体或气体，输送电流要用“电线”。"}, {"text": "这根管道很细，能把船拴在岸边。", "explanation": "这里应该用〈绳子〉。管道不能拴东西，拴船要用“绳子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管道", "is_correct": true, "explanation": "“管道”是中空的，“这条管道是空的，里面没有水”符合句意。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼是活的，不能是空的，“这条鱼是空的”说不通。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾不是容器，不能说“里面没有水”。"}, {"text": "铁棍", "is_correct": false, "explanation": "体貌：铁棍是实心的，不能说是空的。"}], "explanations": {"管道": "“管道”是中空的，“这条管道是空的，里面没有水”符合句意。", "鱼": "语义：鱼是活的，不能是空的，“这条鱼是空的”说不通。", "围巾": "语义：围巾不是容器，不能说“里面没有水”。", "铁棍": "体貌：铁棍是实心的，不能说是空的。"}, "sentence_index": 6, "correct_answer": "管道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条管道通往山里，路很难走。", "explanation": "这里应该用〈道路〉。管道只输送液体或气体，人走的路要用“道路”。"}, {"text": "这条管道很宽，两岸种满了柳树。", "explanation": "这里应该用〈河道〉。管道是人造的输送通道，没有两岸；河流两岸的水道才用“河道”。"}, {"text": "每天早上，这条管道里都挤满了上班的人。", "explanation": "这里应该用〈地铁〉。管道只输送液体或气体，载人的线路要用“地铁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "屋顶的雨水通过一只管道流进了池子。", "corrected_sentence": "屋顶的雨水通过一根管道流进了池子。", "error_description": "量词错误：“管道”是长条形的，应该用“根”或“条”来计量，“只”不能用于管道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们在屋顶上铺了一根的长长的管道。", "corrected_sentence": "工人们在屋顶上铺了一根长长的管道。", "error_description": "结构错误：数量短语“一根”与后面的修饰语之间不能加“的”，应说“一根长长的管道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
