INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39913, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管道是一种中空的通道，用来输送液体或气体。", "primary_collocate": null, "pronunciation": "guǎn dào", "ipa": "kwan taʊ", "syllable_count": 2, "sentences": [{"text": "他们建造了很长的管道，把水从很远的山上送到城市。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这些管道埋在地下，很少有人看见。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下的管道把天然气送到每个家庭。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道坏了，水流到了地上。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在地下安装新的管道。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管道里有热水，所以摸起来很烫。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用管道把热水送进房间。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅检查了每一条管道。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道很粗，能送很多水。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条管道一直通到工厂后面。", "target_word": "管道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "输油管道", "label": "复合"}], "register": "中性", "sense_fingerprint": "输送液体或气体的中空通道", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bbe61e7f-e641-46d1-b96e-b3aaed6264ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39913, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "管道", "is_correct": true, "explanation": "guǎn dào，指输送液体或气体的中空通道。"}, {"text": "赶到", "is_correct": false, "explanation": "gǎn dào（第三声）与 guǎn dào 相差一个 u 音，意思是及时抵达。"}, {"text": "短道", "is_correct": false, "explanation": "duǎn dào 与 guǎn dào 声母不同（d 与 g），意思是较短的通道。"}, {"text": "管套", "is_correct": false, "explanation": "guǎn tào 与 guǎn dào 第二个音节声母不同（t 与 d），意思是套在管子外面的套子。"}], "explanations": {"管道": "guǎn dào，指输送液体或气体的中空通道。", "赶到": "gǎn dào（第三声）与 guǎn dào 相差一个 u 音，意思是及时抵达。", "短道": "duǎn dào 与 guǎn dào 声母不同（d 与 g），意思是较短的通道。", "管套": "guǎn tào 与 guǎn dào 第二个音节声母不同（t 与 d），意思是套在管子外面的套子。"}, "sentence_index": null, "correct_answer": "管道"}, "level_3": {"options": [{"text": "管道", "is_correct": true, "explanation": "“管道”是中空的输送通道，“建造了很长的管道”符合句意。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线用来输送电，不能把水送到城市。"}, {"text": "铁路", "is_correct": false, "explanation": "语义：铁路供火车行驶，不能用来输送水。"}, {"text": "绳子", "is_correct": false, "explanation": "搭配：“建造”一般用于房屋、道路、设施，不说“建造很长的绳子”来输水。"}], "explanations": {"管道": "“管道”是中空的输送通道，“建造了很长的管道”符合句意。", "电线": "语义：电线用来输送电，不能把水送到城市。", "铁路": "语义：铁路供火车行驶，不能用来输送水。", "绳子": "搭配：“建造”一般用于房屋、道路、设施，不说“建造很长的绳子”来输水。"}, "sentence_index": 0, "correct_answer": "管道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一拧管道，就洗起手来。", "explanation": "这里应该用〈水龙头〉。管道是固定输送液体或气体的管线，不能拧开放水洗手；拧开放水、供人洗手的是“水龙头”。"}, {"text": "这条管道一直通到楼下，我们每天都从那里进出。", "explanation": "这里应该用〈通道〉。管道是输送液体或气体的，供人进出的通路要用“通道”。"}, {"text": "这根管道很细，只能输送很小的电流。", "explanation": "这里应该用〈电线〉。管道只输送液体或气体，输送电流要用“电线”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管道", "is_correct": true, "explanation": "“管道”可以输送热水，“用管道把热水送进房间”符合句意。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯用于载人升降，不能把热水送进房间。"}, {"text": "车轮", "is_correct": false, "explanation": "语义：车轮用于滚动行驶，不能用来输送热水。"}, {"text": "筷子", "is_correct": false, "explanation": "搭配：“用……送”的工具要能输送液体，“用筷子送热水”不成立。"}], "explanations": {"管道": "“管道”可以输送热水，“用管道把热水送进房间”符合句意。", "电梯": "语义：电梯用于载人升降，不能把热水送进房间。", "车轮": "语义：车轮用于滚动行驶，不能用来输送热水。", "筷子": "搭配：“用……送”的工具要能输送液体，“用筷子送热水”不成立。"}, "sentence_index": 6, "correct_answer": "管道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条管道很长，火车可以从它里面穿过山底。", "explanation": "这里应该用〈隧道〉。管道只输送液体或气体，火车穿行的通道要用“隧道”。"}, {"text": "这条管道很宽，两岸种满了柳树。", "explanation": "这里应该用〈河道〉。管道是人造的输送通道，没有两岸；河流两岸的水道才用“河道”。"}, {"text": "每天早上，上班的人都坐这条管道去城里。", "explanation": "这里应该用〈地铁〉。管道只输送液体或气体，载人的线路要用“地铁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人用一只新的管道接上了水箱。", "corrected_sentence": "工人用一根新的管道接上了水箱。", "error_description": "量词错误：“管道”是长条形的，应该用“根”或“条”来计量，“只”不能用于管道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在山谷里铺设了一条的管道。", "corrected_sentence": "他们在山谷里铺设了一条管道。", "error_description": "结构错误：数量短语“一条”与名词之间不能加“的”，应说“一条管道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '188657ae-7e23-46ef-8d25-35b8cabc70d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
