INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39917, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供水系统指为一定区域内的用户提供生活、生产等用水的工程设施整体，包括取水、输水、净水和配水等环节。", "primary_collocate": null, "pronunciation": "gōng shuǐ xì tǒng", "ipa": "kʊŋ˥ ʂweɪ˨˩˦ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "古罗马的供水系统非常棒。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个城市的供水系统出了问题，今天停水了。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在检查村里的供水系统。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的供水系统让全村人都喝上了干净的水。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市需要建一个新的供水系统。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震以后，供水系统坏了，大家没有水用。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "供水系统包括取水、净水和送水。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的供水系统每天都要检查。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老小区的供水系统太旧了，常常漏水。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们参观了一个大型供水系统。", "target_word": "供水系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "供水系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市或地区为许多用户供水的整套工程设施，含取水、净水、输水、配水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cd985621-6079-4c4e-9728-3b0bc36e20cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "供水系统", "is_correct": true, "explanation": "正确。供水系统指为城市或地区供水的整套工程设施，古罗马有著名的输水渠和供水工程，句意通顺。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古罗马时代没有手机，“古罗马的手机”与句中的历史背景相矛盾。"}, {"text": "身材", "is_correct": false, "explanation": "语义：身材指人的体型，“古罗马的身材”不通。"}, {"text": "网络", "is_correct": false, "explanation": "语义：古罗马没有互联网，“古罗马的网络”与句中的时代背景相矛盾。"}], "explanations": {"供水系统": "正确。供水系统指为城市或地区供水的整套工程设施，古罗马有著名的输水渠和供水工程，句意通顺。", "手机": "语义：古罗马时代没有手机，“古罗马的手机”与句中的历史背景相矛盾。", "身材": "语义：身材指人的体型，“古罗马的身材”不通。", "网络": "语义：古罗马没有互联网，“古罗马的网络”与句中的时代背景相矛盾。"}, "sentence_index": 0, "correct_answer": "供水系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暴雨过后，城市的供水系统很快就把积水排走了。", "explanation": "这里应该用〈排水系统〉。供水系统负责把水送到用户家中，把积水排走是排水系统的工作，供水系统不能这样用。"}, {"text": "我把供水系统拧紧了，屋里不再滴水。", "explanation": "这里应该用〈水龙头〉。拧紧的是单个水龙头，供水系统是整套工程设施，不能这样处理。"}, {"text": "他是我们学校最聪明的供水系统。", "explanation": "这里应该用〈人才〉。供水系统是工程设施，比喻人时要说“人才”，不能说“供水系统”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供水系统", "is_correct": true, "explanation": "正确。供水系统是由取水、净水和送水等环节组成的整套设施，句意相符。"}, {"text": "电视机", "is_correct": false, "explanation": "语义：电视机是家用电器，不包括取水、净水和送水这些环节。"}, {"text": "容貌", "is_correct": false, "explanation": "语义：容貌指人的面容，与取水、净水、送水毫无关系。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员是人，不能说“运动员包括取水、净水和送水”。"}], "explanations": {"供水系统": "正确。供水系统是由取水、净水和送水等环节组成的整套设施，句意相符。", "电视机": "语义：电视机是家用电器，不包括取水、净水和送水这些环节。", "容貌": "语义：容貌指人的面容，与取水、净水、送水毫无关系。", "运动员": "语义：运动员是人，不能说“运动员包括取水、净水和送水”。"}, "sentence_index": 6, "correct_answer": "供水系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天，供水系统让房间保持温暖。", "explanation": "这里应该用〈暖气系统〉。供水系统负责送水，让房间保持温暖要靠暖气系统。"}, {"text": "供水系统要定期检查，防止漏气。", "explanation": "这里应该用〈煤气管道〉。供水系统输送的是水，防止漏气的应是煤气管道。"}, {"text": "供水系统把脏衣服洗干净了。", "explanation": "这里应该用〈洗衣机〉。供水系统只负责输送水，不负责洗涤衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区换了一只新的供水系统。", "corrected_sentence": "这个小区换了一套新的供水系统。", "error_description": "量词错误：供水系统是成套的设施，量词应该用“套”，不能用“只”。正确说法是“一套新的供水系统”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (39917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座城市建了一根新的供水系统。", "corrected_sentence": "这座城市建了一套新的供水系统。", "error_description": "量词错误：供水系统是成套的工程设施，量词应该用“套”，不能用“根”。“根”用于水管这类细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '948438d2-6025-4ed8-8c85-3885fcef3cbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
