INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85649, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“的”是一个小词。它放在两个词中间，说明东西是谁的，或者是什么样的。", "primary_collocate": null, "pronunciation": "de", "ipa": "tə", "syllable_count": 1, "sentences": [{"text": "这是我的书。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她的家很大。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那是老师的车。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢红色的衣服。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有一杯热的茶。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是妈妈给我的手机。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的教室在二楼。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "昨天的作业很多。", "target_word": "的", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了一件新的衣服。", "target_word": "的", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的猫喜欢睡在小床上。", "target_word": "的", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在名词前，表示东西属于谁或是什么样的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '98e58837-c3d8-404d-95dd-38296864162d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85649, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：的 de（轻声），结构助词，表示领属或修饰。"}, {"text": "德", "is_correct": false, "explanation": "dé（第二声）与 de（轻声）声调不同，意思是品德。"}, {"text": "特", "is_correct": false, "explanation": "tè（第四声）与 de 声母不同，意思是特别。"}, {"text": "呢", "is_correct": false, "explanation": "ne 与 de 声母不同，意思是语气助词，用在句末。"}, {"text": "们", "is_correct": false, "explanation": "men（轻声）与 de 声母不同，表示复数，如“我们”。"}], "explanations": {"的": "正确答案：的 de（轻声），结构助词，表示领属或修饰。", "德": "dé（第二声）与 de（轻声）声调不同，意思是品德。", "特": "tè（第四声）与 de 声母不同，意思是特别。", "呢": "ne 与 de 声母不同，意思是语气助词，用在句末。", "们": "men（轻声）与 de 声母不同，表示复数，如“我们”。"}, "sentence_index": null, "correct_answer": "的"}, "level_3": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：表示“我”和“书”之间的领属关系。"}, {"text": "之", "is_correct": false, "explanation": "语域：“之”是文言用法，口语不说“我之书”。"}, {"text": "地", "is_correct": false, "explanation": "配价：“地”用于修饰动词，“我”后面不能接“地”再接名词。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”连接动词和补语，这里没有动词，不能接在“我”后面。"}], "explanations": {"的": "正确答案：表示“我”和“书”之间的领属关系。", "之": "语域：“之”是文言用法，口语不说“我之书”。", "地": "配价：“地”用于修饰动词，“我”后面不能接“地”再接名词。", "得": "配价：“得”连接动词和补语，这里没有动词，不能接在“我”后面。"}, "sentence_index": 0, "correct_answer": "的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是书的我。", "explanation": "“的”的位置错了。“的”要放在表示主人的词后面、东西前面，应说“这是我的书”。"}, {"text": "我们一起的学习。", "explanation": "这里多用了“的”。“一起”是状语，修饰“学习”，不用“的”，应说“我们一起学习”。"}, {"text": "我的很高兴。", "explanation": "这里多用了“的”。“的”后面应接被修饰的名词，“很高兴”是谓语，应说“我很高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85649, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：的 de（轻声），结构助词，表示领属或修饰。"}, {"text": "了", "is_correct": false, "explanation": "le 与 de 声母不同，意思是动态助词，表示完成或变化。"}, {"text": "么", "is_correct": false, "explanation": "me 与 de 声母不同，意思是疑问助词，如“什么”里的“么”。"}, {"text": "个", "is_correct": false, "explanation": "gè（第四声）与 de 声母和声调都不同，意思是量词，用于人或事物。"}, {"text": "弟", "is_correct": false, "explanation": "dì（第四声）与 de 韵母和声调都不同，意思是弟弟。"}], "explanations": {"的": "正确答案：的 de（轻声），结构助词，表示领属或修饰。", "了": "le 与 de 声母不同，意思是动态助词，表示完成或变化。", "么": "me 与 de 声母不同，意思是疑问助词，如“什么”里的“么”。", "个": "gè（第四声）与 de 声母和声调都不同，意思是量词，用于人或事物。", "弟": "dì（第四声）与 de 韵母和声调都不同，意思是弟弟。"}, "sentence_index": null, "correct_answer": "的"}, "level_3": {"options": [{"text": "的", "is_correct": true, "explanation": "正确答案：表示“我们”和“教室”之间的领属关系。"}, {"text": "所", "is_correct": false, "explanation": "语域：“所”是文言用法，后面要接动词，口语不这样用。"}, {"text": "了", "is_correct": false, "explanation": "体貌：“了”表示完成，不能放在“我们”和名词之间。"}, {"text": "呢", "is_correct": false, "explanation": "配价：“呢”是语气助词，用在句末，不能放在代词和名词之间。"}], "explanations": {"的": "正确答案：表示“我们”和“教室”之间的领属关系。", "所": "语域：“所”是文言用法，后面要接动词，口语不这样用。", "了": "体貌：“了”表示完成，不能放在“我们”和名词之间。", "呢": "配价：“呢”是语气助词，用在句末，不能放在代词和名词之间。"}, "sentence_index": 6, "correct_answer": "的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只的猫很可爱。", "explanation": "这里多用了“的”。“这只”后直接接名词，不用“的”，应说“这只猫”。"}, {"text": "我家的猫喜欢的睡在小床上。", "explanation": "这里多用了“的”。“喜欢”后直接接动词“睡”，不用“的”，应说“喜欢睡在小床上”。"}, {"text": "我有三的猫。", "explanation": "这里应该用量词〈只〉。数词和名词之间要用量词，“的”不能代替量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85649, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那是他的的新电脑。", "corrected_sentence": "那是他的新电脑。", "error_description": "“的”重复：“他的新电脑”中只用一个“的”，多写一个“的”不通顺，应为“那是他的新电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85649, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的成绩的很好。", "corrected_sentence": "他的成绩很好。", "error_description": "“的很好”多了一个“的”。“的”用于名词前，“很好”是形容词谓语，应为“他的成绩很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37dcf538-697e-4cb5-980f-dc6900b53929') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
