INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85651, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "“在”是说人或东西待在哪里，或者事情在哪里发生。", "primary_collocate": null, "pronunciation": "zài", "ipa": "tsaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "我的书在书包里。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "钥匙在桌子下面。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "我的眼镜在哪儿？", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "学校在城东。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "图书馆在二楼。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "他的朋友在外地。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "我的手机在沙发底下。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "银行在车站旁边。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "妹妹的房间在三楼。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}, {"text": "厨房在屋子后面。", "target_word": "在", "complexity_tier": "T3", "furigana": "zài", "sentence_source": "generated"}], "morphological_forms": [{"form": "正在", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示人或东西位于某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85651, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在", "is_correct": true, "explanation": "在 zài：正确答案，表示东西待在某处。"}, {"text": "灾", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。"}, {"text": "赛", "is_correct": false, "explanation": "sài 与 zài 声母不同（s 与 z），意思是比赛。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zài 韵母不同（an 与 ai），意思是赞扬。"}], "explanations": {"在": "在 zài：正确答案，表示东西待在某处。", "灾": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。", "赛": "sài 与 zài 声母不同（s 与 z），意思是比赛。", "赞": "zàn 与 zài 韵母不同（an 与 ai），意思是赞扬。"}, "sentence_index": null, "correct_answer": "在"}, "level_3": {"options": [{"text": "在", "is_correct": true, "explanation": "在：表示“书”待在“书包里”，符合句意。"}, {"text": "住", "is_correct": false, "explanation": "语义：“住”指人或动物在某处居住，书不能“住”在书包里。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，主语须是能睡觉的人或动物，不能用“书”。"}, {"text": "坐", "is_correct": false, "explanation": "搭配：“坐”的主语须是人或动物，“书”不能坐。"}], "explanations": {"在": "在：表示“书”待在“书包里”，符合句意。", "住": "语义：“住”指人或动物在某处居住，书不能“住”在书包里。", "睡": "配价：“睡”是不及物动词，主语须是能睡觉的人或动物，不能用“书”。", "坐": "搭配：“坐”的主语须是人或动物，“书”不能坐。"}, "sentence_index": 0, "correct_answer": "在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间房子在三个卧室。", "explanation": "这里应该用〈有〉。“在”表示人或东西位于某处，不能引出所拥有的东西，“这间房子有三个卧室”要用“有”。"}, {"text": "我们班在三十个学生。", "explanation": "这里应该用〈有〉。“在”表示人或东西位于某处，不能引出所拥有的人，“我们班有三十个学生”要用“有”。"}, {"text": "这个方案在三个优点。", "explanation": "这里应该用〈具有〉。“在”表示位于某处，不能引出所具备的优点，“这个方案具有三个优点”要用“具有”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85651, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在", "is_correct": true, "explanation": "在 zài：正确答案，表示手机待在沙发底下。"}, {"text": "债", "is_correct": false, "explanation": "zhài 与 zài 声母不同（zh 与 z），意思是债务。"}, {"text": "栽", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是种植。"}, {"text": "菜", "is_correct": false, "explanation": "cài 与 zài 声母不同（c 与 z），意思是蔬菜。"}], "explanations": {"在": "在 zài：正确答案，表示手机待在沙发底下。", "债": "zhài 与 zài 声母不同（zh 与 z），意思是债务。", "栽": "zāi（第一声）与 zài（第四声）声调不同，意思是种植。", "菜": "cài 与 zài 声母不同（c 与 z），意思是蔬菜。"}, "sentence_index": null, "correct_answer": "在"}, "level_3": {"options": [{"text": "在", "is_correct": true, "explanation": "在：表示“手机”待在“沙发底下”，符合句意。"}, {"text": "飞", "is_correct": false, "explanation": "语义：“飞”指在空中移动，手机不能“飞”到沙发底下。"}, {"text": "蹲", "is_correct": false, "explanation": "配价：“蹲”是不及物动词，主语须是能蹲下的人或动物，不能用“手机”。"}, {"text": "趴", "is_correct": false, "explanation": "搭配：“趴”的主语须是人或动物，“手机”不能趴。"}], "explanations": {"在": "在：表示“手机”待在“沙发底下”，符合句意。", "飞": "语义：“飞”指在空中移动，手机不能“飞”到沙发底下。", "蹲": "配价：“蹲”是不及物动词，主语须是能蹲下的人或动物，不能用“手机”。", "趴": "搭配：“趴”的主语须是人或动物，“手机”不能趴。"}, "sentence_index": 6, "correct_answer": "在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在老师很尊敬。", "explanation": "这里应该用〈对〉。“对……尊敬”引出对象，“在”不能直接引出“老师”。"}, {"text": "这个城市在三条河。", "explanation": "这里应该用〈有〉。“在”表示人或东西位于某处，不能引出所拥有的东西，“这个城市有三条河”要用“有”。"}, {"text": "这本书在五个章节。", "explanation": "这里应该用〈包括〉。“在”不能引出组成部分，“这本书包括五个章节”要用“包括”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的伞在了门口。", "corrected_sentence": "我的伞在门口。", "error_description": "错误：“在”后多出“了”，“我的伞在了门口”；正确：“我的伞在门口”。表示位置的“在”后面不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架在卧室里在。", "corrected_sentence": "书架在卧室里。", "error_description": "错误：句末多出“在”；正确：“书架在卧室里”。“在”只放在地点词之前引出地点，句末不能再加“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
