INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85652, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示动作行为发生的时间或范围。", "primary_collocate": null, "pronunciation": "zài", "ipa": "tsaɪ˥˩", "syllable_count": 1, "sentences": [{"text": "会议在下午三点开始。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在周末常常去爬山。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在这个问题上有不同看法。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在学习上，他一直很认真。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛在明天上午举行。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在三岁时学会了游泳。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在老师的帮助下，我进步很快。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王在运动方面很有名。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在春天结婚。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在经济上很独立。", "target_word": "在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正在", "label": "复合"}], "register": "中性", "sense_fingerprint": "表示动作发生的时间或所涉范围", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85652, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在", "is_correct": true, "explanation": "在 zài：正确答案，表示会议在下午三点开始。"}, {"text": "灾", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。"}, {"text": "赛", "is_correct": false, "explanation": "sài 与 zài 声母不同（s 与 z），意思是比赛。"}, {"text": "赞", "is_correct": false, "explanation": "zàn 与 zài 韵母不同（an 与 ai），意思是赞扬。"}], "explanations": {"在": "在 zài：正确答案，表示会议在下午三点开始。", "灾": "zāi（第一声）与 zài（第四声）声调不同，意思是灾难。", "赛": "sài 与 zài 声母不同（s 与 z），意思是比赛。", "赞": "zàn 与 zài 韵母不同（an 与 ai），意思是赞扬。"}, "sentence_index": null, "correct_answer": "在"}, "level_3": {"options": [{"text": "在", "is_correct": true, "explanation": "在：表示会议开始的时间点，符合句意。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”引出的是对象，“下午三点”这个时间不能作“对”的对象。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“向”引出方向或对象，“会议向下午三点开始”搭配不当。"}, {"text": "给", "is_correct": false, "explanation": "语义：“给”表示给予，与“会议开始”的时间无关。"}], "explanations": {"在": "在：表示会议开始的时间点，符合句意。", "对": "配价：“对”引出的是对象，“下午三点”这个时间不能作“对”的对象。", "向": "搭配：“向”引出方向或对象，“会议向下午三点开始”搭配不当。", "给": "语义：“给”表示给予，与“会议开始”的时间无关。"}, "sentence_index": 0, "correct_answer": "在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在朋友很热情。", "explanation": "这里应该用〈对〉。“在”不能引出态度的对象，“对朋友很热情”才通顺。"}, {"text": "这次失败在我的错。", "explanation": "这里应该用〈是〉。“在”不能表示判断，“这次失败是我的错”要用“是”。"}, {"text": "他在北京来。", "explanation": "这里应该用〈从〉。“在”表示处所，不表示动作的起点，“他从北京来”要用“从”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85652, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在", "is_correct": true, "explanation": "在 zài：正确答案，表示进步的条件所在。"}, {"text": "债", "is_correct": false, "explanation": "zhài 与 zài 声母不同（zh 与 z），意思是债务。"}, {"text": "栽", "is_correct": false, "explanation": "zāi（第一声）与 zài（第四声）声调不同，意思是种植。"}, {"text": "菜", "is_correct": false, "explanation": "cài 与 zài 声母不同（c 与 z），意思是蔬菜。"}], "explanations": {"在": "在 zài：正确答案，表示进步的条件所在。", "债": "zhài 与 zài 声母不同（zh 与 z），意思是债务。", "栽": "zāi（第一声）与 zài（第四声）声调不同，意思是种植。", "菜": "cài 与 zài 声母不同（c 与 z），意思是蔬菜。"}, "sentence_index": null, "correct_answer": "在"}, "level_3": {"options": [{"text": "在", "is_correct": true, "explanation": "在：表示“老师的帮助下”这一条件范围，符合句意。"}, {"text": "比", "is_correct": false, "explanation": "语义：“比”表示比较，与“老师的帮助下”这种条件不搭。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”要引出施事，不能接“老师的帮助下”这样的条件短语。"}, {"text": "替", "is_correct": false, "explanation": "搭配：“替”后面接被替代的人，不能接“帮助下”这样的条件。"}], "explanations": {"在": "在：表示“老师的帮助下”这一条件范围，符合句意。", "比": "语义：“比”表示比较，与“老师的帮助下”这种条件不搭。", "被": "配价：“被”要引出施事，不能接“老师的帮助下”这样的条件短语。", "替": "搭配：“替”后面接被替代的人，不能接“帮助下”这样的条件。"}, "sentence_index": 6, "correct_answer": "在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在你说一件事。", "explanation": "这里应该用〈跟〉。“在”不能引出说话的对象，“我跟你说一件事”要用“跟”。"}, {"text": "这件事在大家的努力。", "explanation": "这里应该用〈靠〉。“在”不能引出所依靠的条件，“这件事靠大家的努力”要用“靠”。"}, {"text": "他在同学很友好。", "explanation": "这里应该用〈对〉。“在”不能引出态度的对象，“对同学很友好”才通顺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演出在周六晚上在开始。", "corrected_sentence": "演出在周六晚上开始。", "error_description": "错误：“在”重复出现；正确：“演出在周六晚上开始”。表示时间的“在”只需出现一次。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在数学下，她很有天赋。", "corrected_sentence": "在数学上，她很有天赋。", "error_description": "错误：“在数学下”；正确：“在数学上”。表示范围的“在……上”中，方位词要用“上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
