INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85653, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“了”放在动作后面，说明这件事做完了，或者事情变了。", "primary_collocate": null, "pronunciation": "le", "ipa": "lɤ", "syllable_count": 1, "sentences": [{"text": "我昨天买了一本书。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吃了饭就去上班。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，我们回家吧。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她已经走了。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看了三个小时的电视。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，你带伞了吗？", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在他是大学生了。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我今天学了二十个新词。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说完了，大家都笑了。", "target_word": "了", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们长大了，家里安静多了。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在动词或句末，表示动作完成或情况变化的助词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85653, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呢", "is_correct": false, "explanation": "ne 与 le 声母不同（n 与 l），意思是语气词“呢”。"}, {"text": "了", "is_correct": true, "explanation": "正确：“了”读轻声 le，是句中表示完成或变化的助词。"}, {"text": "乐", "is_correct": false, "explanation": "lè（第四声）与 le（轻声）声调不同，意思是快乐的“乐”。"}, {"text": "啦", "is_correct": false, "explanation": "la 与 le 韵母不同（a 与 e），意思是语气词“啦”。"}], "explanations": {"呢": "ne 与 le 声母不同（n 与 l），意思是语气词“呢”。", "了": "正确：“了”读轻声 le，是句中表示完成或变化的助词。", "乐": "lè（第四声）与 le（轻声）声调不同，意思是快乐的“乐”。", "啦": "la 与 le 韵母不同（a 与 e），意思是语气词“啦”。"}, "sentence_index": null, "correct_answer": "了"}, "level_3": {"options": [{"text": "着", "is_correct": false, "explanation": "体貌：“着”表示动作的持续或状态，不能与“昨天买”这种一次性完成的动作搭配。"}, {"text": "得", "is_correct": false, "explanation": "语法：“得”需接补语（如“买得起”），“买得一本书”不成立。"}, {"text": "了", "is_correct": true, "explanation": "正确：“了”表示“买”这个动作在昨天已经完成。"}, {"text": "起", "is_correct": false, "explanation": "语法：“起”多接在动词后构成“起来”，单独接在“买”后带宾语不成立。"}], "explanations": {"着": "体貌：“着”表示动作的持续或状态，不能与“昨天买”这种一次性完成的动作搭配。", "得": "语法：“得”需接补语（如“买得起”），“买得一本书”不成立。", "了": "正确：“了”表示“买”这个动作在昨天已经完成。", "起": "语法：“起”多接在动词后构成“起来”，单独接在“买”后带宾语不成立。"}, "sentence_index": 0, "correct_answer": "了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地球是圆的了。", "explanation": "这里不该用〈了〉。〈了〉表示情况发生了变化或出现新情况，地球的形状是长期不变的事实。"}, {"text": "一年有十二个月了。", "explanation": "这里不该用〈了〉。〈了〉表示变化或新情况，而一年有十二个月是恒常的事实。"}, {"text": "我一直很喜欢数学了。", "explanation": "这里不该用〈了〉。〈了〉说明情况有了新变化，而“一直很喜欢”强调持续不变，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85653, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吗", "is_correct": false, "explanation": "语义：“吗”用于构成疑问句，这里是陈述句，加上“吗”句意就变成了提问。"}, {"text": "了", "is_correct": true, "explanation": "正确：“了”表示身份已经发生变化，与“现在”相合。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”表示持续或状态，不能用于“是大学生”这类判断句句末。"}, {"text": "过", "is_correct": false, "explanation": "语法：“过”表示曾经有过的经历，不能用于此类判断句句末表示身份变化。"}], "explanations": {"吗": "语义：“吗”用于构成疑问句，这里是陈述句，加上“吗”句意就变成了提问。", "了": "正确：“了”表示身份已经发生变化，与“现在”相合。", "着": "语法：“着”表示持续或状态，不能用于“是大学生”这类判断句句末。", "过": "语法：“过”表示曾经有过的经历，不能用于此类判断句句末表示身份变化。"}, "sentence_index": 6, "correct_answer": "了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "北京是中国的首都了。", "explanation": "这里不该用〈了〉。〈了〉表示新情况或变化，北京作为首都是长期稳定的事实。"}, {"text": "一周有七天了。", "explanation": "这里不该用〈了〉。〈了〉表示变化，而“一周有七天”是恒常的事实。"}, {"text": "水由氢和氧组成了。", "explanation": "这里不该用〈了〉。〈了〉要求句子表示变化，而水的组成是不变的化学事实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85653, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了了一件新衣服。", "corrected_sentence": "我昨天买了一件新衣服。", "error_description": "“买”后面已经用“了”表示动作完成，又重复加了一个“了”，只需一个“了”，应写作“我昨天买了一件新衣服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85653, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天看着两部电影。", "corrected_sentence": "他昨天看了两部电影。", "error_description": "“昨天看两部电影”是已经完成的动作，应该用“了”表示完成，不能用表示持续的“着”。应写作“他昨天看了两部电影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
