INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85654, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用在动词或句末，表示动作已经完成或情况发生了变化。", "primary_collocate": null, "pronunciation": "le", "ipa": "lɤ", "syllable_count": 1, "sentences": [{"text": "我昨天买了一本书。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了早饭就去上班了。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们回家吧。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气冷了，多穿一件衣服。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做了很多好吃的菜。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我已经学了三年汉语了。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都睡了。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了看手表，说时间不早了。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友打了一个电话。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，花都开了。", "target_word": "了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "助词了：动词后表完成，句末表变化或新情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "呢", "is_correct": false, "explanation": "ne 与 le 声母不同（n 与 l），意思是语气词“呢”。"}, {"text": "了", "is_correct": true, "explanation": "正确：“了”读轻声 le，是句中表示完成或变化的助词。"}, {"text": "乐", "is_correct": false, "explanation": "lè（第四声）与 le（轻声）声调不同，意思是快乐的“乐”。"}, {"text": "啦", "is_correct": false, "explanation": "la 与 le 韵母不同（a 与 e），意思是语气词“啦”。"}], "explanations": {"呢": "ne 与 le 声母不同（n 与 l），意思是语气词“呢”。", "了": "正确：“了”读轻声 le，是句中表示完成或变化的助词。", "乐": "lè（第四声）与 le（轻声）声调不同，意思是快乐的“乐”。", "啦": "la 与 le 韵母不同（a 与 e），意思是语气词“啦”。"}, "sentence_index": null, "correct_answer": "了"}, "level_3": {"options": [{"text": "着", "is_correct": false, "explanation": "体貌：“着”表示动作的持续或状态，不能与“昨天买”这种一次性完成的动作搭配。"}, {"text": "吗", "is_correct": false, "explanation": "语法：“吗”是句末疑问语气词，不能放在动词“买”和宾语之间。"}, {"text": "了", "is_correct": true, "explanation": "正确：“了”表示“买”这个动作在昨天已经完成。"}, {"text": "的", "is_correct": false, "explanation": "结构：“的”用于修饰名词，“我昨天买的一本书”缺少谓语，不能独立成句。"}], "explanations": {"着": "体貌：“着”表示动作的持续或状态，不能与“昨天买”这种一次性完成的动作搭配。", "吗": "语法：“吗”是句末疑问语气词，不能放在动词“买”和宾语之间。", "了": "正确：“了”表示“买”这个动作在昨天已经完成。", "的": "结构：“的”用于修饰名词，“我昨天买的一本书”缺少谓语，不能独立成句。"}, "sentence_index": 0, "correct_answer": "了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一天有二十四个小时了。", "explanation": "这里不该用〈了〉。〈了〉表示变化或新情况，而一天有二十四小时是恒定的事实。"}, {"text": "北京在中国北方了。", "explanation": "这里不该用〈了〉。〈了〉表示新的变化，北京的地理位置不会因此改变。"}, {"text": "三角形有三条边了。", "explanation": "这里不该用〈了〉。〈了〉表示情况发生了变化，而三角形的边数是固定的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地", "is_correct": false, "explanation": "结构：“地”用在状语和动词之间（如“慢慢地走”），不能放在句末。"}, {"text": "了", "is_correct": true, "explanation": "正确：“了”表示状态已经发生变化，句子陈述孩子们已经睡下。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是副词，要放在形容词前面，不能放在动词“睡”后面的句末。"}, {"text": "把", "is_correct": false, "explanation": "语法：“把”是介词，后面要接宾语和动词，不能放在句末。"}], "explanations": {"地": "结构：“地”用在状语和动词之间（如“慢慢地走”），不能放在句末。", "了": "正确：“了”表示状态已经发生变化，句子陈述孩子们已经睡下。", "很": "语法：“很”是副词，要放在形容词前面，不能放在动词“睡”后面的句末。", "把": "语法：“把”是介词，后面要接宾语和动词，不能放在句末。"}, "sentence_index": 6, "correct_answer": "了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一年有四个季节了。", "explanation": "这里不该用〈了〉。〈了〉表示变化，而一年有四个季节是恒常的事实。"}, {"text": "猫有四条腿了。", "explanation": "这里不该用〈了〉。〈了〉表示新情况，而猫有四条腿是长期不变的事实。"}, {"text": "水是无色的了。", "explanation": "这里不该用〈了〉。〈了〉表示状态发生了变化，而水的颜色是稳定的性质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚下班，已经回家了过。", "corrected_sentence": "他刚下班，已经回家了。", "error_description": "“已经……了”表示动作已经完成、情况已有变化，句末用一个“了”即可；句末再加“过”是多余的，且“过”表示曾经有过的经历，与“刚下班”的时间不符。应写作“他刚下班，已经回家了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她看完那本书过了。", "corrected_sentence": "她看完那本书了。", "error_description": "“看完”表示动作已经结束，句末应用“了”表示完成，不能用“过”（过表示曾经有过的经历）。应写作“她看完那本书了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
