INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85656, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第一人称代词，指说话人自己。", "primary_collocate": null, "pronunciation": "wǒ", "ipa": "wɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我是中国人，你是哪国人？", "target_word": "我", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想去图书馆，你去不去？", "target_word": "我", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天是我的生日，请你来玩。", "target_word": "我", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我每天七点起床，八点上班。", "target_word": "我", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不知道，只有我知道这件事。", "target_word": "我", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "哥哥送给我一本很好看的书。", "target_word": "我", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对不起，我来晚了，让你久等了。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢听音乐，也喜欢看电影。", "target_word": "我", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你说得对，我以前没想过这个问题。", "target_word": "我", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先走了，明天见。", "target_word": "我", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "我们", "label": "复数"}, {"form": "我的", "label": "所属形式"}], "register": "中性", "sense_fingerprint": "第一人称单数代词，作主语或宾语指说话人本人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d72c37e-001c-46ce-9b8e-ae187f9ffc54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85656, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "我", "is_correct": true, "explanation": "正确答案。“我”wǒ 是第一人称代词，指说话人自己。"}, {"text": "窝", "is_correct": false, "explanation": "wō（第一声）与 wǒ（第三声）声调不同，意思是鸟窝。"}, {"text": "握", "is_correct": false, "explanation": "wò（第四声）与 wǒ（第三声）声调不同，意思是握手。"}, {"text": "果", "is_correct": false, "explanation": "guǒ 与 wǒ 声母不同（g 与零声母），意思是水果。"}, {"text": "火", "is_correct": false, "explanation": "huǒ 与 wǒ 声母不同（h 与零声母），意思是火。"}, {"text": "朵", "is_correct": false, "explanation": "duǒ 与 wǒ 声母不同（d 与零声母），意思是花朵，常作量词。"}], "explanations": {"我": "正确答案。“我”wǒ 是第一人称代词，指说话人自己。", "窝": "wō（第一声）与 wǒ（第三声）声调不同，意思是鸟窝。", "握": "wò（第四声）与 wǒ（第三声）声调不同，意思是握手。", "果": "guǒ 与 wǒ 声母不同（g 与零声母），意思是水果。", "火": "huǒ 与 wǒ 声母不同（h 与零声母），意思是火。", "朵": "duǒ 与 wǒ 声母不同（d 与零声母），意思是花朵，常作量词。"}, "sentence_index": null, "correct_answer": "我"}, "level_3": {"options": [{"text": "我", "is_correct": true, "explanation": "“我”指说话人自己，与后面问“你是哪国人”形成对应，是唯一合适的选项。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括听话人，说“咱们是中国人”等于断定对方也是中国人，与后面问对方国籍矛盾。"}, {"text": "你们", "is_correct": false, "explanation": "语义：“你们”指复数的听话人，与后面单独问“你是哪国人”的对象不一致。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能指人，“它是中国人”句意不通。"}], "explanations": {"我": "“我”指说话人自己，与后面问“你是哪国人”形成对应，是唯一合适的选项。", "咱们": "语义：“咱们”包括听话人，说“咱们是中国人”等于断定对方也是中国人，与后面问对方国籍矛盾。", "你们": "语义：“你们”指复数的听话人，与后面单独问“你是哪国人”的对象不一致。", "它": "语义：“它”指物或动物，不能指人，“它是中国人”句意不通。"}, "sentence_index": 0, "correct_answer": "我"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天一起去爬山吧。", "explanation": "这里是邀请对方一起去，应该用〈咱们〉。“我”只指说话人自己，不包括听话人，不能用于邀请对方。"}, {"text": "我都说这个好，我却不这么想。", "explanation": "这里指别人的看法，应该用〈人家〉。“我”只指说话人自己，句中“我都说”与“我却不这么想”自相矛盾。"}, {"text": "我都不敢说，只有我敢说。", "explanation": "这里前半句指别人，应该用〈别人〉。“我”指说话人，前后两句变成同一人既不敢又敢，句意矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85656, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "我", "is_correct": true, "explanation": "正确答案。“我”wǒ 是第一人称代词，指说话人自己。"}, {"text": "蜗", "is_correct": false, "explanation": "wō（第一声）与 wǒ（第三声）声调不同，意思是蜗牛。"}, {"text": "卧", "is_correct": false, "explanation": "wò（第四声）与 wǒ（第三声）声调不同，意思是躺下。"}, {"text": "所", "is_correct": false, "explanation": "suǒ 与 wǒ 声母不同（s 与零声母），意思是处所。"}, {"text": "妥", "is_correct": false, "explanation": "tuǒ 与 wǒ 声母不同（t 与零声母），意思是妥当。"}], "explanations": {"我": "正确答案。“我”wǒ 是第一人称代词，指说话人自己。", "蜗": "wō（第一声）与 wǒ（第三声）声调不同，意思是蜗牛。", "卧": "wò（第四声）与 wǒ（第三声）声调不同，意思是躺下。", "所": "suǒ 与 wǒ 声母不同（s 与零声母），意思是处所。", "妥": "tuǒ 与 wǒ 声母不同（t 与零声母），意思是妥当。"}, "sentence_index": null, "correct_answer": "我"}, "level_3": {"options": [{"text": "我", "is_correct": true, "explanation": "“我”指说话人自己，与“对不起”的道歉语境相符，是唯一合适的选项。"}, {"text": "你", "is_correct": false, "explanation": "语义：道歉的人不能说对方“来晚了”，句意与“对不起”的语境相反。"}, {"text": "别人", "is_correct": false, "explanation": "语义：道歉的是说话人自己，由说话人为“别人来晚了”道歉没有依据，句意不通。"}, {"text": "走", "is_correct": false, "explanation": "语法：“走”是动词，不能作主语，“对不起，走来晚了”不成句。"}], "explanations": {"我": "“我”指说话人自己，与“对不起”的道歉语境相符，是唯一合适的选项。", "你": "语义：道歉的人不能说对方“来晚了”，句意与“对不起”的语境相反。", "别人": "语义：道歉的是说话人自己，由说话人为“别人来晚了”道歉没有依据，句意不通。", "走": "语法：“走”是动词，不能作主语，“对不起，走来晚了”不成句。"}, "sentence_index": 6, "correct_answer": "我"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈问我：“我今天怎么这么早回家？”", "explanation": "这里是妈妈问孩子，应该用〈你〉。“我”指说话人自己，此处指的是对方，用错了人称。"}, {"text": "你帮助我，我也会帮助我的。", "explanation": "这里是说回报对方，应该用〈你〉。“我”指说话人自己，后半句帮助的对象是对方，用错了人称。"}, {"text": "请你先做一下我介绍，好吗？", "explanation": "这里应是“自我介绍”，应该用〈自我介绍〉。“我”不能单独与“介绍”组合，需要组成“自我介绍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85656, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我书，不是你的。", "corrected_sentence": "这是我的书，不是你的。", "error_description": "错误：“我书”少了“的”，应说“我的书”。“我”作定语修饰名词时，一般要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85656, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他送我给一本书。", "corrected_sentence": "他送给我一本书。", "error_description": "错误：“给”的位置不对。“送给”是连在一起的动词结构，应说“送给我”，不能说“送我给”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85657, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85657, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85657, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“和”可以把两个人或两样东西连在一起，说成一起。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "桌子上有苹果和香蕉。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有爸爸、妈妈和我。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一本书和一支笔。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明和小红是好朋友。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里有牛奶和鸡蛋。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢猫和狗。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生都在教室里。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的包里有手机和钥匙。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海都是大城市。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥和姐姐都在北京工作。", "target_word": "和", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "连接两个并列的名词，人或东西放在一起说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd392b4f9-49cb-42d5-83fd-145c61c00b83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85657, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "和", "is_correct": true, "explanation": "和 hé 是连词，表示连接并列的人或事物，是正确答案。"}, {"text": "喝", "is_correct": false, "explanation": "喝 hē 与 和 hé 的声调不同（第一声），意思是把水或饮料咽下去。"}, {"text": "韩", "is_correct": false, "explanation": "韩 hán 与 和 hé 的韵母不同（an 与 e），声调相同，意思是韩国。"}, {"text": "鹤", "is_correct": false, "explanation": "鹤 hè 与 和 hé 的声调不同（第四声），意思是一种长腿长脖子的鸟。"}, {"text": "贺", "is_correct": false, "explanation": "贺 hè 与 和 hé 的声调不同（第四声），意思是祝贺。"}], "explanations": {"和": "和 hé 是连词，表示连接并列的人或事物，是正确答案。", "喝": "喝 hē 与 和 hé 的声调不同（第一声），意思是把水或饮料咽下去。", "韩": "韩 hán 与 和 hé 的韵母不同（an 与 e），声调相同，意思是韩国。", "鹤": "鹤 hè 与 和 hé 的声调不同（第四声），意思是一种长腿长脖子的鸟。", "贺": "贺 hè 与 和 hé 的声调不同（第四声），意思是祝贺。"}, "sentence_index": null, "correct_answer": "和"}, "level_3": {"options": [{"text": "和", "is_correct": true, "explanation": "和表示连接并列的名词，“苹果和香蕉”的句意相符，是正确答案。"}, {"text": "但是", "is_correct": false, "explanation": "语义：“但是”表示转折，不能连接并列的两种水果，“苹果但是香蕉”句意不通。"}, {"text": "而", "is_correct": false, "explanation": "语域：“而”是书面连词，多连接动词或形容词，不能用来连接并列的水果名词。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，与“桌子上有苹果和香蕉”的并列关系不符。"}], "explanations": {"和": "和表示连接并列的名词，“苹果和香蕉”的句意相符，是正确答案。", "但是": "语义：“但是”表示转折，不能连接并列的两种水果，“苹果但是香蕉”句意不通。", "而": "语域：“而”是书面连词，多连接动词或形容词，不能用来连接并列的水果名词。", "虽然": "语义：“虽然”表示让步，与“桌子上有苹果和香蕉”的并列关系不符。"}, "sentence_index": 0, "correct_answer": "和"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们一家人和睦相处，从来不吵架。", "explanation": "这里是“和睦”（关系融洽）的意思，属于“和”的另一种用法，不表示连接并列的人或事物。"}, {"text": "妈妈在厨房和面，准备包饺子。", "explanation": "这里是动词“和面”（加水揉面）的意思，属于“和”的另一种用法，不表示连接并列成分。"}, {"text": "他们吵了一架，后来又和好了。", "explanation": "这里是动词“和好”（重归于好）的意思，属于“和”的另一种用法，不作连词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85657, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "和", "is_correct": true, "explanation": "和 hé 是连词，表示连接并列的人或事物，是正确答案。"}, {"text": "呵", "is_correct": false, "explanation": "呵 hē 与 和 hé 的声调不同（第一声），意思是呵气、呵斥。"}, {"text": "赫", "is_correct": false, "explanation": "赫 hè 与 和 hé 的声调不同（第四声），意思是显赫。"}, {"text": "寒", "is_correct": false, "explanation": "寒 hán 与 和 hé 的韵母不同（an 与 e），声调相同，意思是寒冷。"}], "explanations": {"和": "和 hé 是连词，表示连接并列的人或事物，是正确答案。", "呵": "呵 hē 与 和 hé 的声调不同（第一声），意思是呵气、呵斥。", "赫": "赫 hè 与 和 hé 的声调不同（第四声），意思是显赫。", "寒": "寒 hán 与 和 hé 的韵母不同（an 与 e），声调相同，意思是寒冷。"}, "sentence_index": null, "correct_answer": "和"}, "level_3": {"options": [{"text": "和", "is_correct": true, "explanation": "和表示连接并列的人，“老师和学生都在教室里”的句意相符，是正确答案。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，连接的是两个分句，不能连接“老师”和“学生”两个并列的人。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结果，不能用来连接并列的人，句意不通。"}, {"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“老师和学生都在教室里”的并列关系不符。"}], "explanations": {"和": "和表示连接并列的人，“老师和学生都在教室里”的句意相符，是正确答案。", "因为": "语义：“因为”表示原因，连接的是两个分句，不能连接“老师”和“学生”两个并列的人。", "所以": "语义：“所以”表示结果，不能用来连接并列的人，句意不通。", "尽管": "语义：“尽管”表示让步，与“老师和学生都在教室里”的并列关系不符。"}, "sentence_index": 6, "correct_answer": "和"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对邻居很和气，大家都喜欢他。", "explanation": "这里是形容词“和气”（待人温和）的意思，属于“和”的另一种用法，不表示连接并列的人或事物。"}, {"text": "这盘棋最后下和了。", "explanation": "这里的“和”表示比赛不分胜负（平局），属于“和”的另一种用法，不作连词。"}, {"text": "她用水把面粉和成面团。", "explanation": "这里的“和”读 huó，意思是加水搅拌、揉在一起，属于“和”的另一种用法，不表示连接并列成分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈和爸爸和都很忙。", "corrected_sentence": "妈妈和爸爸都很忙。", "error_description": "多余的“和”：“和”已连接“妈妈”与“爸爸”，后面不能再加“和”，应说“妈妈和爸爸都很忙”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书和和笔都在桌子上。", "corrected_sentence": "书和笔都在桌子上。", "error_description": "重复错误：“和”只用一次，“书和笔”之间不能重复“和”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cbd57905-2a75-4732-b296-47278eecfe97') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
