INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85659, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“你”是我们对面前说话的那个人的叫法。", "primary_collocate": null, "pronunciation": "nǐ", "ipa": "ni˨˩˦", "syllable_count": 1, "sentences": [{"text": "你叫什么名字？", "target_word": "你", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小李，我想问你一个问题。", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈对我说：“你要早点儿睡。”", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王，你今天为什么没来上课？", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书是我送给你的，生日快乐！", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你昨天去哪儿了？", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在门口等你，你快一点儿。", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你帮我拿了行李。", "target_word": "你", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看过这个电影吗？", "target_word": "你", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你站着，我给你拍一张照片。", "target_word": "你", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "你们", "label": "复数"}, {"form": "您", "label": "敬称"}], "register": "口语", "sense_fingerprint": "第二人称代词，指说话时面对的那个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c41e43-d819-4200-99d8-f4259434702f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85659, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "你", "is_correct": true, "explanation": "正确。你 nǐ，指说话时面对的人。"}, {"text": "里", "is_correct": false, "explanation": "lǐ（第三声）与 nǐ（第三声）声母不同（l/n），意思是里面。"}, {"text": "泥", "is_correct": false, "explanation": "ní（第二声）与 nǐ（第三声）声调不同，意思是泥土。"}, {"text": "逆", "is_correct": false, "explanation": "nì（第四声）与 nǐ（第三声）声调不同，意思是违反、相反。"}, {"text": "礼", "is_correct": false, "explanation": "lǐ（第三声）与 nǐ（第三声）声母不同（l/n），意思是礼物。"}], "explanations": {"你": "正确。你 nǐ，指说话时面对的人。", "里": "lǐ（第三声）与 nǐ（第三声）声母不同（l/n），意思是里面。", "泥": "ní（第二声）与 nǐ（第三声）声调不同，意思是泥土。", "逆": "nì（第四声）与 nǐ（第三声）声调不同，意思是违反、相反。", "礼": "lǐ（第三声）与 nǐ（第三声）声母不同（l/n），意思是礼物。"}, "sentence_index": null, "correct_answer": "你"}, "level_3": {"options": [{"text": "你", "is_correct": true, "explanation": "正确。“你”是对面前说话的人的称呼，与提问的对象一致。"}, {"text": "我们", "is_correct": false, "explanation": "语义：问的是对方的名字，“我们”指说话的一方，不能对着对方这样问。"}, {"text": "大家", "is_correct": false, "explanation": "搭配：“大家”指一群人，不能对着一个人问“叫什么名字”。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人或主语本人，与问对方名字的语境不符。"}], "explanations": {"你": "正确。“你”是对面前说话的人的称呼，与提问的对象一致。", "我们": "语义：问的是对方的名字，“我们”指说话的一方，不能对着对方这样问。", "大家": "搭配：“大家”指一群人，不能对着一个人问“叫什么名字”。", "自己": "语义：“自己”指说话人或主语本人，与问对方名字的语境不符。"}, "sentence_index": 0, "correct_answer": "你"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一本书，你很贵。", "explanation": "这里应该用〈它〉。“你”只指人，指书要用“它”，不能说“你很贵”。"}, {"text": "小王和小李，你今天为什么没来上课？", "explanation": "这里应该用〈你们〉。问的是两个人，要用复数“你们”，不能用单数“你”。"}, {"text": "小王，我想问我一个问题。", "explanation": "这里应该用〈你〉。对方是小王，要指对方用“你”，不能用“我”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85659, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "你", "is_correct": true, "explanation": "正确。你 nǐ，指说话时面对的人。"}, {"text": "理", "is_correct": false, "explanation": "lǐ（第三声）与 nǐ（第三声）声母不同（l/n），意思是道理。"}, {"text": "泥", "is_correct": false, "explanation": "ní（第二声）与 nǐ（第三声）声调不同，意思是泥土。"}, {"text": "腻", "is_correct": false, "explanation": "nì（第四声）与 nǐ（第三声）声调不同，意思是油脂多、不爽口。"}], "explanations": {"你": "正确。你 nǐ，指说话时面对的人。", "理": "lǐ（第三声）与 nǐ（第三声）声母不同（l/n），意思是道理。", "泥": "ní（第二声）与 nǐ（第三声）声调不同，意思是泥土。", "腻": "nì（第四声）与 nǐ（第三声）声调不同，意思是油脂多、不爽口。"}, "sentence_index": null, "correct_answer": "你"}, "level_3": {"options": [{"text": "你", "is_correct": true, "explanation": "正确。“你”指对方，与“快一点儿”的催促对象一致。"}, {"text": "我", "is_correct": false, "explanation": "语义：“快一点儿”是催促对方，说话人不能催促自己等待。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指说话人本人，“我们在门口等自己”不通。"}, {"text": "我自己", "is_correct": false, "explanation": "搭配：“等”后面不能接“我自己”，这样说不符合语境。"}], "explanations": {"你": "正确。“你”指对方，与“快一点儿”的催促对象一致。", "我": "语义：“快一点儿”是催促对方，说话人不能催促自己等待。", "自己": "语义：“自己”指说话人本人，“我们在门口等自己”不通。", "我自己": "搭配：“等”后面不能接“我自己”，这样说不符合语境。"}, "sentence_index": 6, "correct_answer": "你"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车很新，你很便宜。", "explanation": "这里应该用〈它〉。“你”只指人，指车要用“它”。"}, {"text": "这个包很重，你太重了，我背不动。", "explanation": "这里应该用〈它〉。“你”只指说话时面对的人，不能指东西。"}, {"text": "小王，我想请他帮个忙。", "explanation": "这里应该用〈你〉。小王就在对面，直接请求对方要用“你”，不能用“他”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85659, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢你书。", "corrected_sentence": "我喜欢你的书。", "error_description": "「你」表示所属修饰名词时要加“的”，应说“你的书”，不能说“你书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85659, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你三个人都来了吗？", "corrected_sentence": "你们都来了吗？", "error_description": "说的是三个人，要用复数“你们”，不能用单数“你”，应说“你们三个人都来了吗？”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
