INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85661, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“为”是变成另一种样子或状态。", "primary_collocate": null, "pronunciation": "wéi", "ipa": "weɪ˧˥", "syllable_count": 1, "sentences": [{"text": "冰慢慢化为水。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的努力变为现实。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把坏事变为好事。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年的辛苦化为泡影。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村变为大城市了。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们把这块地改为公园。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人由朋友转为夫妻。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旧沙发改造为长椅。", "target_word": "为", "complexity_tier": "T3", "furigana": "tā bǎ jiù shā fā gǎi zào wéi cháng yǐ", "sentence_source": "generated"}, {"text": "水加热会变为水蒸气。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从工人转为老板。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成为", "label": "复合"}, {"form": "作为", "label": "复合"}, {"form": "為", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "变成另一种样子，如化为、变为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85661, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为", "is_correct": true, "explanation": "为：wéi（第二声），表示“变成”，如“化为水”。"}, {"text": "位", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是位置。"}, {"text": "委", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是委托。"}, {"text": "威", "is_correct": false, "explanation": "wēi（第一声）与 wéi（第二声）声调不同，意思是威力。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是听见。"}], "explanations": {"为": "为：wéi（第二声），表示“变成”，如“化为水”。", "位": "wèi（第四声）与 wéi（第二声）声调不同，意思是位置。", "委": "wěi（第三声）与 wéi（第二声）声调不同，意思是委托。", "威": "wēi（第一声）与 wéi（第二声）声调不同，意思是威力。", "闻": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是听见。"}, "sentence_index": null, "correct_answer": "为"}, "level_3": {"options": [{"text": "为", "is_correct": true, "explanation": "为：表示“变成”，与“化”组成“化为”，指冰变成水。"}, {"text": "是", "is_correct": false, "explanation": "语义：“是”表示判断，不表示变化，“化是水”不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不与“化”搭配表示变成，“化吃水”不成立。"}, {"text": "抱", "is_correct": false, "explanation": "语义：“抱”表示用手臂环绕，与物质的变化无关。"}], "explanations": {"为": "为：表示“变成”，与“化”组成“化为”，指冰变成水。", "是": "语义：“是”表示判断，不表示变化，“化是水”不通。", "吃": "搭配：“吃”不与“化”搭配表示变成，“化吃水”不成立。", "抱": "语义：“抱”表示用手臂环绕，与物质的变化无关。"}, "sentence_index": 0, "correct_answer": "为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小村为大城市了。", "explanation": "这里应该用〈变成〉。“为”不能单独接名词后加“了”表示变化，这种说法不通。"}, {"text": "冰慢慢为了水。", "explanation": "这里应该用〈化成〉。“为了”表示目的，后面要接动词性成分，不能表示冰变成水。"}, {"text": "他从工人为老板。", "explanation": "这里应该加动词“转”，说〈转为〉。“为”不能单独接在“从……”后表示身份转变。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85661, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "为", "is_correct": true, "explanation": "为：wéi（第二声），表示“变成”，如“转为老板”。"}, {"text": "未", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。"}, {"text": "尾", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。"}, {"text": "微", "is_correct": false, "explanation": "wēi（第一声）与 wéi（第二声）声调不同，意思是微小。"}, {"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是文字。"}], "explanations": {"为": "为：wéi（第二声），表示“变成”，如“转为老板”。", "未": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。", "尾": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。", "微": "wēi（第一声）与 wéi（第二声）声调不同，意思是微小。", "文": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是文字。"}, "sentence_index": null, "correct_answer": "为"}, "level_3": {"options": [{"text": "为", "is_correct": true, "explanation": "为：表示“变成”，“转为夫妻”指关系转变成夫妻。"}, {"text": "摆", "is_correct": false, "explanation": "搭配：“摆”指放置，不能表示关系的转变。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示丢弃，与关系转变无关。"}, {"text": "拉", "is_correct": false, "explanation": "配价：“拉”需要具体的被拉对象，不能接“夫妻”表示转变。"}], "explanations": {"为": "为：表示“变成”，“转为夫妻”指关系转变成夫妻。", "摆": "搭配：“摆”指放置，不能表示关系的转变。", "扔": "语义：“扔”表示丢弃，与关系转变无关。", "拉": "配价：“拉”需要具体的被拉对象，不能接“夫妻”表示转变。"}, "sentence_index": 6, "correct_answer": "为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木头为椅子了。", "explanation": "这里应该用〈做成〉。“为”不能直接接名词表示制成，应说“做成”。"}, {"text": "这个词为新词了。", "explanation": "这里应该用〈演变〉。“为”不能直接表示词语演变成另一个词，应说“演变成”。"}, {"text": "孩子为大人了。", "explanation": "这里应该用〈长成〉。“为”不能表示孩子长成大人的变化，应说“长成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85661, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片荒地终于变为成良田。", "corrected_sentence": "这片荒地终于变为良田。", "error_description": "错误：“变为成”；正确：“变为良田”。“为”已表示“变成”，后面不能再加“成”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85661, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她从学生为教师。", "corrected_sentence": "她从学生转为教师。", "error_description": "漏掉“转”。“从……为……”不成立，表示身份转变要说“转为”，应为：她从学生转为教师。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
