INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85662, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，表示充当、担任或算作某种身份或角色；多用于书面语。", "primary_collocate": null, "pronunciation": "wéi", "ipa": "weɪ˧˥", "syllable_count": 1, "sentences": [{"text": "大家选他为班长。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把十月一日定为运动日。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们称这座山为红山。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民推举他为村长。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以诚实为荣。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都以他为榜样。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校聘他为顾问。", "target_word": "为", "complexity_tier": "T3", "furigana": "xué xiào pìn tā wéi gù wèn", "sentence_source": "generated"}, {"text": "公司决定以北京为中心。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家推他为代表。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聘请她为我们的老师。", "target_word": "为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成为", "label": "复合"}, {"form": "作为", "label": "复合"}, {"form": "為", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "充当、算作，如选某人为班长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26dbc4a2-a243-4c22-9f23-9c2db77eb70c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85662, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "为", "is_correct": true, "explanation": "为：wéi（第二声），表示“充当、算作”，如“选他为班长”。"}, {"text": "位", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是位置。"}, {"text": "尾", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。"}, {"text": "威", "is_correct": false, "explanation": "wēi（第一声）与 wéi（第二声）声调不同，意思是威力。"}, {"text": "文", "is_correct": false, "explanation": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是文字。"}], "explanations": {"为": "为：wéi（第二声），表示“充当、算作”，如“选他为班长”。", "位": "wèi（第四声）与 wéi（第二声）声调不同，意思是位置。", "尾": "wěi（第三声）与 wéi（第二声）声调不同，意思是尾巴。", "威": "wēi（第一声）与 wéi（第二声）声调不同，意思是威力。", "文": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是文字。"}, "sentence_index": null, "correct_answer": "为"}, "level_3": {"options": [{"text": "为", "is_correct": true, "explanation": "为：表示“充当、担任”，“选他为班长”即选他担任班长。"}, {"text": "有", "is_correct": false, "explanation": "配价：“有”的宾语应是所有物，不能表示担任职务，“选他有班长”不成立。"}, {"text": "管", "is_correct": false, "explanation": "搭配：“管”后接事务或人，“管班长”不能表示任命。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”表示吞咽食物，与“选”和职位无关。"}], "explanations": {"为": "为：表示“充当、担任”，“选他为班长”即选他担任班长。", "有": "配价：“有”的宾语应是所有物，不能表示担任职务，“选他有班长”不成立。", "管": "搭配：“管”后接事务或人，“管班长”不能表示任命。", "吃": "语义：“吃”表示吞咽食物，与“选”和职位无关。"}, "sentence_index": 0, "correct_answer": "为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都为他是好朋友。", "explanation": "这里应该用〈当〉。“为”不能直接引出“他是好朋友”这样的小句；认作要说“当……是……”。"}, {"text": "他为过三年班长。", "explanation": "这里应该用〈担任〉。应说“担任过三年班长”，“为”在这里不能单独表示担任职务，用法不通。"}, {"text": "他为了班长。", "explanation": "这里应该用〈成〉。“为了”表示目的，后面要接动词性成分，不能表示充当某种身份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85662, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "为", "is_correct": true, "explanation": "为：wéi（第二声），表示“充当、算作”，如“聘他为顾问”。"}, {"text": "未", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。"}, {"text": "委", "is_correct": false, "explanation": "wěi（第三声）与 wéi（第二声）声调不同，意思是委托。"}, {"text": "微", "is_correct": false, "explanation": "wēi（第一声）与 wéi（第二声）声调不同，意思是微小。"}, {"text": "闻", "is_correct": false, "explanation": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是听见。"}], "explanations": {"为": "为：wéi（第二声），表示“充当、算作”，如“聘他为顾问”。", "未": "wèi（第四声）与 wéi（第二声）声调不同，意思是还没有。", "委": "wěi（第三声）与 wéi（第二声）声调不同，意思是委托。", "微": "wēi（第一声）与 wéi（第二声）声调不同，意思是微小。", "闻": "wén（第二声）与 wéi（第二声）韵母不同（-en／-ei），意思是听见。"}, "sentence_index": null, "correct_answer": "为"}, "level_3": {"options": [{"text": "为", "is_correct": true, "explanation": "为：表示“充当、担任”，“聘他为顾问”即聘用他担任顾问。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”表示观察，与聘用担任职务无关。"}, {"text": "欠", "is_correct": false, "explanation": "配价：“欠”的宾语应是所欠之物，不能接“顾问”表示任职。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”接物品或人，“送顾问”不能表示聘任。"}], "explanations": {"为": "为：表示“充当、担任”，“聘他为顾问”即聘用他担任顾问。", "看": "语义：“看”表示观察，与聘用担任职务无关。", "欠": "配价：“欠”的宾语应是所欠之物，不能接“顾问”表示任职。", "送": "搭配：“送”接物品或人，“送顾问”不能表示聘任。"}, "sentence_index": 6, "correct_answer": "为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们为朋友吧。", "explanation": "这里应该用〈做〉。“做朋友”表示结为朋友，“为”不能与“朋友”直接组成这样的谓语，句子不通。"}, {"text": "他为班上的同学很多帮助。", "explanation": "这里应该用〈给〉。“给同学很多帮助”表示给予，“为”不能带“帮助”这样的给予宾语。"}, {"text": "我长大以后想为医生。", "explanation": "这里应该用〈当〉。表示将来从事某种职业，口语要说“当医生”，“为”不能这样单独使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把五月一日为定校庆日。", "corrected_sentence": "学校把五月一日定为校庆日。", "error_description": "错误：“为定”，语序颠倒；正确：“定为校庆日”。“为”要放在动词“定”之后，再接身份或名称。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司聘她为经理为。", "corrected_sentence": "公司聘她为经理。", "error_description": "错误：句末多出“为”；正确：“公司聘她为经理”。“聘……为……”中的“为”后面要接职务名称，句末不能再加“为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f311aab-b594-4030-9ae9-d3a3efd6eb03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
