INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85663, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“他”是说一个不在这里的男孩或男人。", "primary_collocate": null, "pronunciation": "tā", "ipa": "tʰa˥", "syllable_count": 1, "sentences": [{"text": "他是我的哥哥。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上六点起床。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的爸爸是医生，他在医院工作。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个男孩是谁？他是我的同学。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天看见他了。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说他想去北京。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给他打了一个电话。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢踢足球。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王今年五十岁，他有两个孩子。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认识他吗？", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "代词他：指不在场的某个男孩或男人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85663, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "塔", "is_correct": false, "explanation": "tǎ（第三声）与 tā（第一声）声调不同，意思是塔。"}, {"text": "他", "is_correct": true, "explanation": "正确：“他”读 tā，指不在场的男性。"}, {"text": "哈", "is_correct": false, "explanation": "hā 与 tā 声母不同（h 与 t），意思是哈，如哈哈。"}, {"text": "搭", "is_correct": false, "explanation": "dā 与 tā 声母不同（不送气的 d 与送气的 t），意思是搭配。"}, {"text": "踏", "is_correct": false, "explanation": "tà（第四声）与 tā 声调不同，意思是踩、踏。"}], "explanations": {"塔": "tǎ（第三声）与 tā（第一声）声调不同，意思是塔。", "他": "正确：“他”读 tā，指不在场的男性。", "哈": "hā 与 tā 声母不同（h 与 t），意思是哈，如哈哈。", "搭": "dā 与 tā 声母不同（不送气的 d 与送气的 t），意思是搭配。", "踏": "tà（第四声）与 tā 声调不同，意思是踩、踏。"}, "sentence_index": null, "correct_answer": "他"}, "level_3": {"options": [{"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人自己，“我是我的哥哥”句意不通。"}, {"text": "他", "is_correct": true, "explanation": "正确：“他”指不在场的男性，“哥哥”是男性亲属。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能指“哥哥”这样的人。"}, {"text": "大家", "is_correct": false, "explanation": "语义：“大家”指多人，单数的“哥哥”不能用“大家”来指代。"}], "explanations": {"我": "语义：“我”指说话人自己，“我是我的哥哥”句意不通。", "他": "正确：“他”指不在场的男性，“哥哥”是男性亲属。", "它": "语义：“它”指物或动物，不能指“哥哥”这样的人。", "大家": "语义：“大家”指多人，单数的“哥哥”不能用“大家”来指代。"}, "sentence_index": 0, "correct_answer": "他"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我的妈妈，他很温柔。", "explanation": "这里应该用〈她〉。他指男性，她指女性，妈妈是女性，不能用〈他〉。"}, {"text": "这本书很好看，他讲了一个故事。", "explanation": "这里应该用〈它〉。它用于物品或非人的事物，书是物，不能用〈他〉。"}, {"text": "这个苹果很甜，他很好吃。", "explanation": "这里应该用〈它〉。他指人，苹果是物，不能用〈他〉指代，应该用〈它〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么", "is_correct": false, "explanation": "语法：“什么”是疑问代词，“我给什么打了一个电话”不成立。"}, {"text": "他", "is_correct": true, "explanation": "正确：“他”指接电话的那位不在场的人。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括说话人和听话人，“给咱们打电话”句意不通。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物，不能作为打电话的对象。"}], "explanations": {"什么": "语法：“什么”是疑问代词，“我给什么打了一个电话”不成立。", "他": "正确：“他”指接电话的那位不在场的人。", "咱们": "语义：“咱们”包括说话人和听话人，“给咱们打电话”句意不通。", "它": "语义：“它”指物，不能作为打电话的对象。"}, "sentence_index": 6, "correct_answer": "他"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我叫小明，我今天很累，他想早点睡觉。", "explanation": "这里应该用〈我〉。“我叫小明”已说明说话人就是小明，再用第三人称〈他〉指自己不对。"}, {"text": "妈妈，他饿了，我想吃饭。", "explanation": "这里应该用〈我〉。说话人说的是自己饿了，不能用第三人称〈他〉。"}, {"text": "这张桌子很大，他是木头做的。", "explanation": "这里应该用〈它〉。桌子是物品，不能用指人的〈他〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的爸爸每天很忙，他的要照顾全家。", "corrected_sentence": "我的爸爸每天很忙，他要照顾全家。", "error_description": "“他的”之后不能直接接动词，多出的“的”造成语法错误，应去掉，写作“他要照顾全家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是他书。", "corrected_sentence": "这是他的书。", "error_description": "表示所属关系时，代词“他”后要加“的”，应写作“他的书”，不能说“他书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
