INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85664, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第三人称代词，指称说话双方以外的男性，也泛指不分性别的某个人。", "primary_collocate": null, "pronunciation": "tā", "ipa": "tʰa˥", "syllable_count": 1, "sentences": [{"text": "他在大学教书。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁想去，他就举手。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人在门口，你问问他找谁。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟很高，他今年十六岁。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天没来上课。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人再忙，他也要休息。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太认识他。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位先生姓王，他是我们的经理。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁做错了，他就要说对不起。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最近一直在学做饭。", "target_word": "他", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "第三人称代词他：指男性，也泛指不分性别的某个人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63681715-008c-4ce4-9cde-53c69200fb5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85664, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "他", "is_correct": true, "explanation": "他（tā，第一声）是第三人称代词，指男性，也可泛指某人。"}, {"text": "塔", "is_correct": false, "explanation": "塔（tǎ，第三声）与“他”声调不同，意思是塔楼。"}, {"text": "搭", "is_correct": false, "explanation": "搭（dā）与“他”声母不同（d 与 t），意思是搭乘、搭建。"}, {"text": "汤", "is_correct": false, "explanation": "汤（tāng）与“他”韵母不同（ang 与 a），意思是汤。"}, {"text": "踏", "is_correct": false, "explanation": "踏（tà，第四声）与“他”声调不同，意思是踩。"}], "explanations": {"他": "他（tā，第一声）是第三人称代词，指男性，也可泛指某人。", "塔": "塔（tǎ，第三声）与“他”声调不同，意思是塔楼。", "搭": "搭（dā）与“他”声母不同（d 与 t），意思是搭乘、搭建。", "汤": "汤（tāng）与“他”韵母不同（ang 与 a），意思是汤。", "踏": "踏（tà，第四声）与“他”声调不同，意思是踩。"}, "sentence_index": null, "correct_answer": "他"}, "level_3": {"options": [{"text": "他", "is_correct": true, "explanation": "“他”是第三人称男性代词，作主语指不在场的一位男性，句意通顺。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，句子会变成问句，不能用作陈述句的主语。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”需要句中有先行词，这句没有，“自己在大学教书”句意不通。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指物或动物，不能做“在大学教书”的主语。"}], "explanations": {"他": "“他”是第三人称男性代词，作主语指不在场的一位男性，句意通顺。", "谁": "语义：“谁”是疑问代词，句子会变成问句，不能用作陈述句的主语。", "自己": "语义：“自己”需要句中有先行词，这句没有，“自己在大学教书”句意不通。", "它": "语义：“它”指物或动物，不能做“在大学教书”的主语。"}, "sentence_index": 0, "correct_answer": "他"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我姐姐很漂亮，他今年二十岁。", "explanation": "这里应该用〈她〉。“他”只指男性，这里说的是姐姐，要用“她”。"}, {"text": "这本书很厚，他的价格是五十块。", "explanation": "这里应该用〈它〉。“他”只指人，指物品时要用“它”。"}, {"text": "这几个女孩子都很活泼，他每天都笑个不停。", "explanation": "这里应该用〈她们〉。“他”只指一个男性，指几位女性要用“她们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85664, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "他", "is_correct": true, "explanation": "他（tā，第一声）是第三人称代词，指男性，也可泛指某人。"}, {"text": "摊", "is_correct": false, "explanation": "摊（tān）与“他”韵母不同（an 与 a），意思是摊位、摊开。"}, {"text": "胎", "is_correct": false, "explanation": "胎（tāi）与“他”韵母不同（ai 与 a），意思是轮胎。"}, {"text": "掏", "is_correct": false, "explanation": "掏（tāo）与“他”韵母不同（ao 与 a），意思是掏出。"}, {"text": "拉", "is_correct": false, "explanation": "拉（lā）与“他”声母不同（l 与 t），意思是拉动。"}], "explanations": {"他": "他（tā，第一声）是第三人称代词，指男性，也可泛指某人。", "摊": "摊（tān）与“他”韵母不同（an 与 a），意思是摊位、摊开。", "胎": "胎（tāi）与“他”韵母不同（ai 与 a），意思是轮胎。", "掏": "掏（tāo）与“他”韵母不同（ao 与 a），意思是掏出。", "拉": "拉（lā）与“他”声母不同（l 与 t），意思是拉动。"}, "sentence_index": null, "correct_answer": "他"}, "level_3": {"options": [{"text": "他", "is_correct": true, "explanation": "“他”指不在场的第三者，作“认识”的宾语，句意通顺。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我不太认识我”的认识对象是说话人自己，句意不通。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我不太认识我们”把说话人自己也算作认识的对象，句意不通。"}, {"text": "咱们", "is_correct": false, "explanation": "语域：“咱们”是口语，且包括听话人，与“我不太认识”的说法矛盾。"}], "explanations": {"他": "“他”指不在场的第三者，作“认识”的宾语，句意通顺。", "我": "语义：“我不太认识我”的认识对象是说话人自己，句意不通。", "我们": "语义：“我不太认识我们”把说话人自己也算作认识的对象，句意不通。", "咱们": "语域：“咱们”是口语，且包括听话人，与“我不太认识”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "他"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对朋友说：“他，这个办法怎么样？”", "explanation": "这里应该用〈你〉。对面前的朋友说话要用“你”，“他”只指第三者，不能直接称呼对方。"}, {"text": "王老师，他，最近身体好吗？", "explanation": "这里应该用〈您〉。对面前的老师问候要用“您”表示尊敬，“他”只指第三者。"}, {"text": "同学们，他现在开始上课。", "explanation": "这里应该用〈我〉。老师指自己时要说“我”，不能把自己说成“他”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a142997-6639-43e5-9a02-e3c48c844491') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLU