INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85666, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指示较近的人、事物、时间或地点。", "primary_collocate": null, "pronunciation": "zhè", "ipa": "ʈʂɤ˥˩", "syllable_count": 1, "sentences": [{"text": "这是我的书。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这是什么？", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的菜很好吃。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题我不懂。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我朋友小王。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服太大了。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这个地方。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这杯茶是我的，那杯是你的。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路很长，我们慢慢走。", "target_word": "这", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "这个", "label": "复合"}, {"form": "这些", "label": "复合"}, {"form": "这里", "label": "复合"}], "register": "中性", "sense_fingerprint": "指示代词，指较近的人或事物，与“那”相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f511cdf7-32fc-4ebd-97bd-19cfb744bda7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85666, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "这", "is_correct": true, "explanation": "这：指示较近的人、事物、时间或地点，与听到的读音一致。"}, {"text": "折", "is_correct": false, "explanation": "zhé（第二声）与 zhè（第四声）声调不同，意思是折断。"}, {"text": "设", "is_correct": false, "explanation": "shè 与 zhè 声母不同（sh 与 zh），意思是设计。"}, {"text": "撤", "is_correct": false, "explanation": "chè 与 zhè 声母不同（ch 与 zh），意思是撤退。"}], "explanations": {"这": "这：指示较近的人、事物、时间或地点，与听到的读音一致。", "折": "zhé（第二声）与 zhè（第四声）声调不同，意思是折断。", "设": "shè 与 zhè 声母不同（sh 与 zh），意思是设计。", "撤": "chè 与 zhè 声母不同（ch 与 zh），意思是撤退。"}, "sentence_index": null, "correct_answer": "这"}, "level_3": {"options": [{"text": "这", "is_correct": true, "explanation": "这：指示较近的事物，与“是我的书”搭配，符合句意。"}, {"text": "他", "is_correct": false, "explanation": "搭配：“他”指人，不能用来指代一本书。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，不能用于陈述句指代书。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指人自身，不能说自己是一本书。"}], "explanations": {"这": "这：指示较近的事物，与“是我的书”搭配，符合句意。", "他": "搭配：“他”指人，不能用来指代一本书。", "谁": "语义：“谁”是疑问代词，不能用于陈述句指代书。", "自己": "语义：“自己”指人自身，不能说自己是一本书。"}, "sentence_index": 0, "correct_answer": "这"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "远处这棵树很高。", "explanation": "这里应该用〈那棵〉。“远处”说明距离很远，要用“那”，“这”只指较近的事物。"}, {"text": "这年我才三岁，现在我已经上大学了。", "explanation": "这里应该用〈那年〉。说很久以前的一年要用“那”，“这年”指说话时的这一年。"}, {"text": "这颗很远的星星在几亿光年以外，我们看不清楚它。", "explanation": "这里应该用〈那颗〉。“这颗”指离说话人近的东西，很远的星星要用“那颗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85666, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "这", "is_correct": true, "explanation": "这：指示较近的人、事物、时间或地点，与听到的读音一致。"}, {"text": "遮", "is_correct": false, "explanation": "zhē（第一声）与 zhè（第四声）声调不同，意思是遮挡。"}, {"text": "哲", "is_correct": false, "explanation": "zhé（第二声）与 zhè（第四声）声调不同，意思是哲学。"}, {"text": "社", "is_correct": false, "explanation": "shè 与 zhè 声母不同（sh 与 zh），意思是社会或社团。"}], "explanations": {"这": "这：指示较近的人、事物、时间或地点，与听到的读音一致。", "遮": "zhē（第一声）与 zhè（第四声）声调不同，意思是遮挡。", "哲": "zhé（第二声）与 zhè（第四声）声调不同，意思是哲学。", "社": "shè 与 zhè 声母不同（sh 与 zh），意思是社会或社团。"}, "sentence_index": null, "correct_answer": "这"}, "level_3": {"options": [{"text": "这", "is_correct": true, "explanation": "这：指示较近的衣服，与“太大了”的语境相符。"}, {"text": "哪", "is_correct": false, "explanation": "语义：“哪”是疑问代词，陈述句中不能指示一件具体的衣服。"}, {"text": "它", "is_correct": false, "explanation": "语法：“它”是人称代词，不能直接加量词“件”修饰名词。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是副词，不能放在量词“件”前面。"}], "explanations": {"这": "这：指示较近的衣服，与“太大了”的语境相符。", "哪": "语义：“哪”是疑问代词，陈述句中不能指示一件具体的衣服。", "它": "语法：“它”是人称代词，不能直接加量词“件”修饰名词。", "很": "语法：“很”是副词，不能放在量词“件”前面。"}, "sentence_index": 6, "correct_answer": "这"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的老家在很远的这个小村里。", "explanation": "这里应该用〈那个〉。“很远”说明离说话人远，要用“那”，“这”只指附近的地方。"}, {"text": "这段日子是十年前的事了。", "explanation": "这里应该用〈那段〉。“这段”指说话时近的一段时间，十年前的日子要用“那段”。"}, {"text": "天边这一头有一座山。", "explanation": "这里应该用〈那一头〉。“天边”指很远的地方，要用“那”，“这一头”指说话人附近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85666, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些本书很有意思。", "corrected_sentence": "这些书很有意思。", "error_description": "错误在“这些本”。“这些”后面直接接名词，不再加量词“本”。错误：这些本书很有意思。正确：这些书很有意思。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85666, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个些问题我不懂。", "corrected_sentence": "这些问题我不懂。", "error_description": "错误在“这个些”。“这个”指一个，“这些”指多个，不能连用。错误：这个些问题我不懂。正确：这些问题我不懂。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44062afd-5b26-4dac-bfa0-894fc3a5bb16') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
