INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85667, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "“中”是说在一个东西的里面，或者在两边的中间。", "primary_collocate": null, "pronunciation": "zhōng", "ipa": "ʈʂʊŋ˥", "syllable_count": 1, "sentences": [{"text": "我把钥匙放在包中。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鱼在杯子中游来游去。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在汤中放了一点盐。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中有一张小照片。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把信藏在抽屉中，没有告诉任何人。", "target_word": "中", "complexity_tier": "T3", "furigana": "zhōng", "sentence_source": "generated"}, {"text": "水果在盒子中，你自己拿吧。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在人群中找到了朋友。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把名字写在表格中。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手中拿着一杯茶。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在湖水中玩了一下午。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "方位词：在某物里面或两端中间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85667, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中", "is_correct": true, "explanation": "zhōng（第一声）即“中”，指在某物的里面或两端之间。"}, {"text": "重", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng 声调不同，意思是重量、重要。"}, {"text": "众", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng 声调不同，意思是众多。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhōng 韵母不同（-ang 与 -ong），意思是张开。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 zhōng 韵母不同（-eng 与 -ong），意思是争夺。"}, {"text": "种", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng 声调不同，意思是种子。"}], "explanations": {"中": "zhōng（第一声）即“中”，指在某物的里面或两端之间。", "重": "zhòng（第四声）与 zhōng 声调不同，意思是重量、重要。", "众": "zhòng（第四声）与 zhōng 声调不同，意思是众多。", "张": "zhāng 与 zhōng 韵母不同（-ang 与 -ong），意思是张开。", "争": "zhēng 与 zhōng 韵母不同（-eng 与 -ong），意思是争夺。", "种": "zhǒng（第三声）与 zhōng 声调不同，意思是种子。"}, "sentence_index": null, "correct_answer": "中"}, "level_3": {"options": [{"text": "中", "is_correct": true, "explanation": "正确。“中”指在包的里面，与“放在包中”的意思相合。"}, {"text": "时", "is_correct": false, "explanation": "语法：“时”表示时间，“放在包时”不能表示放东西的位置。"}, {"text": "以前", "is_correct": false, "explanation": "语法：“以前”表示时间，“放在包以前”说不通。"}, {"text": "之间", "is_correct": false, "explanation": "搭配：“之间”需要两个或以上的对象，“包”只是一个东西，不能说“包之间”。"}], "explanations": {"中": "正确。“中”指在包的里面，与“放在包中”的意思相合。", "时": "语法：“时”表示时间，“放在包时”不能表示放东西的位置。", "以前": "语法：“以前”表示时间，“放在包以前”说不通。", "之间": "搭配：“之间”需要两个或以上的对象，“包”只是一个东西，不能说“包之间”。"}, "sentence_index": 0, "correct_answer": "中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子中放着一本书。", "explanation": "这里应该用〈上〉。桌面是物体的表面，“中”指在某物的里面，不能说“桌子中”。"}, {"text": "他把钥匙放进我中。", "explanation": "这里应该用〈口袋〉。“中”指在某物的里面，人身不是可以装东西的范围，装钥匙要说〈口袋〉，不能说“我中”。"}, {"text": "墙中挂着一幅画。", "explanation": "这里应该用〈上〉。画挂在墙的表面，“中”指在某物的里面，不能说“墙中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85667, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "中", "is_correct": true, "explanation": "zhōng（第一声）即“中”，指在某物的里面或两端之间。"}, {"text": "冲", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch 与 zh），意思是冲洗。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d 与 zh），意思是东方。"}, {"text": "通", "is_correct": false, "explanation": "tōng 与 zhōng 声母不同（t 与 zh），意思是通过。"}], "explanations": {"中": "zhōng（第一声）即“中”，指在某物的里面或两端之间。", "冲": "chōng 与 zhōng 声母不同（ch 与 zh），意思是冲洗。", "东": "dōng 与 zhōng 声母不同（d 与 zh），意思是东方。", "通": "tōng 与 zhōng 声母不同（t 与 zh），意思是通过。"}, "sentence_index": null, "correct_answer": "中"}, "level_3": {"options": [{"text": "中", "is_correct": true, "explanation": "正确。“中”指在人群的内部，与“找到朋友”发生在人群之中相合。"}, {"text": "时", "is_correct": false, "explanation": "语法：“时”表示时间，“在人群时”说不通。"}, {"text": "以后", "is_correct": false, "explanation": "语法：“以后”表示时间，“在人群以后”说不通。"}, {"text": "下面", "is_correct": false, "explanation": "搭配：“下面”指位置在下方，不能用来指人群的内部范围。"}], "explanations": {"中": "正确。“中”指在人群的内部，与“找到朋友”发生在人群之中相合。", "时": "语法：“时”表示时间，“在人群时”说不通。", "以后": "语法：“以后”表示时间，“在人群以后”说不通。", "下面": "搭配：“下面”指位置在下方，不能用来指人群的内部范围。"}, "sentence_index": 6, "correct_answer": "中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我站在柱子中，等你来。", "explanation": "这里应该用〈旁边〉。“中”指在某物的内部，柱子是实体，人站在它的一侧要说〈旁边〉，不能说“柱子中”。"}, {"text": "他躺在床中，看着窗外。", "explanation": "这里应该用〈上〉。人躺在床的表面，“中”指在某物的里面，不能说“床中”。"}, {"text": "明天中，我们要去北京。", "explanation": "这里不能用〈中〉。“中”指在某个范围之内，“明天”只是一个时间点，应直接说“明天”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85667, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把书放在抽屉中里。", "corrected_sentence": "他把书放在抽屉中。", "error_description": "错误：“中”后又加了“里”，形成“中里”的重复。“中”本身已表示在……里面，应说“放在抽屉中”或“放在抽屉里”，不说“中里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85667, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我书架中找到了一本书。", "corrected_sentence": "我在书架中找到了一本书。", "error_description": "错误：“书架中”前漏了介词“在”。“在……中”是一个整体的地点结构，应说“我在书架中找到了一本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
