INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85668, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "方位词，表示在一定范围或过程之内。", "primary_collocate": null, "pronunciation": "zhōng", "ipa": "ʈʂʊŋ˥", "syllable_count": 1, "sentences": [{"text": "在学习中，他学会了很多。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这五个人中，他最高。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在比赛中，她一直很努力。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在两个办法中，我选第一个。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在生活中遇到过很多问题。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在三天的旅行中，我们玩得很高兴。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在工作中，我们要互相帮助。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这些书中，我最喜欢这本。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在跑步中，他认识了很多朋友。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在游戏中学会了合作。", "target_word": "中", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "方位词：在一定范围、过程之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '090b0596-03c6-49fa-9960-4cdd5ded62a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85668, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "中", "is_correct": true, "explanation": "zhōng（第一声）即“中”，表示在一定范围、过程之内。"}, {"text": "重", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng 声调不同，意思是重量、重要。"}, {"text": "众", "is_correct": false, "explanation": "zhòng（第四声）与 zhōng 声调不同，意思是众多。"}, {"text": "张", "is_correct": false, "explanation": "zhāng 与 zhōng 韵母不同（-ang 与 -ong），意思是张开。"}, {"text": "争", "is_correct": false, "explanation": "zhēng 与 zhōng 韵母不同（-eng 与 -ong），意思是争夺。"}, {"text": "种", "is_correct": false, "explanation": "zhǒng（第三声）与 zhōng 声调不同，意思是种子。"}], "explanations": {"中": "zhōng（第一声）即“中”，表示在一定范围、过程之内。", "重": "zhòng（第四声）与 zhōng 声调不同，意思是重量、重要。", "众": "zhòng（第四声）与 zhōng 声调不同，意思是众多。", "张": "zhāng 与 zhōng 韵母不同（-ang 与 -ong），意思是张开。", "争": "zhēng 与 zhōng 韵母不同（-eng 与 -ong），意思是争夺。", "种": "zhǒng（第三声）与 zhōng 声调不同，意思是种子。"}, "sentence_index": null, "correct_answer": "中"}, "level_3": {"options": [{"text": "中", "is_correct": true, "explanation": "正确。“中”表示在学习这一过程之内，与句意相合。"}, {"text": "对面", "is_correct": false, "explanation": "搭配：“对面”是空间位置，“学习对面”不能指学习的过程。"}, {"text": "外", "is_correct": false, "explanation": "搭配：“外”需要带“之”构成“之外”，单说“学习外”不成词组。"}, {"text": "下", "is_correct": false, "explanation": "搭配：“在……下”多用于条件或指导，“学习下”不构成这一用法。"}], "explanations": {"中": "正确。“中”表示在学习这一过程之内，与句意相合。", "对面": "搭配：“对面”是空间位置，“学习对面”不能指学习的过程。", "外": "搭配：“外”需要带“之”构成“之外”，单说“学习外”不成词组。", "下": "搭配：“在……下”多用于条件或指导，“学习下”不构成这一用法。"}, "sentence_index": 0, "correct_answer": "中"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在三点中，大家都到了。", "explanation": "这里应该用〈时〉。“中”表示一段范围之内，“三点”只是一个时间点，不能用“中”来限定。"}, {"text": "在他中，有一个秘密。", "explanation": "这里应该用〈心中〉。“中”指一定范围之内，人本身不是可以容纳东西的范围，应说“他的心中”，不能说“在他中”。"}, {"text": "在墙角中，站着一个人。", "explanation": "这里应该用〈旁边〉。人站在墙角的一侧，是在旁边的位置，“中”指一定范围之内，不能说“墙角中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85668, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "中", "is_correct": true, "explanation": "zhōng（第一声）即“中”，表示在一定范围、过程之内。"}, {"text": "冲", "is_correct": false, "explanation": "chōng 与 zhōng 声母不同（ch 与 zh），意思是冲洗。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 zhōng 声母不同（d 与 zh），意思是东方。"}, {"text": "通", "is_correct": false, "explanation": "tōng 与 zhōng 声母不同（t 与 zh），意思是通过。"}, {"text": "同", "is_correct": false, "explanation": "tóng（第二声）与 zhōng 声调不同，意思是相同。"}], "explanations": {"中": "zhōng（第一声）即“中”，表示在一定范围、过程之内。", "冲": "chōng 与 zhōng 声母不同（ch 与 zh），意思是冲洗。", "东": "dōng 与 zhōng 声母不同（d 与 zh），意思是东方。", "通": "tōng 与 zhōng 声母不同（t 与 zh），意思是通过。", "同": "tóng（第二声）与 zhōng 声调不同，意思是相同。"}, "sentence_index": null, "correct_answer": "中"}, "level_3": {"options": [{"text": "中", "is_correct": true, "explanation": "正确。“中”表示在工作这一过程之内，与句意相合。"}, {"text": "旁边", "is_correct": false, "explanation": "搭配：“旁边”是空间位置，“工作旁边”不能指工作的过程或范围。"}, {"text": "下面", "is_correct": false, "explanation": "搭配：“下面”指下方位置，“工作下面”不能指工作的过程。"}, {"text": "对面", "is_correct": false, "explanation": "搭配：“对面”指相对的一方，不能说“工作对面”。"}], "explanations": {"中": "正确。“中”表示在工作这一过程之内，与句意相合。", "旁边": "搭配：“旁边”是空间位置，“工作旁边”不能指工作的过程或范围。", "下面": "搭配：“下面”指下方位置，“工作下面”不能指工作的过程。", "对面": "搭配：“对面”指相对的一方，不能说“工作对面”。"}, "sentence_index": 6, "correct_answer": "中"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在桌底中，藏着一只猫。", "explanation": "这里应该用〈桌下〉。“中”指在一定范围之内，猫藏在桌子的下方，不能把“桌底”当作范围说“中”。"}, {"text": "在饭前中，我们洗了手。", "explanation": "这里应该用〈之前〉。“饭前”是一个时间点，“中”表示范围之内，不能与时间点搭配，应说“吃饭之前”。"}, {"text": "在窗户中贴了一张画。", "explanation": "这里应该用〈上〉。画贴在窗户的表面，“中”指在某物的里面，不能说“窗户中”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在这次活动的中，大家都很开心。", "corrected_sentence": "在这次活动中，大家都很开心。", "error_description": "错误：“中”前多了“的”。“在……中”结构中，“中”应直接接在名词后，应说“在这次活动中”，不能说“在这次活动的中”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在这次训练中里，我们学到了很多。", "corrected_sentence": "在这次训练中，我们学到了很多。", "error_description": "错误：“中”后又加“里”，重复。“在……中”已表示范围之内，应说“在这次训练中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27c0647a-b367-4c12-8b85-e3aa674d2dbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
