INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85670, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "时间单位，地球绕太阳公转一周的时间，通常指从一月一日到十二月三十一日的一段时间。", "primary_collocate": null, "pronunciation": "nián", "ipa": "njɛn˧˥", "syllable_count": 1, "sentences": [{"text": "我是一九九八年生的。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一年从一月一日开始。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的一年开始了，我有新计划。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一月一日是一年的第一天。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的人口一年比一年多。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二〇二四年有三百六十六天。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一九九〇年来到中国。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年有十二个月。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一年的冬天特别冷。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年里我去了两次上海。", "target_word": "年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年年", "label": "重叠"}, {"form": "年份", "label": "复合"}], "register": "通用", "sense_fingerprint": "从一月一日到十二月三十一日的日历年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 5 above tier T1: 4 words above tier T1 (max 2): 〇 (Zipf 3.69), 三百 (Zipf 3.89), 六十 (Zipf 3.85), 六天 (Zipf 3.4)']::text[], 'e8b19119-d89a-436b-a0df-53ddddc827e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85670, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "年", "is_correct": true, "explanation": "年 nián：日历上的一年，是本题正确答案。"}, {"text": "连", "is_correct": false, "explanation": "连 lián 与 nián 声母不同（l 与 n），意思是连接。"}, {"text": "蔫", "is_correct": false, "explanation": "蔫 niān 与 nián 声调不同（第一声与第二声），意思是植物失去水分而萎缩。"}, {"text": "念", "is_correct": false, "explanation": "念 niàn 与 nián 声调不同（第四声与第二声），意思是朗读。"}], "explanations": {"年": "年 nián：日历上的一年，是本题正确答案。", "连": "连 lián 与 nián 声母不同（l 与 n），意思是连接。", "蔫": "蔫 niān 与 nián 声调不同（第一声与第二声），意思是植物失去水分而萎缩。", "念": "念 niàn 与 nián 声调不同（第四声与第二声），意思是朗读。"}, "sentence_index": null, "correct_answer": "年"}, "level_3": {"options": [{"text": "岁", "is_correct": false, "explanation": "语义：“岁”指年龄，这里说的是出生的年份，不能用“岁”。"}, {"text": "年", "is_correct": true, "explanation": "年：正确答案，“一九九八年”是年份的标准说法。"}, {"text": "月", "is_correct": false, "explanation": "搭配：年份后面不能直接接“月”，要说“某年某月”。"}, {"text": "号", "is_correct": false, "explanation": "语义：“号”指日期中的“日”，不能接在年份后面。"}], "explanations": {"岁": "语义：“岁”指年龄，这里说的是出生的年份，不能用“岁”。", "年": "年：正确答案，“一九九八年”是年份的标准说法。", "月": "搭配：年份后面不能直接接“月”，要说“某年某月”。", "号": "语义：“号”指日期中的“日”，不能接在年份后面。"}, "sentence_index": 0, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议的年定在下午三点。", "explanation": "这里应该用〈时间〉。“年”指一年这段时间，不能用来表示一天中的钟点，会议的时间要说“时间”。"}, {"text": "春天是一年中最美的年。", "explanation": "这里应该用〈季节〉。“年”是时间单位，不能指春天这样的季节。"}, {"text": "我们年五见面。", "explanation": "这里应该用〈星期〉。“年”不能用在表示星期几的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85670, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "年", "is_correct": true, "explanation": "年 nián：日历上的一年，是本题正确答案。"}, {"text": "联", "is_correct": false, "explanation": "联 lián 与 nián 声母不同（l 与 n），意思是联系。"}, {"text": "粘", "is_correct": false, "explanation": "粘 niān 与 nián 声调不同（第一声与第二声），意思是用胶把东西粘在一起。"}, {"text": "碾", "is_correct": false, "explanation": "碾 niǎn 与 nián 声调不同（第三声与第二声），意思是用碾子压。"}], "explanations": {"年": "年 nián：日历上的一年，是本题正确答案。", "联": "联 lián 与 nián 声母不同（l 与 n），意思是联系。", "粘": "粘 niān 与 nián 声调不同（第一声与第二声），意思是用胶把东西粘在一起。", "碾": "碾 niǎn 与 nián 声调不同（第三声与第二声），意思是用碾子压。"}, "sentence_index": null, "correct_answer": "年"}, "level_3": {"options": [{"text": "日", "is_correct": false, "explanation": "语义：“日”指具体的某一天，年份后面不能直接接“日”。"}, {"text": "年", "is_correct": true, "explanation": "年：正确答案，“一九九〇年”是年份的标准说法。"}, {"text": "春", "is_correct": false, "explanation": "语义：“春”指季节，不能接在年份后面。"}, {"text": "时", "is_correct": false, "explanation": "搭配：“时”指小时或时刻，年份后面不能接“时”。"}], "explanations": {"日": "语义：“日”指具体的某一天，年份后面不能直接接“日”。", "年": "年：正确答案，“一九九〇年”是年份的标准说法。", "春": "语义：“春”指季节，不能接在年份后面。", "时": "搭配：“时”指小时或时刻，年份后面不能接“时”。"}, "sentence_index": 6, "correct_answer": "年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的年是两百块。", "explanation": "这里应该用〈价格〉。“年”指一段时间，不能用来表示价钱，衣服的价钱要说“价格”。"}, {"text": "我今年十八年。", "explanation": "这里应该用〈岁〉。表示年龄要用“岁”，“年”不表示年龄。"}, {"text": "我坐高铁两年到上海。", "explanation": "这里应该用〈钟头〉。路上花的时间用“钟头”表示，“年”不能用于路程耗时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85670, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的妹妹在一九九九个年出生。", "corrected_sentence": "我的妹妹在一九九九年出生。", "error_description": "错误：“个”；正确：去掉“个”。年份后面的“年”前面不加量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85670, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她二〇一五岁去了上海。", "corrected_sentence": "她二〇一五年去了上海。", "error_description": "错误：“岁”；正确：“年”。表示年份要用“年”，“岁”表示年龄，不能放在年份数字后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5386a762-7b32-4110-b8c7-1a768f13dace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
