INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85671, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“与”和“和”差不多，可以把两个人或两样东西连在一起。", "primary_collocate": null, "pronunciation": "yǔ", "ipa": "y˨˩˦", "syllable_count": 1, "sentences": [{"text": "苹果与香蕉都很好吃。", "target_word": "与", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸与妈妈今天都在家。", "target_word": "与", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有书与笔。", "target_word": "与", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京与上海是中国的大城市。", "target_word": "与", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢音乐与电影。", "target_word": "与", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明与小红是同班同学。", "target_word": "与", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天与秋天的天气都很好。", "target_word": "与", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "中文与英文我都在学。", "target_word": "与", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "房间里的桌子与椅子都是新的。", "target_word": "与", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生与护士都在忙。", "target_word": "与", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "與", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "连接两个并列的人或事物，用法同“和”，比“和”更书面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85671, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "与", "is_correct": true, "explanation": "与（yǔ）是本题的词，连接两个并列的人或事物，用法同“和”。"}, {"text": "鱼", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，yú 的意思是鱼。"}, {"text": "玉", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，yù 的意思是玉石。"}, {"text": "女", "is_correct": false, "explanation": "yǔ 与 nǚ 声母不同（y 与 n），nǚ 的意思是女性。"}, {"text": "旅", "is_correct": false, "explanation": "yǔ 与 lǚ 声母不同（y 与 l），lǚ 的意思是旅行。"}], "explanations": {"与": "与（yǔ）是本题的词，连接两个并列的人或事物，用法同“和”。", "鱼": "yǔ（第三声）与 yú（第二声）声调不同，yú 的意思是鱼。", "玉": "yǔ（第三声）与 yù（第四声）声调不同，yù 的意思是玉石。", "女": "yǔ 与 nǚ 声母不同（y 与 n），nǚ 的意思是女性。", "旅": "yǔ 与 lǚ 声母不同（y 与 l），lǚ 的意思是旅行。"}, "sentence_index": null, "correct_answer": "与"}, "level_3": {"options": [{"text": "与", "is_correct": true, "explanation": "正确。“与”连接并列的“苹果”和“香蕉”，符合“都”的并列语境。"}, {"text": "但", "is_correct": false, "explanation": "语义：“但”表示转折，与“都很好吃”所表达的并列关系矛盾。"}, {"text": "因为", "is_correct": false, "explanation": "搭配：“因为”引出原因分句，不能直接连接“苹果”和“香蕉”。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，句子只是说两者都很好吃，没有转折关系。"}], "explanations": {"与": "正确。“与”连接并列的“苹果”和“香蕉”，符合“都”的并列语境。", "但": "语义：“但”表示转折，与“都很好吃”所表达的并列关系矛盾。", "因为": "搭配：“因为”引出原因分句，不能直接连接“苹果”和“香蕉”。", "然而": "语义：“然而”表示转折，句子只是说两者都很好吃，没有转折关系。"}, "sentence_index": 0, "correct_answer": "与"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我与去了北京。", "explanation": "错在词性不同：“与”连接的两项须同类，名词“我”与动词短语“去了北京”不能并列。"}, {"text": "他买了与苹果。", "explanation": "错在结构：“与”须连接两个同类的名词性成分，此处“买了”是动词，无法与“苹果”并列。"}, {"text": "书与在桌子上。", "explanation": "错在词性不同：名词“书”与介词短语“在桌子上”不能并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85671, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "与", "is_correct": true, "explanation": "与（yǔ）是本题的词，连接两个并列的人或事物，用法同“和”。"}, {"text": "渔", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，yú 的意思是捕鱼。"}, {"text": "愚", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，yú 的意思是愚蠢。"}, {"text": "举", "is_correct": false, "explanation": "yǔ 与 jǔ 声母不同（y 与 j），jǔ 的意思是抬起。"}, {"text": "取", "is_correct": false, "explanation": "yǔ 与 qǔ 声母不同（y 与 q），qǔ 的意思是拿取。"}], "explanations": {"与": "与（yǔ）是本题的词，连接两个并列的人或事物，用法同“和”。", "渔": "yǔ（第三声）与 yú（第二声）声调不同，yú 的意思是捕鱼。", "愚": "yǔ（第三声）与 yú（第二声）声调不同，yú 的意思是愚蠢。", "举": "yǔ 与 jǔ 声母不同（y 与 j），jǔ 的意思是抬起。", "取": "yǔ 与 qǔ 声母不同（y 与 q），qǔ 的意思是拿取。"}, "sentence_index": null, "correct_answer": "与"}, "level_3": {"options": [{"text": "与", "is_correct": true, "explanation": "正确。“与”连接并列的“春天”和“秋天”，符合“都”的并列语境。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，句子只是在说两个季节的天气都很好，没有因果关系。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”连接并列的动作或分句，不能连接两个名词“春天”和“秋天”。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，与“天气都很好”的并列描述不符。"}], "explanations": {"与": "正确。“与”连接并列的“春天”和“秋天”，符合“都”的并列语境。", "所以": "语义：“所以”表示因果，句子只是在说两个季节的天气都很好，没有因果关系。", "并且": "搭配：“并且”连接并列的动作或分句，不能连接两个名词“春天”和“秋天”。", "因此": "语义：“因此”表示结果，与“天气都很好”的并列描述不符。"}, "sentence_index": 6, "correct_answer": "与"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌子与上有书。", "explanation": "错在词性不同：名词“桌子”与方位词“上”不能并列，应写作“桌子上有书”。"}, {"text": "我喜欢与。", "explanation": "错在缺项：“与”后面缺少并列的第二项，无法连接两个成分。"}, {"text": "他跑与快。", "explanation": "错在词性不同：动词“跑”与形容词“快”不能用“与”并列。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我与与妈妈都在家。", "corrected_sentence": "我与妈妈都在家。", "error_description": "“与”重复出现，多了一个连词。正确形式为“我与妈妈都在家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我他与都是中国人。", "corrected_sentence": "我与他都是中国人。", "error_description": "“与”应放在两个并列成分之间。“他与都”把“与”放在“都”前，语序错误，正确为“我与他都是中国人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
