INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85674, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，引出态度、影响或看法所针对的对象。", "primary_collocate": null, "pronunciation": "duì", "ipa": "tweɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "他对音乐很感兴趣。", "target_word": "对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈对我很好。", "target_word": "对", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃糖太多对牙不好。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这个问题有一个想法。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生很认真。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的工作很满意。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喝咖啡对身体有好处吗？", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这里的天气不太习惯。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对新同事很客气。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动对健康很重要。", "target_word": "对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "对：引出态度、影响或看法所针对的对象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e424837-2e8c-4c86-b782-2097d65b46d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85674, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对", "is_correct": true, "explanation": "对（duì）：介词，引出态度、影响或看法所针对的对象。"}, {"text": "碎", "is_correct": false, "explanation": "碎（suì）与对（duì）声母不同（s 与 d），意思是破碎。"}, {"text": "脆", "is_correct": false, "explanation": "脆（cuì）与对（duì）声母不同（c 与 d），意思是容易折断。"}, {"text": "罪", "is_correct": false, "explanation": "罪（zuì）与对（duì）声母不同（z 与 d），意思是罪过。"}], "explanations": {"对": "对（duì）：介词，引出态度、影响或看法所针对的对象。", "碎": "碎（suì）与对（duì）声母不同（s 与 d），意思是破碎。", "脆": "脆（cuì）与对（duì）声母不同（c 与 d），意思是容易折断。", "罪": "罪（zuì）与对（duì）声母不同（z 与 d），意思是罪过。"}, "sentence_index": null, "correct_answer": "对"}, "level_3": {"options": [{"text": "对", "is_correct": true, "explanation": "对：引出感兴趣的对象，“对音乐很感兴趣”是固定说法。"}, {"text": "从", "is_correct": false, "explanation": "配价：“感兴趣”的对象要用“对”引出，不能用“从”。"}, {"text": "向", "is_correct": false, "explanation": "配价：“感兴趣”不接“向”引出的对象，应用“对”。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替，“替音乐感兴趣”说不通。"}], "explanations": {"对": "对：引出感兴趣的对象，“对音乐很感兴趣”是固定说法。", "从": "配价：“感兴趣”的对象要用“对”引出，不能用“从”。", "向": "配价：“感兴趣”不接“向”引出的对象，应用“对”。", "替": "语义：“替”表示代替，“替音乐感兴趣”说不通。"}, "sentence_index": 0, "correct_answer": "对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我对他借了一支笔。", "explanation": "这里应该用〈向〉。“对”引出态度或看法针对的对象，不能表示借东西的来源。"}, {"text": "我对说明书操作了机器。", "explanation": "这里应该用〈按照〉。“对”引出态度或看法的对象，不能表示依据，应说“按照说明书操作了机器”。"}, {"text": "我对五点有一个约会。", "explanation": "这里应该用〈在〉。“对”只能引出人或事物，不能引出时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85674, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "对", "is_correct": true, "explanation": "对（duì）：介词，引出态度、影响或看法所针对的对象。"}, {"text": "堆", "is_correct": false, "explanation": "堆（duī）与对（duì）声调不同（第一声与第四声），意思是堆积。"}, {"text": "退", "is_correct": false, "explanation": "退（tuì）与对（duì）声母不同（t 与 d），意思是后退。"}, {"text": "最", "is_correct": false, "explanation": "最（zuì）与对（duì）声母不同（z 与 d），意思是程度最高。"}], "explanations": {"对": "对（duì）：介词，引出态度、影响或看法所针对的对象。", "堆": "堆（duī）与对（duì）声调不同（第一声与第四声），意思是堆积。", "退": "退（tuì）与对（duì）声母不同（t 与 d），意思是后退。", "最": "最（zuì）与对（duì）声母不同（z 与 d），意思是程度最高。"}, "sentence_index": null, "correct_answer": "对"}, "level_3": {"options": [{"text": "对", "is_correct": true, "explanation": "对：引出影响的对象，“对身体有好处”是通顺的说法。"}, {"text": "以", "is_correct": false, "explanation": "语义：“以”引出凭借或方式，“以身体有好处”说不通。"}, {"text": "由", "is_correct": false, "explanation": "配价：“由”引出施事或来源，不能接“有好处”的对象“身体”。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”表示依据，“按身体有好处”说不通。"}], "explanations": {"对": "对：引出影响的对象，“对身体有好处”是通顺的说法。", "以": "语义：“以”引出凭借或方式，“以身体有好处”说不通。", "由": "配价：“由”引出施事或来源，不能接“有好处”的对象“身体”。", "按": "语义：“按”表示依据，“按身体有好处”说不通。"}, "sentence_index": 6, "correct_answer": "对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我对老师那里学到了很多东西。", "explanation": "这里应该用〈从〉。“对”引出针对的对象，不能表示知识或东西的来源。"}, {"text": "妈妈对我买了一件衣服。", "explanation": "这里应该用〈替〉或〈为〉。“对”引出针对的对象，不能表示为某人做事，应说“替我买了一件衣服”或“为我买了一件衣服”。"}, {"text": "他对同学一起吃饭。", "explanation": "这里应该用〈跟〉。“对”引出针对的对象，不能表示一起行动的伙伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85674, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她对了这次比赛很有信心。", "corrected_sentence": "她对这次比赛很有信心。", "error_description": "错误：“对”后直接加“了”不通，“对了”不能引出“有信心”针对的对象；应去掉“了”，写作“她对这次比赛很有信心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85674, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对很友好。", "corrected_sentence": "她对邻居很友好。", "error_description": "缺少宾语：“对”引出的对象不能省略，“她对很友好”不通，应补上“邻居”，写作“她对邻居很友好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b82f074-9073-48a1-a25a-cbb1a7b7ac41') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
