INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85676, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "数量词，表示单个的人或事物的数量为一。", "primary_collocate": null, "pronunciation": "yí gè", "ipa": "i˧˥ kɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我有一个哥哥。", "target_word": "一个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有一个杯子。", "target_word": "一个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他买了一个面包。", "target_word": "一个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里有一个讲台。", "target_word": "一个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给我一个苹果。", "target_word": "一个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请给我一个袋子。", "target_word": "一个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天我要去见一个朋友。", "target_word": "一个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她画了一个很大的圆。", "target_word": "一个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他昨天讲了一个有意思的故事。", "target_word": "一个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有一个小湖。", "target_word": "一个", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个个", "label": "重叠"}], "register": "口语", "sense_fingerprint": "数量词，后接名词，表示单个的人或事物的数量为一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f31afe75-cf81-4a37-a9d7-9dd37dc90485') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一个", "is_correct": true, "explanation": "正确。“一个哥哥”表示单个的人，数量为一。"}, {"text": "一只", "is_correct": false, "explanation": "搭配：“只”用于动物，不能用来数“哥哥”。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长的东西，不能用来数“哥哥”。"}, {"text": "一头", "is_correct": false, "explanation": "语义：“头”多用于牲畜，用来数“哥哥”会使句子的意思荒谬。"}], "explanations": {"一个": "正确。“一个哥哥”表示单个的人，数量为一。", "一只": "搭配：“只”用于动物，不能用来数“哥哥”。", "一条": "搭配：“条”用于细长的东西，不能用来数“哥哥”。", "一头": "语义：“头”多用于牲畜，用来数“哥哥”会使句子的意思荒谬。"}, "sentence_index": 0, "correct_answer": "一个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里有一本讲台。", "explanation": "这里应该用〈个〉。“本”用于书册，讲台要用“个”。"}, {"text": "教室里有一条讲台。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，讲台要用“个”。"}, {"text": "教室里有一只讲台。", "explanation": "这里应该用〈个〉。“只”用于动物，讲台要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一个", "is_correct": true, "explanation": "正确。“一个朋友”表示单个的人，与“见”搭配。"}, {"text": "一颗", "is_correct": false, "explanation": "搭配：“颗”用于小而圆的东西，不能用来数“朋友”。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，不能用来数“朋友”。"}, {"text": "一本", "is_correct": false, "explanation": "语义：“本”指书册，与“朋友”指人，语义不合。"}], "explanations": {"一个": "正确。“一个朋友”表示单个的人，与“见”搭配。", "一颗": "搭配：“颗”用于小而圆的东西，不能用来数“朋友”。", "一张": "搭配：“张”用于平面的东西，不能用来数“朋友”。", "一本": "语义：“本”指书册，与“朋友”指人，语义不合。"}, "sentence_index": 6, "correct_answer": "一个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园里有一张小湖。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，湖要用“个”。"}, {"text": "公园里有一颗小湖。", "explanation": "这里应该用〈个〉。“颗”用于小而圆的东西，湖要用“个”。"}, {"text": "公园里有一朵小湖。", "explanation": "这里应该用〈个〉。“朵”用于花或云，湖要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我有一个个问题。", "corrected_sentence": "我有一个问题。", "error_description": "“一个个”是重叠形式，表示“一个接一个”，不能用来修饰单个的“问题”。错误形式“我有一个个问题”，正确为“我有一个问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想喝一个水。", "corrected_sentence": "我想喝一杯水。", "error_description": "量词误用：“水”是不可数的物质名词，不能直接用“一个”来数，要借用容器量词。错误形式“一个水”，正确为“一杯水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fad6a88a-e1ea-430f-97ef-5c3a9d644ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
