INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85679, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“吗”放在句子最后，用来问问题。", "primary_collocate": null, "pronunciation": "ma", "ipa": "ma", "syllable_count": 1, "sentences": [{"text": "你今天有空吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，这里可以坐吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你喝过茶吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天会下雨吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的朋友是中国人吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书好看吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想和我们一起去吃饭吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，我可以问一个问题吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你会说汉语吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天看了那个电影吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "吗：句末助词，把陈述句变成是非问句", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '464d8e31-3b58-4903-948d-c22c693dcaf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85679, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吗", "is_correct": true, "explanation": "ma（轻声）是本词，句末语气助词，表示疑问。"}, {"text": "妈", "is_correct": false, "explanation": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。"}, {"text": "麻", "is_correct": false, "explanation": "má（第二声）与 ma（轻声）声调不同，意思是麻烦。"}, {"text": "骂", "is_correct": false, "explanation": "mà（第四声）与 ma（轻声）声调不同，意思是骂。"}, {"text": "吧", "is_correct": false, "explanation": "ba 与 ma 声母不同（b 与 m），是表示商量或猜测的语气词。"}], "explanations": {"吗": "ma（轻声）是本词，句末语气助词，表示疑问。", "妈": "mā（第一声）与 ma（轻声）声调不同，意思是妈妈。", "马": "mǎ（第三声）与 ma（轻声）声调不同，意思是马。", "麻": "má（第二声）与 ma（轻声）声调不同，意思是麻烦。", "骂": "mà（第四声）与 ma（轻声）声调不同，意思是骂。", "吧": "ba 与 ma 声母不同（b 与 m），是表示商量或猜测的语气词。"}, "sentence_index": null, "correct_answer": "吗"}, "level_3": {"options": [{"text": "吗", "is_correct": true, "explanation": "吗：句末语气助词，把陈述句变成是非问句。"}, {"text": "得", "is_correct": false, "explanation": "语义：得是结构助词（如“跑得快”），不能用在句末构成疑问。"}, {"text": "过", "is_correct": false, "explanation": "体貌：过表示经历，“有空过”不能用来问今天的状况。"}, {"text": "呢", "is_correct": false, "explanation": "语义：呢用于追问或省略句（如“我呢？”），不用于一般是非问。"}], "explanations": {"吗": "吗：句末语气助词，把陈述句变成是非问句。", "得": "语义：得是结构助词（如“跑得快”），不能用在句末构成疑问。", "过": "体貌：过表示经历，“有空过”不能用来问今天的状况。", "呢": "语义：呢用于追问或省略句（如“我呢？”），不用于一般是非问。"}, "sentence_index": 0, "correct_answer": "吗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你去不去吗？", "explanation": "“去不去”已经是正反问，句末不能再加“吗”，应说“你去不去？”"}, {"text": "你叫什么名字吗？", "explanation": "句中已有疑问代词“什么”，是特指问，不能再加“吗”，应说“你叫什么名字？”"}, {"text": "别这么生气吗，大家都很关心你。", "explanation": "这里应该用〈嘛〉。劝说语气要用“嘛”，“吗”只用于疑问，不能用来劝说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85679, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吗", "is_correct": true, "explanation": "ma（轻声）是本词，句末语气助词，表示疑问。"}, {"text": "呢", "is_correct": false, "explanation": "ne（轻声）与 ma 声母不同（n 与 m），是语气助词。"}, {"text": "码", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码。"}, {"text": "蚂", "is_correct": false, "explanation": "mǎ（第三声）与 ma（轻声）声调不同，意思是蚂蚁。"}], "explanations": {"吗": "ma（轻声）是本词，句末语气助词，表示疑问。", "呢": "ne（轻声）与 ma 声母不同（n 与 m），是语气助词。", "码": "mǎ（第三声）与 ma（轻声）声调不同，意思是号码。", "蚂": "mǎ（第三声）与 ma（轻声）声调不同，意思是蚂蚁。"}, "sentence_index": null, "correct_answer": "吗"}, "level_3": {"options": [{"text": "吗", "is_correct": true, "explanation": "吗：句末语气助词，用来表示疑问。"}, {"text": "着", "is_correct": false, "explanation": "体貌：着表示状态持续，“吃饭着”不能用来提问。"}, {"text": "地", "is_correct": false, "explanation": "语义：地是结构助词，不能用在句末。"}, {"text": "得", "is_correct": false, "explanation": "语义：得是结构助词（如“跑得快”），不能用在句末构成疑问。"}], "explanations": {"吗": "吗：句末语气助词，用来表示疑问。", "着": "体貌：着表示状态持续，“吃饭着”不能用来提问。", "地": "语义：地是结构助词，不能用在句末。", "得": "语义：得是结构助词（如“跑得快”），不能用在句末构成疑问。"}, "sentence_index": 6, "correct_answer": "吗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电影真好看吗！", "explanation": "这里应该用〈啊〉。表示赞叹要用“啊”，“吗”只用于疑问，不能表示感叹。"}, {"text": "快点吃饭吗！", "explanation": "这是命令句，句末不能用“吗”，应说“快点吃饭！”"}, {"text": "我去图书馆，你吗？", "explanation": "这里应该用〈呢〉。承接前文追问“你呢”要用“呢”，不用“吗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85679, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他明天能来吗吗？", "corrected_sentence": "他明天能来吗？", "error_description": "重复语气词：句末只用一个“吗”，多出的“吗”要删去。应说“他明天能来吗？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85679, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你周末要来我家吗呢？", "corrected_sentence": "你周末要来我家吗？", "error_description": "语气词叠用：“吗”已表示是非问，句末不能再加“呢”。应说“你周末要来我家吗？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9bc37fe-d124-4688-95fc-05c5e1d76589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
