INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85680, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气助词，用在句末，表示疑问。", "primary_collocate": null, "pronunciation": "ma", "ipa": "ma", "syllable_count": 1, "sentences": [{"text": "他在家吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你累了吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机是新的吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你去过北京吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天来学校吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们家有狗吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我可以用一下你的笔吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你认识那个人吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜辣吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想去公园玩吗？", "target_word": "吗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嗎", "label": "繁体"}], "register": "中性", "sense_fingerprint": "吗：句末语气助词，表示疑问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '464d8e31-3b58-4903-948d-c22c693dcaf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_