INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年中的一段时间，一年分十二个月。", "primary_collocate": null, "pronunciation": "yuè", "ipa": "ɥɛ˥˩", "syllable_count": 1, "sentences": [{"text": "这个月我很忙。", "target_word": "月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一年有十二个月。", "target_word": "月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下个月我要去北京。", "target_word": "月", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我学汉语已经三个月了。", "target_word": "月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上个月他给我打了两次电话。", "target_word": "月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每个月我都给妈妈寄一些钱。", "target_word": "月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月有三十天，下个月有三十一天。", "target_word": "月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在中国住了五个月。", "target_word": "月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个月后，我们就要放假了。", "target_word": "月", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年的最后一个月是十二月。", "target_word": "月", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个月", "label": "量词搭配（个）"}, {"form": "月份", "label": "复合"}, {"form": "月底", "label": "复合"}], "register": "中性", "sense_fingerprint": "一年十二份中的一份时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "月", "is_correct": true, "explanation": "正确答案：月（yuè，第四声），如“这个月”“三个月”。"}, {"text": "约", "is_correct": false, "explanation": "约（yuē，第一声）与 yuè 声调不同，意思是约定、大约。"}, {"text": "夜", "is_correct": false, "explanation": "夜（yè）比 yuè 少了介音 u，韵母不同，意思是夜晚。"}, {"text": "页", "is_correct": false, "explanation": "页（yè）比 yuè 少了介音 u，韵母不同，意思是书页。"}, {"text": "玉", "is_correct": false, "explanation": "玉（yù）比 yuè 少了韵尾 e，韵母不同，意思是玉石。"}], "explanations": {"月": "正确答案：月（yuè，第四声），如“这个月”“三个月”。", "约": "约（yuē，第一声）与 yuè 声调不同，意思是约定、大约。", "夜": "夜（yè）比 yuè 少了介音 u，韵母不同，意思是夜晚。", "页": "页（yè）比 yuè 少了介音 u，韵母不同，意思是书页。", "玉": "玉（yù）比 yuè 少了韵尾 e，韵母不同，意思是玉石。"}, "sentence_index": null, "correct_answer": "月"}, "level_3": {"options": [{"text": "月", "is_correct": true, "explanation": "正确：“这个月我很忙”中的“月”指一段时间，与“这个”和“很忙”的语境相符。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不是一段时间，“这个饭我很忙”说不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“书”的量词是“本”，不说“这个书”，而且“书”也不能“忙”。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”不是人，不能“很忙”，句子说不通。"}], "explanations": {"月": "正确：“这个月我很忙”中的“月”指一段时间，与“这个”和“很忙”的语境相符。", "饭": "语义：“饭”不是一段时间，“这个饭我很忙”说不通。", "书": "搭配：“书”的量词是“本”，不说“这个书”，而且“书”也不能“忙”。", "车": "语义：“车”不是人，不能“很忙”，句子说不通。"}, "sentence_index": 0, "correct_answer": "月"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我学汉语已经三轮月了。", "explanation": "这里应该用〈个〉。“轮”用于圆月（一轮明月），表示学了多长时间要用“个”，“三轮月”不通。"}, {"text": "我学汉语已经三次月了。", "explanation": "这里应该用〈个〉。“次”用来数动作的次数，不能数一段时间，“三次月”不通。"}, {"text": "我学汉语已经三条月了。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，如“一条河”，不能数“月”，表示时长要说“三个月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85684, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "月", "is_correct": true, "explanation": "正确答案：月（yuè，第四声），指一年中的一个月份。"}, {"text": "也", "is_correct": false, "explanation": "也（yě，第三声）没有介音 u，声调也不同，意思是“也是、同样”。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ，第三声）没有韵尾 e，声调也不同，意思是下雨的雨。"}, {"text": "雪", "is_correct": false, "explanation": "雪（xuě，第三声）声母是 x 不是 y，声调也不同，意思是下雪的雪。"}, {"text": "爷", "is_correct": false, "explanation": "爷（yé，第二声）没有介音 u，声调也不同，意思是爷爷。"}], "explanations": {"月": "正确答案：月（yuè，第四声），指一年中的一个月份。", "也": "也（yě，第三声）没有介音 u，声调也不同，意思是“也是、同样”。", "雨": "雨（yǔ，第三声）没有韵尾 e，声调也不同，意思是下雨的雨。", "雪": "雪（xuě，第三声）声母是 x 不是 y，声调也不同，意思是下雪的雪。", "爷": "爷（yé，第二声）没有介音 u，声调也不同，意思是爷爷。"}, "sentence_index": null, "correct_answer": "月"}, "level_3": {"options": [{"text": "月", "is_correct": true, "explanation": "正确：“这个月有三十天”中的“月”是一个月的时长。"}, {"text": "周", "is_correct": false, "explanation": "语义：一周只有七天，不能有三十天。"}, {"text": "年", "is_correct": false, "explanation": "语义：一年有三百六十五天左右，不是三十天。"}, {"text": "旬", "is_correct": false, "explanation": "语域：“旬”是书面语，指十天，与“有三十天”矛盾。"}], "explanations": {"月": "正确：“这个月有三十天”中的“月”是一个月的时长。", "周": "语义：一周只有七天，不能有三十天。", "年": "语义：一年有三百六十五天左右，不是三十天。", "旬": "语域：“旬”是书面语，指十天，与“有三十天”矛盾。"}, "sentence_index": 6, "correct_answer": "月"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今年的最后一只月是十二月。", "explanation": "这里应该用〈个〉。“只”多用于动物，数一年中的月份要用“个”，“一只月”说不通。"}, {"text": "今年的最后一个月是十二个月。", "explanation": "这里应该用〈十二月〉。“十二个月”表示时长，而这里要说月份名称，应为“十二月”。"}, {"text": "今年的最后一个月是十二号。", "explanation": "这里应该用〈十二月〉。“十二号”指日期，不指月份，把月份说成日期是错的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们等了两只月才收到回信。", "corrected_sentence": "我们等了两个月才收到回信。", "error_description": "量词错误：“月”作时段要用量词“个”，“只”多用于动物，不能数“月”。应改为“两个月”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在北京工作了两次月。", "corrected_sentence": "他在北京工作了两个月。", "error_description": "量词错误：“月”作时段要用量词“个”，“次”只用于数动作的次数。应改为“两个月”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
