INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85685, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“被”是说有人对一个东西做了一件事，这个东西受到了影响。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei˥˩", "syllable_count": 1, "sentences": [{"text": "门被打开了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的杯子被摔坏了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书被放在桌子上。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服被雨淋湿了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被大家选为班长。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地被扫干净了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑被关上了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户被关好了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只鸟被抓住了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我被这个消息吓了一跳。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "表示东西受到别人动作的影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebcaa39-880a-494e-9b7b-c3edf04ba17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85685, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "被", "is_correct": true, "explanation": "正确。被（bèi）是第四声，是本题要辨认的词。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。"}, {"text": "碑", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。"}], "explanations": {"被": "正确。被（bèi）是第四声，是本题要辨认的词。", "北": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。", "杯": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。", "碑": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。"}, "sentence_index": null, "correct_answer": "被"}, "level_3": {"options": [{"text": "被", "is_correct": true, "explanation": "正确。“门”是受事，“被打开”表示门受到外力影响，符合被动句。"}, {"text": "让", "is_correct": false, "explanation": "配价：“让”引出使令的施事，后面需接人或动作的主体，“门让打开了”缺少施事。"}, {"text": "叫", "is_correct": false, "explanation": "配价：“叫”引出施事，后面需接具体的人，“门叫打开了”缺少施事，句子不成立。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”引出起点，不能表示被动，“门从打开了”句子不成立。"}], "explanations": {"被": "正确。“门”是受事，“被打开”表示门受到外力影响，符合被动句。", "让": "配价：“让”引出使令的施事，后面需接人或动作的主体，“门让打开了”缺少施事。", "叫": "配价：“叫”引出施事，后面需接具体的人，“门叫打开了”缺少施事，句子不成立。", "从": "语义：“从”引出起点，不能表示被动，“门从打开了”句子不成立。"}, "sentence_index": 0, "correct_answer": "被"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地被我满意了。", "explanation": "〈满意〉是心理状态，不能用〈被〉引出施事，这里的〈被〉不合。"}, {"text": "这个玩具被她笑了。", "explanation": "〈笑〉是不及物动作，不能施加于主语，不能用〈被〉引出施事。"}, {"text": "孩子被我们努力读书了。", "explanation": "〈被〉引出的施事不能支配主语自主完成的动作；“努力读书”是主语自己的行为，不能用〈被〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85685, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被", "is_correct": true, "explanation": "正确。“电脑”是受事，“被关上”表示电脑受到外力影响，符合被动句。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”引出受益者，不能引出施事，“电脑替关上了”意思不通。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”引出动作的对象，不能引出施事，“电脑对关上了”结构不成立。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示方向或对象，不引出施事，句子不成立。"}], "explanations": {"被": "正确。“电脑”是受事，“被关上”表示电脑受到外力影响，符合被动句。", "替": "语义：“替”引出受益者，不能引出施事，“电脑替关上了”意思不通。", "对": "配价：“对”引出动作的对象，不能引出施事，“电脑对关上了”结构不成立。", "向": "语义：“向”表示方向或对象，不引出施事，句子不成立。"}, "sentence_index": 6, "correct_answer": "被"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书被我满意了。", "explanation": "〈满意〉是心理状态，不能用〈被〉引出施事，这里的〈被〉不合。"}, {"text": "妹妹被爸爸哭了。", "explanation": "〈哭〉是不及物动作，不能施加于主语，不能用〈被〉引出施事。"}, {"text": "这辆车被我害怕了。", "explanation": "〈害怕〉是心理状态，不能用〈被〉引出施事，这里的〈被〉不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85685, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书包被被老师拿走了。", "corrected_sentence": "书包被老师拿走了。", "error_description": "错误：“被”重复出现，一句之中只需一个“被”，应直接引出施事“老师”。正确形式是“书包被老师拿走了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
