INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85686, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，用在被动句中，引出施事者，表示主语受到动作的影响。", "primary_collocate": null, "pronunciation": "bèi", "ipa": "pei˥˩", "syllable_count": 1, "sentences": [{"text": "我的手机被弟弟拿走了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花瓶被小猫打破了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他被老师叫到办公室去了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕被孩子们吃完了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那本书被朋友借走了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的自行车被哥哥骑走了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇窗户被风吹开了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗被主人带去公园了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的钱包被小偷偷走了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "课桌被同学们搬到外面了。", "target_word": "被", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "被动句介词，后接施事者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebcaa39-880a-494e-9b7b-c3edf04ba17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85686, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "被", "is_correct": true, "explanation": "正确。被（bèi）是第四声，是本题要辨认的词。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。"}, {"text": "杯", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。"}, {"text": "碑", "is_correct": false, "explanation": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。"}], "explanations": {"被": "正确。被（bèi）是第四声，是本题要辨认的词。", "北": "běi（第三声）与 bèi（第四声）声调不同，意思是北方。", "杯": "bēi（第一声）与 bèi（第四声）声调不同，意思是杯子。", "碑": "bēi（第一声）与 bèi（第四声）声调不同，意思是石碑。"}, "sentence_index": null, "correct_answer": "被"}, "level_3": {"options": [{"text": "被", "is_correct": true, "explanation": "正确。“我的手机”是受事，“被弟弟拿走”引出施事，符合被动句。"}, {"text": "把", "is_correct": false, "explanation": "配价：“把”引出被处置的对象，不能让“我的手机”作主语后再接施事，“我的手机把弟弟拿走了”结构不成立。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出动作的对象，不能引出施事，与被动句的结构不合。"}, {"text": "向", "is_correct": false, "explanation": "语义：“向”表示动作的方向或对象，不引出施事，句子不成立。"}], "explanations": {"被": "正确。“我的手机”是受事，“被弟弟拿走”引出施事，符合被动句。", "把": "配价：“把”引出被处置的对象，不能让“我的手机”作主语后再接施事，“我的手机把弟弟拿走了”结构不成立。", "对": "语义：“对”引出动作的对象，不能引出施事，与被动句的结构不合。", "向": "语义：“向”表示动作的方向或对象，不引出施事，句子不成立。"}, "sentence_index": 0, "correct_answer": "被"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被杯子打碎了。", "explanation": "这里应该用〈把〉。〈被〉引出的施事“杯子”与主语位置颠倒；此句主语“他”是施动者，应说“他把杯子打碎了”。"}, {"text": "我被这个消息高兴了。", "explanation": "这里应该用〈让〉。〈被〉表示主语受他人动作影响，“高兴”是心理状态，不能用〈被〉引出施事；应说“这个消息让我高兴”。"}, {"text": "这只猫被我生气了。", "explanation": "〈生气〉是心理状态，不能用〈被〉引出施事，这里的〈被〉不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85686, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被", "is_correct": true, "explanation": "正确。“课桌”是受事，“被同学们搬到外面”引出施事，符合被动句。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”引出受益者，不能引出施事，“课桌替同学们搬到外面”意思不通。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”引出起点，不能引出施事，句意不通。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为”引出目的或原因，不能引出动作的施事，句子不成立。"}], "explanations": {"被": "正确。“课桌”是受事，“被同学们搬到外面”引出施事，符合被动句。", "替": "语义：“替”引出受益者，不能引出施事，“课桌替同学们搬到外面”意思不通。", "从": "语义：“从”引出起点，不能引出施事，句意不通。", "为": "语义：“为”引出目的或原因，不能引出动作的施事，句子不成立。"}, "sentence_index": 6, "correct_answer": "被"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他被我的朋友笑了。", "explanation": "〈笑〉是不及物动作，不能施加于主语，不能用〈被〉引出施事。"}, {"text": "宝宝被妈妈哭了。", "explanation": "〈哭〉是不及物动作，不能施加于主语，不能用〈被〉引出施事。"}, {"text": "这封信被我感动了。", "explanation": "〈感动〉是心理状态，不能用〈被〉引出施事，这里的〈被〉不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85686, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "杯子被被小猫碰倒了。", "corrected_sentence": "杯子被小猫碰倒了。", "error_description": "错误：“被”重复出现，一句之中只需一个“被”，紧跟受事主语“杯子”。正确形式是“杯子被小猫碰倒了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85686, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "风筝被被风刮走了。", "corrected_sentence": "风筝被风刮走了。", "error_description": "错误：“被”重复出现，一句之中只需一个“被”，紧跟受事主语“风筝”。正确形式是“风筝被风刮走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
