INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85687, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“他们”是说不在这里的两个或更多人。", "primary_collocate": null, "pronunciation": "tā men", "ipa": "tʰa˥ mən˨", "syllable_count": 2, "sentences": [{"text": "他们三个人都是医生。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些学生很高兴，他们得了第一名。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早就回国了。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别等他们了，我们先吃饭吧。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们喜欢吃中国菜，也喜欢喝茶。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在外面玩，他们笑得很大声。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说他们明年要搬到上海去。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉他们，明天九点开会。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家离这儿很远，要坐一个小时车。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两个是好朋友，常常一起玩。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "她们", "label": "女性复数"}, {"form": "它们", "label": "非人复数"}, {"form": "他們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用来指不在场的两个或更多人，说话时他们不在身边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他们", "is_correct": true, "explanation": "正确。“他们”指不在这里的三个人，与“三个人都是医生”相符。"}, {"text": "他", "is_correct": false, "explanation": "搭配：“他”是单数，不能和“三个人”搭配。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物或动物，不指人，而句子说的是三个医生。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”只指说话人自己，不能指那三个人。"}], "explanations": {"他们": "正确。“他们”指不在这里的三个人，与“三个人都是医生”相符。", "他": "搭配：“他”是单数，不能和“三个人”搭配。", "它": "语义：“它”指事物或动物，不指人，而句子说的是三个医生。", "我": "语义：“我”只指说话人自己，不能指那三个人。"}, "sentence_index": 0, "correct_answer": "他们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长今天很忙，他们正在办公室开会。", "explanation": "这里应该用〈他〉。“班长”只指一个人，“他们”指多人，不能用于单数。"}, {"text": "我家的猫很可爱，他们每天都陪我。", "explanation": "这里应该用〈它〉。猫是一只动物，“他们”只指人，而且指多个人。"}, {"text": "那几本书很重，他们都放在桌上。", "explanation": "书是东西，应该用〈它们〉。“他们”只指人，不能用于物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他们", "is_correct": true, "explanation": "正确。“他们”指不在场的一群人，“搬到上海去”是他们的动作。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，这句是陈述句，不能指代这群人。"}, {"text": "彼此", "is_correct": false, "explanation": "搭配：“彼此”表示互相，不能作主语指一群人搬家。"}, {"text": "自己", "is_correct": false, "explanation": "语义：“自己”指主语本人，句中说的是别人明年搬家；“听说自己明年要搬到上海去”只能理解为说话人自己要搬，句意不通。"}], "explanations": {"他们": "正确。“他们”指不在场的一群人，“搬到上海去”是他们的动作。", "谁": "语义：“谁”是疑问代词，这句是陈述句，不能指代这群人。", "彼此": "搭配：“彼此”表示互相，不能作主语指一群人搬家。", "自己": "语义：“自己”指主语本人，句中说的是别人明年搬家；“听说自己明年要搬到上海去”只能理解为说话人自己要搬，句意不通。"}, "sentence_index": 6, "correct_answer": "他们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我姐姐很聪明，他们常常帮我。", "explanation": "“姐姐”只有一个人，应该用〈她〉。“他们”不能指一个人。"}, {"text": "这三位姑娘都很温柔，他们每天都很努力。", "explanation": "三位都是女性，应该用〈她们〉。“他们”不用于全是女性的一群人。"}, {"text": "他们一个人住在山里，很孤单。", "explanation": "“一个人”只有一人，应该用〈他〉。“他们”指多人，不能和“一个人”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那三位都是女医生，他们一起去上班。", "corrected_sentence": "那三位都是女医生，她们一起去上班。", "error_description": "性别用错。三位都是女性，应该用“她们”，不能用“他们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人们在树下下棋，他们的很开心。", "corrected_sentence": "老人们在树下下棋，他们很开心。", "error_description": "错误：“他们的”是所属结构，后面应接名词，不能直接作主语。正确：“他们很开心”，不要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
