INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85688, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85688, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第三人称复数代词，指说话双方以外的多个人。", "primary_collocate": null, "pronunciation": "tā men", "ipa": "tʰa˥ mən˨", "syllable_count": 2, "sentences": [{"text": "他们是我的同事，都在一家公司工作。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识他们很多年了。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先走吧，他们一会儿就到。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都说这个地方很安静。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说他们这次考得很好。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去北京，他们去上海。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每个周末都去公园玩。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我见过他们两个人。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们住在学校旁边的小房子里。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的孩子今年上大学了。", "target_word": "他们", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "她们", "label": "女性复数"}, {"form": "它们", "label": "非人复数"}, {"form": "他們", "label": "繁体"}], "register": "中性", "sense_fingerprint": "第三人称复数代词，指说话人和听话人以外的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "他们", "is_correct": true, "explanation": "正确。“他们”指说话人和听话人以外的多个人，与“都在一家公司工作”相符。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”包括说话人在内，句子说“我们是我的同事”，说话人不能是自己的同事。"}, {"text": "咱们", "is_correct": false, "explanation": "语义：“咱们”包括听话人在内，句子说“咱们是我的同事”，会把说话人和听话人都算进去，与指第三方的意思不符。"}, {"text": "他", "is_correct": false, "explanation": "搭配：“他”是单数，后面的“都”要求复数的人，“他……都在一家公司工作”搭配不通。"}], "explanations": {"他们": "正确。“他们”指说话人和听话人以外的多个人，与“都在一家公司工作”相符。", "我们": "语义：“我们”包括说话人在内，句子说“我们是我的同事”，说话人不能是自己的同事。", "咱们": "语义：“咱们”包括听话人在内，句子说“咱们是我的同事”，会把说话人和听话人都算进去，与指第三方的意思不符。", "他": "搭配：“他”是单数，后面的“都”要求复数的人，“他……都在一家公司工作”搭配不通。"}, "sentence_index": 0, "correct_answer": "他们"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的鹦鹉很聪明，他们会说话。", "explanation": "这里应该用〈它〉。鹦鹉是一只动物，“他们”只指人，而且指多个人。"}, {"text": "张先生今天在家，他们正在看书。", "explanation": "这里应该用〈他〉。“张先生”只指一个人，“他们”指多人，不能用于单数。"}, {"text": "那些书很旧，他们都放在箱子里。", "explanation": "这里应该用〈它们〉。书是事物，“他们”只指人，不能用于物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "他们", "is_correct": true, "explanation": "正确。“他们”指说话人以外的一群人，与“每个周末都去公园玩”相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，这句是陈述句，不能指代这群人去公园。"}, {"text": "彼此", "is_correct": false, "explanation": "搭配：“彼此”表示互相，不能作主语指一群人去做动作。"}, {"text": "这", "is_correct": false, "explanation": "语义：“这”是指示代词，指事物，不指一群人，句子不通。"}], "explanations": {"他们": "正确。“他们”指说话人以外的一群人，与“每个周末都去公园玩”相符。", "谁": "语义：“谁”是疑问代词，这句是陈述句，不能指代这群人去公园。", "彼此": "搭配：“彼此”表示互相，不能作主语指一群人去做动作。", "这": "语义：“这”是指示代词，指事物，不指一群人，句子不通。"}, "sentence_index": 6, "correct_answer": "他们"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我妈妈今天很忙，他们不在家。", "explanation": "“妈妈”只有一个人，应该用〈她〉。“他们”指多个人，不能指单数。"}, {"text": "这两个女孩是好朋友，他们常一起玩。", "explanation": "两个都是女孩，应该用〈她们〉。“他们”不用于全是女性的一群人。"}, {"text": "这个人很热心，他们常常帮我。", "explanation": "“这个人”只指一个人，前面的代词应该用〈他〉，不能用“他们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几个姑娘都很漂亮，他们正在跳舞。", "corrected_sentence": "这几个姑娘都很漂亮，她们正在跳舞。", "error_description": "性别用错。全是女性的一群人要用“她们”，不能用“他们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这对朋友常一起玩，它们两个很开心。", "corrected_sentence": "这对朋友常一起玩，他们两个很开心。", "error_description": "错误：“它们”只指事物或动物，这里指人，应该用“他们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85689, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85689, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85689, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“而”可以把两句话连起来，有时是说后面的话和前面不一样。", "primary_collocate": null, "pronunciation": "ér", "ipa": "ɚ˧˥", "syllable_count": 1, "sentences": [{"text": "我喜欢喝茶，而弟弟喜欢喝咖啡。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥爱运动，而我爱看书。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京现在很冷，而广州还很热。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只会说，而不会做。", "target_word": "而", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "姐姐很高，而妹妹很矮。", "target_word": "而", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里是白天，而美国现在是晚上。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近很吵，而他家附近很安静。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明考了一百分，而小王只考了六十分。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈喜欢早睡，而爸爸总是很晚才睡。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店白天人很多，而晚上几乎没有人。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "而且", "label": "复合"}, {"form": "然而", "label": "复合"}], "register": "书面", "sense_fingerprint": "而：连接两个分句，表示后面的内容与前面相对或不同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85689, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。而 读作 ér（第二声）。"}, {"text": "二", "is_correct": false, "explanation": "èr（第四声）与 ér（第二声）声调不同，意思是数字“二”。"}, {"text": "耳", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，意思是“耳朵”。"}, {"text": "饵", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，意思是“鱼饵”。"}], "explanations": {"而": "正确。而 读作 ér（第二声）。", "二": "èr（第四声）与 ér（第二声）声调不同，意思是数字“二”。", "耳": "ěr（第三声）与 ér（第二声）声调不同，意思是“耳朵”。", "饵": "ěr（第三声）与 ér（第二声）声调不同，意思是“鱼饵”。"}, "sentence_index": null, "correct_answer": "而"}, "level_3": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。「而」连接两个分句，表示“我”和“弟弟”的爱好不同。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，“我喜欢喝茶，所以弟弟喜欢喝咖啡”句意不通，两件事之间没有因果关系。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，两个分句之间没有因果关系，不能这样连接。"}, {"text": "和", "is_correct": false, "explanation": "搭配：「和」连接名词性成分，不能连接两个完整的分句。"}], "explanations": {"而": "正确。「而」连接两个分句，表示“我”和“弟弟”的爱好不同。", "所以": "语义：「所以」表示因果，“我喜欢喝茶，所以弟弟喜欢喝咖啡”句意不通，两件事之间没有因果关系。", "因为": "语义：「因为」表示原因，两个分句之间没有因果关系，不能这样连接。", "和": "搭配：「和」连接名词性成分，不能连接两个完整的分句。"}, "sentence_index": 0, "correct_answer": "而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢喝茶，而是弟弟喜欢喝咖啡。", "explanation": "这里应该用〈不是……而是〉。“而是”前面必须有否定词“不是”，没有否定前句时不能直接用“而是”。"}, {"text": "他吃完饭，而是去上学了。", "explanation": "这里的〈而是〉前面没有否定词〈不是〉，不能直接用；表示承接先后应该用〈然后〉。"}, {"text": "天很热，而是我们去游泳。", "explanation": "这里的〈而是〉没有否定前句〈不是〉，不能直接用；说明天热导致去游泳，应该用〈因此〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85689, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。而 读作 ér（第二声）。"}, {"text": "尔", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，意思是“你”（书面）。"}, {"text": "贰", "is_correct": false, "explanation": "èr（第四声）与 ér（第二声）声调不同，是“二”的大写。"}, {"text": "洱", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，用于“洱海”。"}], "explanations": {"而": "正确。而 读作 ér（第二声）。", "尔": "ěr（第三声）与 ér（第二声）声调不同，意思是“你”（书面）。", "贰": "èr（第四声）与 ér（第二声）声调不同，是“二”的大写。", "洱": "ěr（第三声）与 ér（第二声）声调不同，用于“洱海”。"}, "sentence_index": null, "correct_answer": "而"}, "level_3": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。「而」连接两个分句，表示“我家”和“他家”的情况形成对比。"}, {"text": "从而", "is_correct": false, "explanation": "语义：「从而」表示由此导致的结果，“我家附近很吵，从而他家附近很安静”句意不通。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果，两家的情况之间没有因果关系，不能这样连接。"}, {"text": "以及", "is_correct": false, "explanation": "搭配：「以及」连接名词性成分，不能连接两个完整的分句。"}], "explanations": {"而": "正确。「而」连接两个分句，表示“我家”和“他家”的情况形成对比。", "从而": "语义：「从而」表示由此导致的结果，“我家附近很吵，从而他家附近很安静”句意不通。", "因此": "语义：「因此」表示因果，两家的情况之间没有因果关系，不能这样连接。", "以及": "搭配：「以及」连接名词性成分，不能连接两个完整的分句。"}, "sentence_index": 6, "correct_answer": "而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很喜欢音乐，而是很喜欢跑步。", "explanation": "这里应该用〈而且〉。“而是”需要前面有否定词〈不是〉，这里没有否定，应改用〈而且〉表示并列。"}, {"text": "他喜欢唱歌，而是喜欢跳舞。", "explanation": "这里应该用〈而且〉。“而是”只用于“不是……而是”的结构，这里没有否定前句，不能用。"}, {"text": "这家店的菜便宜，而是很难吃。", "explanation": "这里应该用〈但是〉。“而是”需要前面有〈不是〉，这里没有否定词，不能直接用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85689, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他喜欢唱歌，而妹妹而喜欢跳舞。", "corrected_sentence": "他喜欢唱歌，而妹妹喜欢跳舞。", "error_description": "错误形式：「而妹妹而喜欢跳舞」；正确形式：「而妹妹喜欢跳舞」。「而」只放在两个分句之间，一个分句内部不能再加「而」，这里多写了一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85689, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只会听，不而会说。", "corrected_sentence": "他只会听，而不会说。", "error_description": "错误形式：「不而会说」；正确形式：「而不会说」。「而不」是固定的关联次序，「而」在前、「不」在后，颠倒后不成词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
