INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85690, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，连接意义相承或相对的词语（如形容词），表示并列、转折、递进等关系。", "primary_collocate": null, "pronunciation": "ér", "ipa": "ɚ˧˥", "syllable_count": 1, "sentences": [{"text": "这条小路长而安静，我常在那里散步。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子小而轻，很好带。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话短而有用。", "target_word": "而", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的菜便宜而好吃。", "target_word": "而", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师的办法简单而有效。", "target_word": "而", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她说话慢而清楚，我们都听得懂。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服好看而不贵。", "target_word": "而", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那是一本薄而有意思的书。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是一个聪明而努力的学生。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的夏天热而长，大家都爱喝冰水。", "target_word": "而", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "而且", "label": "复合"}, {"form": "然而", "label": "复合"}], "register": "书面", "sense_fingerprint": "而：连接两个意义相承的词语，表示并列、递进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 小路 (Zipf 3.7), 我常 (Zipf 3.17), 散步 (Zipf 3.93)']::text[], '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85690, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。而 读作 ér（第二声）。"}, {"text": "二", "is_correct": false, "explanation": "èr（第四声）与 ér（第二声）声调不同，意思是数字“二”。"}, {"text": "耳", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，意思是“耳朵”。"}, {"text": "饵", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，意思是“鱼饵”。"}], "explanations": {"而": "正确。而 读作 ér（第二声）。", "二": "èr（第四声）与 ér（第二声）声调不同，意思是数字“二”。", "耳": "ěr（第三声）与 ér（第二声）声调不同，意思是“耳朵”。", "饵": "ěr（第三声）与 ér（第二声）声调不同，意思是“鱼饵”。"}, "sentence_index": null, "correct_answer": "而"}, "level_3": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。「而」连接并列的两个形容词，表示“长”和“安静”两种性质同时存在。"}, {"text": "或", "is_correct": false, "explanation": "语义：「或」表示选择，“长或安静”说的是二选一，不能说明同一条小路的两种性质。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，“长所以安静”说不通，两个形容词之间没有因果关系。"}, {"text": "和", "is_correct": false, "explanation": "搭配：「和」连接名词性成分，不能连接“长”和“安静”两个形容词。"}], "explanations": {"而": "正确。「而」连接并列的两个形容词，表示“长”和“安静”两种性质同时存在。", "或": "语义：「或」表示选择，“长或安静”说的是二选一，不能说明同一条小路的两种性质。", "所以": "语义：「所以」表示因果，“长所以安静”说不通，两个形容词之间没有因果关系。", "和": "搭配：「和」连接名词性成分，不能连接“长”和“安静”两个形容词。"}, "sentence_index": 0, "correct_answer": "而"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是学生，而是医生。", "explanation": "这里应该用〈不是……而是〉。“而是”前面必须有否定词“不是”，直接说“他是学生，而是医生”前后矛盾，只有先否定前句才能用“而是”。"}, {"text": "他不但聪明，而是很努力。", "explanation": "这里应该用〈而且〉。“不但”后面要接“而且”表示递进；“而是”只用于“不是……而是”的结构。"}, {"text": "天气很冷，而是大家都穿了外套。", "explanation": "这里的〈而是〉没有否定前句〈不是〉，不能直接用；说明天冷导致大家穿外套，应该用〈因此〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85690, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。而 读作 ér（第二声）。"}, {"text": "尔", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，意思是“你”（书面）。"}, {"text": "贰", "is_correct": false, "explanation": "èr（第四声）与 ér（第二声）声调不同，是“二”的大写。"}, {"text": "洱", "is_correct": false, "explanation": "ěr（第三声）与 ér（第二声）声调不同，用于“洱海”。"}], "explanations": {"而": "正确。而 读作 ér（第二声）。", "尔": "ěr（第三声）与 ér（第二声）声调不同，意思是“你”（书面）。", "贰": "èr（第四声）与 ér（第二声）声调不同，是“二”的大写。", "洱": "ěr（第三声）与 ér（第二声）声调不同，用于“洱海”。"}, "sentence_index": null, "correct_answer": "而"}, "level_3": {"options": [{"text": "而", "is_correct": true, "explanation": "正确。「而」连接“好看”和“不贵”，表示两种性质并存。"}, {"text": "因为", "is_correct": false, "explanation": "语义：「因为」表示原因，“好看因为不贵”说不通，两个形容词之间没有因果关系。"}, {"text": "以及", "is_correct": false, "explanation": "搭配：「以及」连接名词性成分，不能连接“好看”和“不贵”两个形容词。"}, {"text": "从而", "is_correct": false, "explanation": "语义：「从而」表示由此导致的结果，“好看从而不贵”句意不通。"}], "explanations": {"而": "正确。「而」连接“好看”和“不贵”，表示两种性质并存。", "因为": "语义：「因为」表示原因，“好看因为不贵”说不通，两个形容词之间没有因果关系。", "以及": "搭配：「以及」连接名词性成分，不能连接“好看”和“不贵”两个形容词。", "从而": "语义：「从而」表示由此导致的结果，“好看从而不贵”句意不通。"}, "sentence_index": 6, "correct_answer": "而"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的菜很好吃，而是很贵。", "explanation": "这里的〈而是〉前面没有否定词〈不是〉，不能直接用；表示转折应该用〈但是〉。"}, {"text": "我喜欢音乐，而是喜欢跑步。", "explanation": "这里的〈而是〉没有否定前句，不能用；表示并列的两个爱好应该用〈而且〉。"}, {"text": "这家店的菜便宜，而是很难吃。", "explanation": "这里应该用〈但是〉。“而是”需要前面有〈不是〉，这里没有否定词，不能直接用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85690, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间屋子小而而干净，很适合一个人住。", "corrected_sentence": "这间屋子小而干净，很适合一个人住。", "error_description": "错误形式：「小而而干净」；正确形式：「小而干净」。「而」在两个并列形容词之间只用一次，这里多写了一个「而」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85690, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包轻和结实，我天天背着。", "corrected_sentence": "这个包轻而结实，我天天背着。", "error_description": "错误形式：「轻和结实」；正确形式：「轻而结实」。「和」一般连接名词性成分，连接两个并列的形容词谓语要用「而」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
