INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85691, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "“个”是数东西时用的字，放在数字后面。", "primary_collocate": null, "pronunciation": "gè", "ipa": "kɤ˥˩", "syllable_count": 1, "sentences": [{"text": "请给我两个鸡蛋。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了五个面包。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天买了一个新书包。", "target_word": "个", "complexity_tier": "T3", "furigana": "wǒ zuótiān mǎi le yí ge xīn shūbāo.", "sentence_source": "generated"}, {"text": "公园里有六个小孩在玩。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了一个大西瓜。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盘子里还有四个饺子。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有二十个学生。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要两个房间。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一个红杯子。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个星期有七天。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個", "label": "繁体"}, {"form": "个个", "label": "重叠"}], "register": "中性", "sense_fingerprint": "数东西时放在数字后面的字，用来数一个一个的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 8 above tier T1: 3 words above tier T1 (max 2): 桌上 (Zipf 3.95), 放着 (Zipf 3.16), 杯子 (Zipf 3.82)']::text[], 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85691, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "个", "is_correct": true, "explanation": "gè（第四声）是量词“个”，用于数东西，正确答案。"}, {"text": "哥", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是哥哥。"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是格子。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），意思是课程。"}, {"text": "故", "is_correct": false, "explanation": "gù 与 gè 韵母不同（u 与 e），意思是缘故、旧的。"}, {"text": "贺", "is_correct": false, "explanation": "hè 与 gè 声母不同（h 与 g），意思是祝贺。"}], "explanations": {"个": "gè（第四声）是量词“个”，用于数东西，正确答案。", "哥": "gē（第一声）与 gè（第四声）声调不同，意思是哥哥。", "格": "gé（第二声）与 gè（第四声）声调不同，意思是格子。", "课": "kè 与 gè 声母不同（k 与 g），意思是课程。", "故": "gù 与 gè 韵母不同（u 与 e），意思是缘故、旧的。", "贺": "hè 与 gè 声母不同（h 与 g），意思是祝贺。"}, "sentence_index": null, "correct_answer": "个"}, "level_3": {"options": [{"text": "个", "is_correct": true, "explanation": "“个”是量词，可以用来数鸡蛋，“两个鸡蛋”说法自然。"}, {"text": "本", "is_correct": false, "explanation": "搭配：「本」用于书、本子等，不说“两本鸡蛋”。"}, {"text": "条", "is_correct": false, "explanation": "语义：「条」指细长的东西，如鱼、裤子，与鸡蛋的形状不符。"}, {"text": "辆", "is_correct": false, "explanation": "语义：「辆」用于车辆，鸡蛋不是车，这里不能用。"}], "explanations": {"个": "“个”是量词，可以用来数鸡蛋，“两个鸡蛋”说法自然。", "本": "搭配：「本」用于书、本子等，不说“两本鸡蛋”。", "条": "语义：「条」指细长的东西，如鱼、裤子，与鸡蛋的形状不符。", "辆": "语义：「辆」用于车辆，鸡蛋不是车，这里不能用。"}, "sentence_index": 0, "correct_answer": "个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一个书。", "explanation": "这里应该用〈本〉。书用量词“本”，说“买了一本书”，“个”不用于书。"}, {"text": "我们家养了一个牛。", "explanation": "这里应该用〈头〉。牛用量词“头”，说“养了一头牛”，“个”不用于牛。"}, {"text": "他在北京住了三个天。", "explanation": "这里“个”用错了。表示天数直接说“数词加天”，应说“住了三天”，不加量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85691, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "个", "is_correct": true, "explanation": "gè（第四声）是量词“个”，用于数东西，正确答案。"}, {"text": "歌", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是歌曲。"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是隔开。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），意思是客人。"}, {"text": "顾", "is_correct": false, "explanation": "gù 与 gè 韵母不同（u 与 e），意思是照顾。"}], "explanations": {"个": "gè（第四声）是量词“个”，用于数东西，正确答案。", "歌": "gē（第一声）与 gè（第四声）声调不同，意思是歌曲。", "隔": "gé（第二声）与 gè（第四声）声调不同，意思是隔开。", "客": "kè 与 gè 声母不同（k 与 g），意思是客人。", "顾": "gù 与 gè 韵母不同（u 与 e），意思是照顾。"}, "sentence_index": null, "correct_answer": "个"}, "level_3": {"options": [{"text": "个", "is_correct": true, "explanation": "“个”是量词，可以用来数人，“二十个学生”说法自然。"}, {"text": "台", "is_correct": false, "explanation": "语义：「台」用于机器、设备，不用来数人。"}, {"text": "座", "is_correct": false, "explanation": "搭配：「座」用于山、桥、楼等大型固定物，不说“二十座学生”。"}, {"text": "件", "is_correct": false, "explanation": "语义：「件」用于衣服、事情等，不能用来数学生。"}], "explanations": {"个": "“个”是量词，可以用来数人，“二十个学生”说法自然。", "台": "语义：「台」用于机器、设备，不用来数人。", "座": "搭配：「座」用于山、桥、楼等大型固定物，不说“二十座学生”。", "件": "语义：「件」用于衣服、事情等，不能用来数学生。"}, "sentence_index": 6, "correct_answer": "个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下了一个大雨。", "explanation": "这里应该用〈场〉。雨、比赛等事件用量词「场」，说“下了一场大雨”，不说“一个大雨”。"}, {"text": "我买了一个裤子。", "explanation": "这里应该用〈条〉。裤子用量词“条”，说“买了一条裤子”，“个”不用于裤子。"}, {"text": "我昨天写了一个信。", "explanation": "这里应该用〈封〉。信件用量词「封」，说“写了一封信”，“个”不用于信件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_va