INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85692, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "最常用的量词，用于没有专用量词的人或事物。", "primary_collocate": null, "pronunciation": "gè", "ipa": "kɤ˥˩", "syllable_count": 1, "sentences": [{"text": "我有一个哥哥和两个姐姐。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里来了一个新同学。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一个杯子。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有一个很好的朋友。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买个新书包。", "target_word": "个", "complexity_tier": "T3", "furigana": "wǒ xiǎng mǎi ge xīn shūbāo", "sentence_source": "generated"}, {"text": "她家有四个人。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天等了他一个小时。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里有十几个学生。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有三个苹果。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司新来了两个同事。", "target_word": "个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "個", "label": "繁体"}, {"form": "个个", "label": "重叠"}], "register": "中性", "sense_fingerprint": "通用量词，用于人或没有专用量词的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85692, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "个", "is_correct": true, "explanation": "正确。“个”是最常用的通用量词。"}, {"text": "哥", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是哥哥。"}, {"text": "课", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g，送气与否），声调相同，意思是课程。"}, {"text": "客", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），声调相同，意思是客人。"}, {"text": "格", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是格子。"}], "explanations": {"个": "正确。“个”是最常用的通用量词。", "哥": "gē（第一声）与 gè（第四声）声调不同，意思是哥哥。", "课": "kè 与 gè 声母不同（k 与 g，送气与否），声调相同，意思是课程。", "客": "kè 与 gè 声母不同（k 与 g），声调相同，意思是客人。", "格": "gé（第二声）与 gè（第四声）声调不同，意思是格子。"}, "sentence_index": null, "correct_answer": "个"}, "level_3": {"options": [{"text": "个", "is_correct": true, "explanation": "正确。“个”是通用量词，与“哥哥”搭配，表示一个人。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”用于动物或成对之一，不用于“哥哥”这样的人。"}, {"text": "本", "is_correct": false, "explanation": "搭配：“本”用于书册，不能用来计量“哥哥”。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面物，不能用来计量“哥哥”。"}], "explanations": {"个": "正确。“个”是通用量词，与“哥哥”搭配，表示一个人。", "只": "搭配：“只”用于动物或成对之一，不用于“哥哥”这样的人。", "本": "搭配：“本”用于书册，不能用来计量“哥哥”。", "张": "搭配：“张”用于纸、桌子等平面物，不能用来计量“哥哥”。"}, "sentence_index": 0, "correct_answer": "个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他骑着一个马去公园。", "explanation": "这里应该用〈匹〉。马用“匹”计量，“个”是通用量词，不用于马。"}, {"text": "桌子上有一个信。", "explanation": "这里应该用〈封〉。信用“封”计量，“个”不用于信。"}, {"text": "院子里有一个树。", "explanation": "这里应该用〈棵〉。树用“棵”计量，“个”不用于树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, valid