INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85692, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "个", "is_correct": true, "explanation": "正确。“个”是最常用的通用量词。"}, {"text": "歌", "is_correct": false, "explanation": "gē（第一声）与 gè（第四声）声调不同，意思是歌曲。"}, {"text": "隔", "is_correct": false, "explanation": "gé（第二声）与 gè（第四声）声调不同，意思是隔开。"}, {"text": "刻", "is_correct": false, "explanation": "kè 与 gè 声母不同（k 与 g），声调相同，意思是时刻。"}], "explanations": {"个": "正确。“个”是最常用的通用量词。", "歌": "gē（第一声）与 gè（第四声）声调不同，意思是歌曲。", "隔": "gé（第二声）与 gè（第四声）声调不同，意思是隔开。", "刻": "kè 与 gè 声母不同（k 与 g），声调相同，意思是时刻。"}, "sentence_index": null, "correct_answer": "个"}, "level_3": {"options": [{"text": "个", "is_correct": true, "explanation": "正确。“一个小时”中的“个”是通用量词，用于计量时长。"}, {"text": "次", "is_correct": false, "explanation": "搭配：“次”用于动作的次数，不能用来计量“小时”。"}, {"text": "段", "is_correct": false, "explanation": "搭配：“段”多用于一段时间或路程，不直接和“小时”搭配，“一段小时”不通。"}, {"text": "场", "is_correct": false, "explanation": "语义：“场”用于一场比赛、一场雨等事件，不能计量时长。"}], "explanations": {"个": "正确。“一个小时”中的“个”是通用量词，用于计量时长。", "次": "搭配：“次”用于动作的次数，不能用来计量“小时”。", "段": "搭配：“段”多用于一段时间或路程，不直接和“小时”搭配，“一段小时”不通。", "场": "语义：“场”用于一场比赛、一场雨等事件，不能计量时长。"}, "sentence_index": 6, "correct_answer": "个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我口渴了，想喝一个水。", "explanation": "水是不可数的液体，要用容器量词，应说〈一杯水〉。“个”不能直接修饰“水”。"}, {"text": "饭桌上放着一个茶。", "explanation": "茶要用容器量词，应说〈一杯茶〉。“个”不能直接修饰“茶”。"}, {"text": "我买了一个米。", "explanation": "米要用容器量词，应说〈一袋米〉。“个”不能用于米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85692, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有两个个学生。", "corrected_sentence": "我们班有两个学生。", "error_description": "量词“个”重复了。数词和名词之间只用一个“个”，应说“两个学生”，不能写成“两个个学生”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85692, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校门口有三个个小店。", "corrected_sentence": "学校门口有三个小店。", "error_description": "量词“个”重复了。数词和名词之间只用一个“个”，应说“三个小店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
