INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85693, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "“可以”是说能这样做，大人也同意这样做。", "primary_collocate": null, "pronunciation": "kě yǐ", "ipa": "kʰɤ˨˩˦ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "妈妈说我可以看电视。", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸说，你可以出去玩。", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，我们可以回家了。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭，你就可以玩手机。", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "作业写完了，我可以去公园吗？", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶说今天不冷，我可以不穿外衣。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈同意了，我可以和朋友去看电影。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里可以吃东西吗？", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生说他可以回学校上课了。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷说，小孩子也可以喝一点茶。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可以", "label": "否定式"}, {"form": "可不可以", "label": "正反问"}], "register": "中性", "sense_fingerprint": "大人同意、允许这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85693, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可以", "is_correct": true, "explanation": "正确答案：可以（kěyǐ），表示许可。"}, {"text": "可疑", "is_correct": false, "explanation": "可疑（kěyí）第二字声调与 yǐ 不同（第二声），意思是令人怀疑。"}, {"text": "可喜", "is_correct": false, "explanation": "可喜（kěxǐ）第二字声母 x 与 y 不同，声调相同，意思是令人高兴。"}, {"text": "可比", "is_correct": false, "explanation": "可比（kěbǐ）第二字声母 b 与 y 不同，声调相同，意思是可以比较。"}], "explanations": {"可以": "正确答案：可以（kěyǐ），表示许可。", "可疑": "可疑（kěyí）第二字声调与 yǐ 不同（第二声），意思是令人怀疑。", "可喜": "可喜（kěxǐ）第二字声母 x 与 y 不同，声调相同，意思是令人高兴。", "可比": "可比（kěbǐ）第二字声母 b 与 y 不同，声调相同，意思是可以比较。"}, "sentence_index": null, "correct_answer": "可以"}, "level_3": {"options": [{"text": "可以", "is_correct": true, "explanation": "正确：“妈妈说我可以看电视”中的“可以”表示大人许可，符合语境。"}, {"text": "但是", "is_correct": false, "explanation": "语法：“但是”是连词，不能放在主语“我”和动词“看”之间。"}, {"text": "所以", "is_correct": false, "explanation": "语法：“所以”是连词，不能放在“我”和“看电视”之间，“我所以看电视”不通。"}, {"text": "得以", "is_correct": false, "explanation": "语域：“得以”是书面语，口语不说“妈妈说我得以看电视”，且意思是“能够”而非许可。"}], "explanations": {"可以": "正确：“妈妈说我可以看电视”中的“可以”表示大人许可，符合语境。", "但是": "语法：“但是”是连词，不能放在主语“我”和动词“看”之间。", "所以": "语法：“所以”是连词，不能放在“我”和“看电视”之间，“我所以看电视”不通。", "得以": "语域：“得以”是书面语，口语不说“妈妈说我得以看电视”，且意思是“能够”而非许可。"}, "sentence_index": 0, "correct_answer": "可以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校规定，学生可以在教室里吸烟。", "explanation": "这里应该用〈不能〉。学校禁烟，说“可以吸烟”表示许可与规定相悖，应说“不能”。"}, {"text": "爸爸说，你可以在马路中间踢球。", "explanation": "这里应该用〈不能〉。在马路中间踢球很危险，大人不会允许，应说“不能”。"}, {"text": "妈妈说，你可以把作业扔到窗外。", "explanation": "这里应该用〈不能〉。把作业扔出窗外不被允许，用“可以”表示许可与语境相悖，应说“不能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可以", "is_correct": true, "explanation": "正确：“妈妈同意了，我可以和朋友去看电影”中的“可以”表示许可，与“同意”相符。"}, {"text": "所以", "is_correct": false, "explanation": "语法：“所以”是连词，要放在句首，不能放在“我”和“和朋友”之间。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”引出原因，“我因为和朋友去看电影”句子不完整，也不表示许可。"}, {"text": "不能", "is_correct": false, "explanation": "语义：妈妈已经同意，说“我不能……去看电影”与“同意”矛盾。"}], "explanations": {"可以": "正确：“妈妈同意了，我可以和朋友去看电影”中的“可以”表示许可，与“同意”相符。", "所以": "语法：“所以”是连词，要放在句首，不能放在“我”和“和朋友”之间。", "因为": "语法：“因为”引出原因，“我因为和朋友去看电影”句子不完整，也不表示许可。", "不能": "语义：妈妈已经同意，说“我不能……去看电影”与“同意”矛盾。"}, "sentence_index": 6, "correct_answer": "可以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "爷爷说，小孩子可以喝酒。", "explanation": "这里应该用〈不能〉。小孩子喝酒不被允许，用“可以”表示许可与常理相悖，应说“不能”。"}, {"text": "奶奶可以了我的请求。", "explanation": "这里应该用〈答应〉。“可以”是能愿动词，不能直接带宾语“我的请求”；“答应”可以这样用。"}, {"text": "这只猫可以用汉语写作业。", "explanation": "这里应该用〈不能〉。猫不会写作业，用“可以”表示能力或许可都说不通，应说“不能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师说，你没可以先回家。", "corrected_sentence": "老师说，你可以先回家。", "error_description": "否定形式错误：“可以”表示许可时不能用“没”否定。应删去“没”，写成“老师说，你可以先回家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈同意了，我没可以去公园。", "corrected_sentence": "妈妈同意了，我可以去公园。", "error_description": "否定形式错误：“可以”表示许可时不能用“没”否定。应删去“没”，写成“妈妈同意了，我可以去公园”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
