INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85694, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "能愿动词，表示有可能、有能力，或表示许可、同意。", "primary_collocate": null, "pronunciation": "kě yǐ", "ipa": "kʰɤ˨˩˦ i˨˩˦", "syllable_count": 2, "sentences": [{"text": "你可以坐在这里。", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这里可以停车吗？", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我可以用你的笔吗？", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天你可以来我家玩。", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会说汉语，可以帮你翻译。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，我们可以在家看电影。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间很大，可以住四个人。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你有时间的话，可以和我们一起去。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐地铁可以很快到公司。", "target_word": "可以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书很简单，小学生也可以看懂。", "target_word": "可以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可以", "label": "否定式"}, {"form": "可不可以", "label": "正反问"}], "register": "中性", "sense_fingerprint": "表示有可能、有能力或许可", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '628b2333-0eb6-4215-84dd-38c7b4eb1246') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85694, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "可以", "is_correct": true, "explanation": "正确答案：可以（kěyǐ），表示能力、可能或许可。"}, {"text": "可疑", "is_correct": false, "explanation": "可疑（kěyí）第二字声调与 yǐ 不同（第二声），意思是令人怀疑。"}, {"text": "可喜", "is_correct": false, "explanation": "可喜（kěxǐ）第二字声母 x 与 y 不同，声调相同（第三声），意思是令人高兴。"}, {"text": "可比", "is_correct": false, "explanation": "可比（kěbǐ）第二字声母 b 与 y 不同，声调相同（第三声），意思是可以比较。"}], "explanations": {"可以": "正确答案：可以（kěyǐ），表示能力、可能或许可。", "可疑": "可疑（kěyí）第二字声调与 yǐ 不同（第二声），意思是令人怀疑。", "可喜": "可喜（kěxǐ）第二字声母 x 与 y 不同，声调相同（第三声），意思是令人高兴。", "可比": "可比（kěbǐ）第二字声母 b 与 y 不同，声调相同（第三声），意思是可以比较。"}, "sentence_index": null, "correct_answer": "可以"}, "level_3": {"options": [{"text": "可以", "is_correct": true, "explanation": "正确：“你可以坐在这里”中的“可以”表示许可，符合语境。"}, {"text": "但是", "is_correct": false, "explanation": "语法：“但是”是连词，不能放在“你”和“坐”之间。"}, {"text": "所以", "is_correct": false, "explanation": "语法：“所以”是连词，“你所以坐在这里”不通。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“你因为坐在这里”句子不完整，“因为”不能表示许可。"}], "explanations": {"可以": "正确：“你可以坐在这里”中的“可以”表示许可，符合语境。", "但是": "语法：“但是”是连词，不能放在“你”和“坐”之间。", "所以": "语法：“所以”是连词，“你所以坐在这里”不通。", "因为": "语法：“你因为坐在这里”句子不完整，“因为”不能表示许可。"}, "sentence_index": 0, "correct_answer": "可以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生可以在考试时作弊。", "explanation": "这里应该用〈不能〉。“可以”表示允许或能力，说违规的事要用“不能”，“可以作弊”说成了允许，意思不对。"}, {"text": "这么小的盒子可以装下一头大象。", "explanation": "这里应该用〈不能〉。盒子装不下大象，用“可以”表示能力或可能说不通，应说“不能”。"}, {"text": "这间教室可以大声吃饭。", "explanation": "这里应该用〈不能〉。“可以”表示允许，教室里大声吃饭是禁止的，应说“不能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85694, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可以", "is_correct": true, "explanation": "正确：“这个房间很大，可以住四个人”中的“可以”表示能容纳，符合语境。"}, {"text": "肯", "is_correct": false, "explanation": "搭配：“肯”要求有意愿的主语，房间不能“肯”住人。"}, {"text": "愿", "is_correct": false, "explanation": "搭配：“愿”的主语须是有意愿的人，房子不能“愿”住四个人。"}, {"text": "不能", "is_correct": false, "explanation": "语义：“这个房间很大，不能住四个人”与“能住四人”的意思相反。"}], "explanations": {"可以": "正确：“这个房间很大，可以住四个人”中的“可以”表示能容纳，符合语境。", "肯": "搭配：“肯”要求有意愿的主语，房间不能“肯”住人。", "愿": "搭配：“愿”的主语须是有意愿的人，房子不能“愿”住四个人。", "不能": "语义：“这个房间很大，不能住四个人”与“能住四人”的意思相反。"}, "sentence_index": 6, "correct_answer": "可以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生可以在图书馆里大声喧哗。", "explanation": "这里应该用〈不能〉。“可以”表示许可，图书馆里大声喧哗是禁止的，应说“不能”。"}, {"text": "我可以一个人搬动这座大山。", "explanation": "这里应该用〈不能〉。一个人搬动大山办不到，用“可以”表示能力说不通，应说“不能”。"}, {"text": "这条鱼可以在沙漠里生活。", "explanation": "这里应该用〈不能〉。鱼离开水活不了，用“可以”表示能力或可能说不通，应说“不能”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85694, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天没可以去北京。", "corrected_sentence": "我明天可以去北京。", "error_description": "否定形式错误：“可以”不能用“没”否定，应说“不可以”或“不能”。这里应删去“没”，写成“我明天可以去北京”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85694, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个停车场没可以停五十辆车。", "corrected_sentence": "这个停车场可以停五十辆车。", "error_description": "否定形式错误：表示能容纳时，“可以”前面不能加“没”。应删去“没”，写成“这个停车场可以停五十辆车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8097d4b-aabc-4497-9843-d2650f3f1805') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
