INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85697, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "说了几样东西以后，再说“等”，是告诉别人还有别的一样的东西。", "primary_collocate": null, "pronunciation": "děng", "ipa": "tɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "我喜欢苹果、香蕉、西瓜等水果。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有书、笔、本子等东西。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京、上海、广州等大城市人很多。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他会说英语、法语、日语等语言。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里卖米、面、油等食品。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近有医院、银行、商店等。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天常见的花有荷花、玫瑰等。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了衣服、鞋子、帽子等东西。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有猫、狗、鸟等小动物。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校有篮球、足球、网球等运动。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "等等", "label": "重叠"}], "register": "中性", "sense_fingerprint": "列举几样事物后，表示还有同类的未列出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59327ee7-06ff-40ff-9a8c-59a74be07909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85697, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "等", "is_correct": true, "explanation": "等（děng）是助词，用在列举的事物之后，表示还有同类的未列出。"}, {"text": "灯", "is_correct": false, "explanation": "灯（dēng，第一声）与等（děng，第三声）声调不同，意思是灯。"}, {"text": "凳", "is_correct": false, "explanation": "凳（dèng，第四声）与等（děng，第三声）声调不同，意思是凳子。"}, {"text": "挡", "is_correct": false, "explanation": "挡（dǎng）与等（děng）韵母不同（ang 与 eng），意思是阻挡。"}, {"text": "冷", "is_correct": false, "explanation": "冷（lěng）与等（děng）声母不同（l 与 d），意思是寒冷。"}], "explanations": {"等": "等（děng）是助词，用在列举的事物之后，表示还有同类的未列出。", "灯": "灯（dēng，第一声）与等（děng，第三声）声调不同，意思是灯。", "凳": "凳（dèng，第四声）与等（děng，第三声）声调不同，意思是凳子。", "挡": "挡（dǎng）与等（děng）韵母不同（ang 与 eng），意思是阻挡。", "冷": "冷（lěng）与等（děng）声母不同（l 与 d），意思是寒冷。"}, "sentence_index": null, "correct_answer": "等"}, "level_3": {"options": [{"text": "等", "is_correct": true, "explanation": "“等”是助词，用在列举的末项之后，表示还有同类的水果。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“西瓜的水果”把西瓜当作水果的所属，语义不通，与并列列举的语境不符。"}, {"text": "之", "is_correct": false, "explanation": "语域：“之”是文言用法，口语列举句中不用，“西瓜之水果”书面且生硬。"}, {"text": "般", "is_correct": false, "explanation": "语域：“般”是书面语，表示“像……一样”，口语中不接在并列名词后面。"}], "explanations": {"等": "“等”是助词，用在列举的末项之后，表示还有同类的水果。", "的": "搭配：“西瓜的水果”把西瓜当作水果的所属，语义不通，与并列列举的语境不符。", "之": "语域：“之”是文言用法，口语列举句中不用，“西瓜之水果”书面且生硬。", "般": "语域：“般”是书面语，表示“像……一样”，口语中不接在并列名词后面。"}, "sentence_index": 0, "correct_answer": "等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢苹果、汽车、老师等。", "explanation": "“等”概括的必须是同类事物；苹果、汽车、老师不属同类，误用了“等”的概括义。"}, {"text": "我喜欢等苹果、香蕉、西瓜水果。", "explanation": "“等”必须放在列举的末项之后，不能放在列举项前面。"}, {"text": "我喜欢春天、北京、星期一等。", "explanation": "春天、北京、星期一分属时间与地点等不同类别，“等”不能用来概括它们。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85697, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "等", "is_correct": true, "explanation": "等（děng）是助词，用在列举的事物之后，表示还有同类的未列出。"}, {"text": "登", "is_correct": false, "explanation": "登（dēng，第一声）与等（děng，第三声）声调不同，意思是登上。"}, {"text": "党", "is_correct": false, "explanation": "党（dǎng）与等（děng）韵母不同（ang 与 eng），意思是政党。"}, {"text": "瞪", "is_correct": false, "explanation": "瞪（dèng，第四声）与等（děng，第三声）声调不同，意思是睁大眼睛看。"}], "explanations": {"等": "等（děng）是助词，用在列举的事物之后，表示还有同类的未列出。", "登": "登（dēng，第一声）与等（děng，第三声）声调不同，意思是登上。", "党": "党（dǎng）与等（děng）韵母不同（ang 与 eng），意思是政党。", "瞪": "瞪（dèng，第四声）与等（děng，第三声）声调不同，意思是睁大眼睛看。"}, "sentence_index": null, "correct_answer": "等"}, "level_3": {"options": [{"text": "等", "is_correct": true, "explanation": "“等”是助词，置于列举之后，表示列举未尽。"}, {"text": "罢了", "is_correct": false, "explanation": "语义：“罢了”表示“仅此而已”，与“常见的花有……”的列举未尽语义相反。"}, {"text": "的", "is_correct": false, "explanation": "搭配：句末的“的”需要指代前面的中心语，“玫瑰的”后面没有中心语，不成句。"}, {"text": "着", "is_correct": false, "explanation": "语法：“着”是动态助词，只接在动词后，不能接在名词“玫瑰”后，句子不成立。"}], "explanations": {"等": "“等”是助词，置于列举之后，表示列举未尽。", "罢了": "语义：“罢了”表示“仅此而已”，与“常见的花有……”的列举未尽语义相反。", "的": "搭配：句末的“的”需要指代前面的中心语，“玫瑰的”后面没有中心语，不成句。", "着": "语法：“着”是动态助词，只接在动词后，不能接在名词“玫瑰”后，句子不成立。"}, "sentence_index": 6, "correct_answer": "等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我喜欢猫、香蕉、医生等。", "explanation": "猫、香蕉、医生分属动物、食物、职业，不同类，不能用“等”概括同类事物。"}, {"text": "公园里有等猫、狗、鸟小动物。", "explanation": "“等”必须放在列举的末项之后，不能放在列举项前面。"}, {"text": "我喜欢红色、星期二、警察等。", "explanation": "红色、星期二、警察不同类，误用了“等”的概括义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85697, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢草莓、葡萄、芒果等的水果。", "corrected_sentence": "我喜欢草莓、葡萄、芒果等水果。", "error_description": "错误形式：“芒果等的水果”；正确形式：“芒果等水果”。“等”后直接接中心语，中间不能加“的”，“的”会把“等”与“水果”拆开，破坏列举结构。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85697, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有数学、英语、物理等的课程。", "corrected_sentence": "我们班有数学、英语、物理等课程。", "error_description": "错误形式：“物理等的课程”；正确形式：“物理等课程”。“等”后直接接中心语，中间不能加“的”，“的”会把“等”与“课程”拆开，破坏列举结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
