INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85698, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "助词，用在列举的末项之后，表示列举到此结束，后常接数量词。", "primary_collocate": null, "pronunciation": "děng", "ipa": "tɤŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "张明、李红、王力等三个人来了。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议上，经理、老师等两位发了言。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "红、黄、蓝等三种颜色我都喜欢。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸、妈妈、哥哥等四人去了北京。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学了听、说、读、写等四种技能。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春、夏、秋、冬等四个季节我都爱。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京、天津、上海等三个城市我去过。", "target_word": "等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果、梨、桃等三种水果都很甜。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王、小李等两位同学得了奖。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "米饭、面条、饺子等三种我都爱吃。", "target_word": "等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "等等", "label": "重叠"}], "register": "中性", "sense_fingerprint": "列举之后煞尾，常接数量，表示列举结束", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 米饭 (Zipf 3.68), 面条 (Zipf 3.78), 饺子 (Zipf 3.62)']::text[], '59327ee7-06ff-40ff-9a8c-59a74be07909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85698, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "等", "is_correct": true, "explanation": "等（děng）是助词，用在列举的末项之后，表示列举结束。"}, {"text": "灯", "is_correct": false, "explanation": "灯（dēng，第一声）与等（děng，第三声）声调不同，意思是灯。"}, {"text": "凳", "is_correct": false, "explanation": "凳（dèng，第四声）与等（děng，第三声）声调不同，意思是凳子。"}, {"text": "挡", "is_correct": false, "explanation": "挡（dǎng）与等（děng）韵母不同（ang 与 eng），意思是阻挡。"}, {"text": "冷", "is_correct": false, "explanation": "冷（lěng）与等（děng）声母不同（l 与 d），意思是寒冷。"}], "explanations": {"等": "等（děng）是助词，用在列举的末项之后，表示列举结束。", "灯": "灯（dēng，第一声）与等（děng，第三声）声调不同，意思是灯。", "凳": "凳（dèng，第四声）与等（děng，第三声）声调不同，意思是凳子。", "挡": "挡（dǎng）与等（děng）韵母不同（ang 与 eng），意思是阻挡。", "冷": "冷（lěng）与等（děng）声母不同（l 与 d），意思是寒冷。"}, "sentence_index": null, "correct_answer": "等"}, "level_3": {"options": [{"text": "等", "is_correct": true, "explanation": "“等”是助词，用在列举的末项之后，表示列举结束，后接数量。"}, {"text": "的", "is_correct": false, "explanation": "搭配：“王力的三个人”把王力当作三人的所属，与并列的“张明、李红”矛盾。"}, {"text": "之", "is_correct": false, "explanation": "语域：“之”是文言用法，口语中不用，“王力之三个人”生硬。"}, {"text": "般", "is_correct": false, "explanation": "语域：“般”为书面语，表示“像……一样”，不用于口语中人名之后。"}], "explanations": {"等": "“等”是助词，用在列举的末项之后，表示列举结束，后接数量。", "的": "搭配：“王力的三个人”把王力当作三人的所属，与并列的“张明、李红”矛盾。", "之": "语域：“之”是文言用法，口语中不用，“王力之三个人”生硬。", "般": "语域：“般”为书面语，表示“像……一样”，不用于口语中人名之后。"}, "sentence_index": 0, "correct_answer": "等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "红、黄、星期一等三种颜色我都喜欢。", "explanation": "“三种颜色”要求列举项都是颜色，星期一不是颜色，“等”后的列举不成立。"}, {"text": "我家有一台电视机等。", "explanation": "只有一件事物，没有列举，“等”不表示列举结束。"}, {"text": "春、夏、汽车、冬等四个季节我都爱。", "explanation": "汽车不是季节，列举项不同类，“等”后的数量“四个季节”与列举不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85698, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "等", "is_correct": true, "explanation": "等（děng）是助词，用在列举的末项之后，表示列举结束。"}, {"text": "登", "is_correct": false, "explanation": "登（dēng，第一声）与等（děng，第三声）声调不同，意思是登上。"}, {"text": "党", "is_correct": false, "explanation": "党（dǎng）与等（děng）韵母不同（ang 与 eng），意思是政党。"}, {"text": "瞪", "is_correct": false, "explanation": "瞪（dèng，第四声）与等（děng，第三声）声调不同，意思是睁大眼睛看。"}], "explanations": {"等": "等（děng）是助词，用在列举的末项之后，表示列举结束。", "登": "登（dēng，第一声）与等（děng，第三声）声调不同，意思是登上。", "党": "党（dǎng）与等（děng）韵母不同（ang 与 eng），意思是政党。", "瞪": "瞪（dèng，第四声）与等（děng，第三声）声调不同，意思是睁大眼睛看。"}, "sentence_index": null, "correct_answer": "等"}, "level_3": {"options": [{"text": "等", "is_correct": true, "explanation": "“等”是助词，用在列举的末项之后，表示列举结束。"}, {"text": "似的", "is_correct": false, "explanation": "语义：“似的”表示“像……一样”，把所列城市变成比喻，与列举结束、三个确定城市的意思不符。"}, {"text": "们", "is_correct": false, "explanation": "语义：“们”表示复数，多接在人称代词或人名之后，不接在城市名之后，句意不通。"}, {"text": "呢", "is_correct": false, "explanation": "语义：“呢”用于提起话题或询问，把话题转向城市，与“三个城市我去过”的陈述语义不符。"}], "explanations": {"等": "“等”是助词，用在列举的末项之后，表示列举结束。", "似的": "语义：“似的”表示“像……一样”，把所列城市变成比喻，与列举结束、三个确定城市的意思不符。", "们": "语义：“们”表示复数，多接在人称代词或人名之后，不接在城市名之后，句意不通。", "呢": "语义：“呢”用于提起话题或询问，把话题转向城市，与“三个城市我去过”的陈述语义不符。"}, "sentence_index": 6, "correct_answer": "等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "张明、李红、春天等三个人来了。", "explanation": "列举项中的“春天”不是人，“等”后的“三个人”与列举项不同类。"}, {"text": "红、黄、椅子等三种颜色我都喜欢。", "explanation": "椅子不是颜色，列举项不同类，不能用“等”概括。"}, {"text": "苹果、梨、电脑等三种水果都很甜。", "explanation": "电脑不是水果，列举项不同类，与“三种水果”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85698, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "张三、李四、王五等的三个人参加了比赛。", "corrected_sentence": "张三、李四、王五等三个人参加了比赛。", "error_description": "错误形式：“王五等的三个人”；正确形式：“王五等三个人”。“等”后直接接数量短语，中间不能加“的”，“的”会切断“等”与数量短语的结合。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85698, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小赵、小钱等两位同学等参加了比赛。", "corrected_sentence": "小赵、小钱等两位同学参加了比赛。", "error_description": "错误形式：“小赵、小钱等两位同学等参加了比赛”；正确形式去掉多余的第二个“等”。“等”在一句中只用于列举末项之后，此处在“两位同学”后又加“等”，重复且没有列举可收尾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
