INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85701, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“于”是一个小词，说明事情在哪里、什么时候发生，或者从哪里来。", "primary_collocate": null, "pronunciation": "yú", "ipa": "y˧˥", "syllable_count": 1, "sentences": [{"text": "他生于一九九〇年。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城位于河边。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业于北京大学。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家位于学校的东边。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他出生于上海，现在住在北京。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书出版于二〇一八年。", "target_word": "于", "complexity_tier": "T3", "furigana": "zhè běn shū chūbǎn yú èr líng yī bā nián.", "sentence_source": "generated"}, {"text": "爷爷生于冬天，所以叫冬生。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院位于市中心。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他毕业于一所很好的大学。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥建于一九八五年。", "target_word": "于", "complexity_tier": "T3", "furigana": "zhè zuò qiáo jiàn yú yī jiǔ bā wǔ nián.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "介词：表示时间、地点或来源，常用于“生于、位于、毕业于”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85701, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "于", "is_correct": true, "explanation": "yú（第二声）是介词“于”，正确答案。"}, {"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨水。"}, {"text": "遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是遇见。"}, {"text": "云", "is_correct": false, "explanation": "yún 与 yú 韵尾不同（多一个 n），声调相同，意思是云彩。"}], "explanations": {"于": "yú（第二声）是介词“于”，正确答案。", "雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨水。", "遇": "yù（第四声）与 yú（第二声）声调不同，意思是遇见。", "云": "yún 与 yú 韵尾不同（多一个 n），声调相同，意思是云彩。"}, "sentence_index": null, "correct_answer": "于"}, "level_3": {"options": [{"text": "于", "is_correct": true, "explanation": "“于”是书面介词，引出出生的时间，“生于一九九〇年”说法规范。"}, {"text": "由", "is_correct": false, "explanation": "语义：「由」表示来源或经由，不表示出生的时间。"}, {"text": "朝", "is_correct": false, "explanation": "配价：「朝」引出动作的方向，不能引出出生的时间。"}, {"text": "为", "is_correct": false, "explanation": "语义：「为」表示目的或作为，与出生的时间无关。"}], "explanations": {"于": "“于”是书面介词，引出出生的时间，“生于一九九〇年”说法规范。", "由": "语义：「由」表示来源或经由，不表示出生的时间。", "朝": "配价：「朝」引出动作的方向，不能引出出生的时间。", "为": "语义：「为」表示目的或作为，与出生的时间无关。"}, "sentence_index": 0, "correct_answer": "于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的同桌于学校吃午饭。", "explanation": "这里应该用〈在〉。表示在某处做事用“在”，说“在学校吃午饭”，“于”不能这样用。"}, {"text": "他于我借了一本书。", "explanation": "这里应该用〈向〉。借东西时引出对象要用“向”，说“向我借了一本书”，“于”不能这样用。"}, {"text": "她于厨房做了早饭。", "explanation": "这里应该用〈在〉。表示在某个地方做事用“在”，说“在厨房做早饭”，“于”不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85701, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "于", "is_correct": true, "explanation": "yú（第二声）是介词“于”，正确答案。"}, {"text": "语", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。"}, {"text": "局", "is_correct": false, "explanation": "jú 与 yú 声母不同（j 与 y），声调相同，意思是局面。"}], "explanations": {"于": "yú（第二声）是介词“于”，正确答案。", "语": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。", "玉": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。", "局": "jú 与 yú 声母不同（j 与 y），声调相同，意思是局面。"}, "sentence_index": null, "correct_answer": "于"}, "level_3": {"options": [{"text": "于", "is_correct": true, "explanation": "“于”是书面介词，引出出生的时间，“生于冬天”说法规范。"}, {"text": "从", "is_correct": false, "explanation": "配价：「生」后引出出生的时间只能用「于」或「在」，「从」不能这样用。"}, {"text": "向", "is_correct": false, "explanation": "配价：「向」引出动作的方向，不能引出出生的时间。"}, {"text": "对", "is_correct": false, "explanation": "语义：「对」引出对象，与“出生在哪个季节”的意思无关。"}], "explanations": {"于": "“于”是书面介词，引出出生的时间，“生于冬天”说法规范。", "从": "配价：「生」后引出出生的时间只能用「于」或「在」，「从」不能这样用。", "向": "配价：「向」引出动作的方向，不能引出出生的时间。", "对": "语义：「对」引出对象，与“出生在哪个季节”的意思无关。"}, "sentence_index": 6, "correct_answer": "于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我于老师问了一个问题。", "explanation": "这里应该用〈向〉。问问题时引出对象要用“向”，说“向老师问了一个问题”，“于”不能这样用。"}, {"text": "妈妈于我买了一件衣服。", "explanation": "这里应该用〈给〉。表示给予、引出接受者要用“给”，说“给我买了一件衣服”，“于”不能这样用。"}, {"text": "我于朋友一起去。", "explanation": "这里应该用〈跟〉。表示同伴要用“跟”，说“跟朋友一起去”，“于”不能引出同伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所医院位在于城南。", "corrected_sentence": "这所医院位于城南。", "error_description": "错误：“位”和“于”之间多加了“在”，成了“位在于”。正确：“位于城南”。“位于”是固定搭配，“在”与“于”只留一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路建在于二〇〇〇年。", "corrected_sentence": "这条路建于二〇〇〇年。", "error_description": "错误：“建”和“于”之间多加了“在”，成了“建在于”。正确：“建于二〇〇〇年”。书面语中“建于”后接时间，“在”与“于”只留一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
