INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85702, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示时间、地点、对象、来源等，相当于“在”“从”“向”“对”。", "primary_collocate": null, "pronunciation": "yú", "ipa": "y˧˥", "syllable_count": 1, "sentences": [{"text": "他生于上海，长于北京。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老师毕业于北京大学。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司位于市中心。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果富含维生素，有益于身体。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的成功得益于努力。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果来自于南方。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那所学校坐落于山脚下。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多喝水有利于身体健康。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位画家出生于一个小城市。", "target_word": "于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座寺庙建于唐朝。", "target_word": "于", "complexity_tier": "T3", "furigana": "zhè zuò sì miào jiàn yú Táng cháo.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "书面介词，接在动词或形容词后，引出时间、地点、对象或来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bfeb4457-02e8-4e80-8df6-6e789a775f8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85702, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "于", "is_correct": true, "explanation": "yú（第二声）是介词“于”，正确答案。"}, {"text": "语", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。"}, {"text": "遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。"}, {"text": "局", "is_correct": false, "explanation": "jú 与 yú 声母不同（j 与 y），声调相同，意思是局面。"}], "explanations": {"于": "yú（第二声）是介词“于”，正确答案。", "语": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。", "遇": "yù（第四声）与 yú（第二声）声调不同，意思是遇到。", "局": "jú 与 yú 声母不同（j 与 y），声调相同，意思是局面。"}, "sentence_index": null, "correct_answer": "于"}, "level_3": {"options": [{"text": "于", "is_correct": true, "explanation": "“于”是书面介词，引出出生的地点，“生于上海”说法规范。"}, {"text": "从", "is_correct": false, "explanation": "配价：「生」后引出出生地只能用「于」或「在」，「从」不能引出出生地。"}, {"text": "向", "is_correct": false, "explanation": "配价：「向」引出动作的方向，不能引出出生的地点。"}, {"text": "对", "is_correct": false, "explanation": "语义：「对」引出对象，与“出生在哪里”的意思无关。"}], "explanations": {"于": "“于”是书面介词，引出出生的地点，“生于上海”说法规范。", "从": "配价：「生」后引出出生地只能用「于」或「在」，「从」不能引出出生地。", "向": "配价：「向」引出动作的方向，不能引出出生的地点。", "对": "语义：「对」引出对象，与“出生在哪里”的意思无关。"}, "sentence_index": 0, "correct_answer": "于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们于学校吃饭了。", "explanation": "这里应该用〈在〉。表示在某处做事用“在”，说“在学校吃饭”，“于”不能这样用。"}, {"text": "她于同学借了一支笔。", "explanation": "这里应该用〈向〉。借东西时引出对象要用“向”，说“向同学借了一支笔”，“于”不能这样用。"}, {"text": "我于同桌玩了一天。", "explanation": "这里应该用〈和〉。表示同伴要用“和”，说“和同桌玩了一天”，“于”不能引出同伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85702, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "于", "is_correct": true, "explanation": "yú（第二声）是介词“于”，正确答案。"}, {"text": "宇", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是宇宙。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。"}, {"text": "云", "is_correct": false, "explanation": "yún 与 yú 韵尾不同（多一个 n），声调相同，意思是云彩。"}], "explanations": {"于": "yú（第二声）是介词“于”，正确答案。", "宇": "yǔ（第三声）与 yú（第二声）声调不同，意思是宇宙。", "玉": "yù（第四声）与 yú（第二声）声调不同，意思是玉石。", "云": "yún 与 yú 韵尾不同（多一个 n），声调相同，意思是云彩。"}, "sentence_index": null, "correct_answer": "于"}, "level_3": {"options": [{"text": "于", "is_correct": true, "explanation": "“于”是书面介词，引出处所，“坐落于山脚下”说法规范。"}, {"text": "朝", "is_correct": false, "explanation": "配价：「朝」引出动作的方向，“坐落”表示位置，不能用方向介词。"}, {"text": "由", "is_correct": false, "explanation": "语义：「由」表示来源或经由，不表示学校所在的位置。"}, {"text": "给", "is_correct": false, "explanation": "配价：「给」引出接受对象，不能表示学校所在的位置。"}], "explanations": {"于": "“于”是书面介词，引出处所，“坐落于山脚下”说法规范。", "朝": "配价：「朝」引出动作的方向，“坐落”表示位置，不能用方向介词。", "由": "语义：「由」表示来源或经由，不表示学校所在的位置。", "给": "配价：「给」引出接受对象，不能表示学校所在的位置。"}, "sentence_index": 6, "correct_answer": "于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他于书包里拿出了钥匙。", "explanation": "这里应该用〈从〉。表示从某处拿出东西用“从”，说“从书包里拿出钥匙”，“于”不这样用。"}, {"text": "他于我一本书。", "explanation": "这里应该用〈给〉。引出接受者的双宾结构要用“给”，说“给我一本书”，“于”不能这样用。"}, {"text": "她于弟弟一起去公园。", "explanation": "这里应该用〈跟〉。表示同伴要用“跟”，说“跟弟弟一起去”，“于”不能引出同伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我奶奶生在于河北农村。", "corrected_sentence": "我奶奶生于河北农村。", "error_description": "错误：“生”和“于”之间多加了“在”，成了“生在于”。正确：“生于河北农村”（“生在”与“生于”二者只取其一；书面语常用“于”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座公园坐落在于城市中心。", "corrected_sentence": "这座公园坐落于城市中心。", "error_description": "错误：“坐落”和“于”之间多加了“在”，成了“坐落在于”。正确：“坐落于城市中心”。“坐落于”是固定搭配，“在”与“于”只留一个。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '191ff4f8-1b89-4519-833c-ee98ddee1cc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
