INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85703, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“什么”是用来问是哪样东西或哪件事的。", "primary_collocate": null, "pronunciation": "shén me", "ipa": "ʂən˧˥ mɤ", "syllable_count": 2, "sentences": [{"text": "你喜欢吃什么？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上是什么？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是什么书？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你想喝什么茶？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天你要做什么？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他手里拿着什么？", "target_word": "什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在看什么？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你今天买了什么？", "target_word": "什么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末你想去什么地方？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的包里有什么？", "target_word": "什么", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "疑问代词，询问是哪样东西或哪件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59327ee7-06ff-40ff-9a8c-59a74be07909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么", "is_correct": true, "explanation": "“什么”是疑问代词，询问所喜欢吃的是哪样东西。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”询问人，“吃”的对象应是食物，“你喜欢吃谁”语义不通。"}, {"text": "怎么", "is_correct": false, "explanation": "搭配：“怎么”不能作“吃”的宾语，“你喜欢吃怎么”不成句。"}, {"text": "怎样", "is_correct": false, "explanation": "搭配：“怎样”修饰动作的方式，不能作“吃”的宾语，搭配不当。"}], "explanations": {"什么": "“什么”是疑问代词，询问所喜欢吃的是哪样东西。", "谁": "语义：“谁”询问人，“吃”的对象应是食物，“你喜欢吃谁”语义不通。", "怎么": "搭配：“怎么”不能作“吃”的宾语，“你喜欢吃怎么”不成句。", "怎样": "搭配：“怎样”修饰动作的方式，不能作“吃”的宾语，搭配不当。"}, "sentence_index": 0, "correct_answer": "什么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个穿红衣服的人是什么的朋友？", "explanation": "“朋友”指人，所属应问“谁的朋友”；“什么”只用于询问事物，这里误用来问人。"}, {"text": "坐在窗边的那位女士是什么的同事？", "explanation": "“同事”指人，应问“谁的同事”；“什么”只用于询问事物，这里误用来问人。"}, {"text": "给我开门的那个男人是什么的邻居？", "explanation": "“邻居”指人，应问“谁的邻居”；“什么”只用于询问事物，这里误用来问人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么", "is_correct": true, "explanation": "“什么”是疑问代词，询问所看的是哪样东西。"}, {"text": "怎么", "is_correct": false, "explanation": "搭配：“怎么”问方式或原因，不能作“看”的宾语，“你在看怎么”不成句。"}, {"text": "这样", "is_correct": false, "explanation": "搭配：“这样”是指示方式，不能作“看”的宾语，“你在看这样”不成句。"}, {"text": "那样", "is_correct": false, "explanation": "语义：“那样”指示方式或状态，与“看”的对象不符，句意不通。"}], "explanations": {"什么": "“什么”是疑问代词，询问所看的是哪样东西。", "怎么": "搭配：“怎么”问方式或原因，不能作“看”的宾语，“你在看怎么”不成句。", "这样": "搭配：“这样”是指示方式，不能作“看”的宾语，“你在看这样”不成句。", "那样": "语义：“那样”指示方式或状态，与“看”的对象不符，句意不通。"}, "sentence_index": 6, "correct_answer": "什么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "站在门口的那个小孩是什么的弟弟？", "explanation": "“弟弟”指人，应问“谁的弟弟”；“什么”只用于询问事物，这里误用来问人。"}, {"text": "那位在台上唱歌的老先生是什么的爷爷？", "explanation": "“爷爷”指人，应问“谁的爷爷”；“什么”只用于询问事物，这里误用来问人。"}, {"text": "刚才打电话的那个阿姨是什么的妈妈？", "explanation": "“妈妈”指人，应问“谁的妈妈”；“什么”只用于询问事物，这里误用来问人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买的是一什么饮料？", "corrected_sentence": "他买的是什么饮料？", "error_description": "错误形式：“一什么饮料”；正确形式：“什么饮料”。“什么”是疑问代词，不能受数词“一”修饰，应直接修饰名词“饮料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你在看一什么书？", "corrected_sentence": "你在看什么书？", "error_description": "错误形式：“一什么书”；正确形式：“什么书”。“什么”是疑问代词，不能受数词“一”修饰，应直接修饰名词“书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
