INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85707, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“这个”是指离我们很近的那一个人或东西。", "primary_collocate": null, "pronunciation": "zhè ge", "ipa": "ʈʂɤ˥˩ kɤ", "syllable_count": 2, "sentences": [{"text": "这个苹果很甜。", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你喜欢这个还是那个？", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个是我哥哥。", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个字怎么读？", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我要这个，不要那个。", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个包太重了。", "target_word": "这个", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个菜是妈妈做的。", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你知道这个吗？", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小狗叫什么名字？", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个给你，那个给他。", "target_word": "这个", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "这些", "label": "复数"}], "register": "中性", "sense_fingerprint": "指离说话人很近的那一个人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59327ee7-06ff-40ff-9a8c-59a74be07909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85707, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "这个", "is_correct": true, "explanation": "“这个”指离说话人很近的那一个人或东西，是正确答案。"}, {"text": "那个", "is_correct": false, "explanation": "nà ge（那个）与 zhè ge（这个）声母不同（n 与 zh），意思是指较远的人或东西。"}, {"text": "哪个", "is_correct": false, "explanation": "nǎ ge（哪个）与 zhè ge（这个）声母不同（n 与 zh）且声调不同，意思是问哪一个。"}, {"text": "这么", "is_correct": false, "explanation": "zhè me（这么）与 zhè ge（这个）后一音节声母不同（m 与 g），意思是这样、如此。"}], "explanations": {"这个": "“这个”指离说话人很近的那一个人或东西，是正确答案。", "那个": "nà ge（那个）与 zhè ge（这个）声母不同（n 与 zh），意思是指较远的人或东西。", "哪个": "nǎ ge（哪个）与 zhè ge（这个）声母不同（n 与 zh）且声调不同，意思是问哪一个。", "这么": "zhè me（这么）与 zhè ge（这个）后一音节声母不同（m 与 g），意思是这样、如此。"}, "sentence_index": null, "correct_answer": "这个"}, "level_3": {"options": [{"text": "这个", "is_correct": true, "explanation": "“这个”指离说话人较近的那个苹果，与句意相符，是正确答案。"}, {"text": "这位", "is_correct": false, "explanation": "语义：“位”是量词，只用于人，不能修饰“苹果”。"}, {"text": "这条", "is_correct": false, "explanation": "搭配：量词“条”用于鱼、河、绳子等长条形的东西，不能说“这条苹果”。"}, {"text": "这张", "is_correct": false, "explanation": "搭配：量词“张”用于纸、桌子等平面的东西，不能说“这张苹果”。"}], "explanations": {"这个": "“这个”指离说话人较近的那个苹果，与句意相符，是正确答案。", "这位": "语义：“位”是量词，只用于人，不能修饰“苹果”。", "这条": "搭配：量词“条”用于鱼、河、绳子等长条形的东西，不能说“这条苹果”。", "这张": "搭配：量词“张”用于纸、桌子等平面的东西，不能说“这张苹果”。"}, "sentence_index": 0, "correct_answer": "这个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这个坐一会儿吧。", "explanation": "这里要指地点，应说〈这儿〉或〈这里〉；“这个”只指人或东西，不能单独指地点。"}, {"text": "你看远处那座山，这个很高。", "explanation": "“这个”指离说话人近的人或东西，远处的山应该用〈那个〉来指。"}, {"text": "他从这个跑出去了。", "explanation": "这里要指地点，应说〈这里〉或〈这儿〉；“这个”不能单独指地点，“从这个”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这个", "is_correct": true, "explanation": "“这个”指较近的那道菜，与句意相符，是正确答案。"}, {"text": "那位", "is_correct": false, "explanation": "语义：“位”是量词，只用于人，不能修饰“菜”。"}, {"text": "这匹", "is_correct": false, "explanation": "搭配：量词“匹”多用于马、骡等牲口，不说“这匹菜”。"}, {"text": "这本", "is_correct": false, "explanation": "搭配：量词“本”用于书、本子，不能说“这本菜”。"}], "explanations": {"这个": "“这个”指较近的那道菜，与句意相符，是正确答案。", "那位": "语义：“位”是量词，只用于人，不能修饰“菜”。", "这匹": "搭配：量词“匹”多用于马、骡等牲口，不说“这匹菜”。", "这本": "搭配：量词“本”用于书、本子，不能说“这本菜”。"}, "sentence_index": 6, "correct_answer": "这个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我等了这个半个小时。", "explanation": "这里表示时长，应说〈这半个小时〉；“这个”不能直接放在“半个小时”这样的数量短语前面。"}, {"text": "这个三个人都来了。", "explanation": "这里要表示数量，应说〈这三个人〉；“这个”是指示词，不能直接放在数词“三”前面。"}, {"text": "他这个笑了，然后就走了。", "explanation": "这里要描述动作的方式，应说〈这样〉或直接用副词；“这个”是指示词，不能修饰动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了这个个电脑。", "corrected_sentence": "我买了这个电脑。", "error_description": "错误形式：“这个个电脑”；正确形式：“这个电脑”。“这个”本身已含量词“个”，后面不能再加一个“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹很喜欢这个个书包。", "corrected_sentence": "妹妹很喜欢这个书包。", "error_description": "错误形式：“这个个书包”；正确形式：“这个书包”。“这个”本身已含量词“个”，后面不能再加一个“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
