INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85709, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "“并”放在“不”前面，是让别人知道事情真的不是那样。", "primary_collocate": null, "pronunciation": "bìng", "ipa": "piŋ˥˩", "syllable_count": 1, "sentences": [{"text": "他看起来很凶，其实并不可怕。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都说那家店贵，我觉得并不贵。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你以为他生气了，他并不生气。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道题看着难，做起来并不难。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然下雨，但是路上并不堵。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别人说他很懒，可是他并不懒。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我并不想去，是朋友一直叫我。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事听起来很奇怪，但并不是假的。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑了，可是心里并不快乐。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里的东西看上去不错，价格并不便宜。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "并不", "label": "复合"}, {"form": "并非", "label": "复合"}, {"form": "並", "label": "繁体"}], "register": "中性", "sense_fingerprint": "并+不：纠正别人的看法，强调事实并非如此", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59327ee7-06ff-40ff-9a8c-59a74be07909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85709, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "并", "is_correct": true, "explanation": "“并”（bìng）是副词，用在“不”前面，纠正别人的看法，是正确答案。"}, {"text": "冰", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。"}, {"text": "饼", "is_correct": false, "explanation": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。"}, {"text": "必", "is_correct": false, "explanation": "bì 没有 bìng 的韵尾 ng，意思是必定、一定。"}, {"text": "平", "is_correct": false, "explanation": "píng 与 bìng 声母不同（p 与 b）且声调不同，意思是平。"}], "explanations": {"并": "“并”（bìng）是副词，用在“不”前面，纠正别人的看法，是正确答案。", "冰": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。", "饼": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。", "必": "bì 没有 bìng 的韵尾 ng，意思是必定、一定。", "平": "píng 与 bìng 声母不同（p 与 b）且声调不同，意思是平。"}, "sentence_index": null, "correct_answer": "并"}, "level_3": {"options": [{"text": "并", "is_correct": true, "explanation": "“并不”连用表示纠正看法，强调事实并非如此，是正确答案。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”表示过度，与“不可怕”连用，句意不通，不能表达纠正的语气。"}, {"text": "更", "is_correct": false, "explanation": "语义：“更”表示程度加深，需要比较对象，这里没有比较，句意不通。"}, {"text": "没", "is_correct": false, "explanation": "语法：“没”不能与“不”连用，“其实没不可怕”不成立。"}], "explanations": {"并": "“并不”连用表示纠正看法，强调事实并非如此，是正确答案。", "太": "搭配：“太”表示过度，与“不可怕”连用，句意不通，不能表达纠正的语气。", "更": "语义：“更”表示程度加深，需要比较对象，这里没有比较，句意不通。", "没": "语法：“没”不能与“不”连用，“其实没不可怕”不成立。"}, "sentence_index": 0, "correct_answer": "并"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题并很难，我一下子就做出来了。", "explanation": "“并”是副词，只能放在“不”前表示否定，不能直接修饰肯定的“很难”，这里应说〈并不〉。"}, {"text": "你并去吗？", "explanation": "“并”后面必须接“不”或“没有”等否定词，“你并去吗”缺少否定词，句子不成立；可说〈你并不想去吗？〉。"}, {"text": "这件事并是假的。", "explanation": "“并”只用在“不”前表示否定，这里是肯定句，应直接说“是假的”，或用〈并不〉表示否定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85709, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "并", "is_correct": true, "explanation": "“并”（bìng）是副词，用在“不”前面，纠正别人的看法，是正确答案。"}, {"text": "兵", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。"}, {"text": "另", "is_correct": false, "explanation": "lìng 与 bìng 声母不同（l 与 b），意思是另外。"}, {"text": "静", "is_correct": false, "explanation": "jìng 与 bìng 声母不同（j 与 b），意思是安静。"}, {"text": "鼻", "is_correct": false, "explanation": "bí 少了 ng 韵尾且声调不同，意思是鼻子。"}], "explanations": {"并": "“并”（bìng）是副词，用在“不”前面，纠正别人的看法，是正确答案。", "兵": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。", "另": "lìng 与 bìng 声母不同（l 与 b），意思是另外。", "静": "jìng 与 bìng 声母不同（j 与 b），意思是安静。", "鼻": "bí 少了 ng 韵尾且声调不同，意思是鼻子。"}, "sentence_index": null, "correct_answer": "并"}, "level_3": {"options": [{"text": "并", "is_correct": true, "explanation": "“并不”连用表示纠正看法，强调“不想去”的事实，是正确答案。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”是介词，表示被动，不能直接放在“不想去”前面，“我被不想去”不成立。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”多修饰突出的积极状态，与否定的“不想去”连用不自然。"}, {"text": "竟", "is_correct": false, "explanation": "语义：“竟”表示出乎意料，与后面平实的叙述“是朋友一直叫我”不合。"}], "explanations": {"并": "“并不”连用表示纠正看法，强调“不想去”的事实，是正确答案。", "被": "语法：“被”是介词，表示被动，不能直接放在“不想去”前面，“我被不想去”不成立。", "格外": "搭配：“格外”多修饰突出的积极状态，与否定的“不想去”连用不自然。", "竟": "语义：“竟”表示出乎意料，与后面平实的叙述“是朋友一直叫我”不合。"}, "sentence_index": 6, "correct_answer": "并"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个办法并很好，大家都同意。", "explanation": "“并”是副词，只用于否定，不能修饰肯定的“很好”，这里应去掉〈并〉，直接说“很好”。"}, {"text": "我并知道这件事，你别瞒我。", "explanation": "“并”是加强否定语气的副词，肯定句中不能用，这里应说〈确实〉或〈的确〉。"}, {"text": "大家说他很笨，其实他并聪明。", "explanation": "“并”只用在否定词前加强否定，“并聪明”缺少否定词，应说〈并不笨〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他看着很累，其实不并累。", "corrected_sentence": "他看着很累，其实并不累。", "error_description": "“并”是副词，只能放在“不”前面，应说“并不累”；“不并累”把它放到了否定词后面，语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法听起来很难，其实并难。", "corrected_sentence": "这个办法听起来很难，其实并不难。", "error_description": "“并”必须与“不”连用，表示“并不”纠正看法；“并难”缺少否定词，句意不成立，应说“并不难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
