INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85710, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，用在否定词前，加强否定语气。", "primary_collocate": null, "pronunciation": "bìng", "ipa": "piŋ˥˩", "syllable_count": 1, "sentences": [{"text": "医生说他病了，但他并没有生病。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你以为我知道吗？我并不知道这件事。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说他来了，可我并没有看见他。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都以为我准备好了，我并没有准备好。", "target_word": "并", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师批评他，并不是因为他迟到。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是朋友，但并不常见面。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "虽然我很累，可是并不想休息。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很会说话，但并不总是对。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看了很多遍，并没有看懂。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外面很冷，屋里并不冷。", "target_word": "并", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "并不", "label": "复合"}, {"form": "并非", "label": "复合"}, {"form": "並", "label": "繁体"}], "register": "中性", "sense_fingerprint": "并+否定词：加强否定语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59327ee7-06ff-40ff-9a8c-59a74be07909') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85710, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "并", "is_correct": true, "explanation": "“并”（bìng）是副词，用在否定词前，加强否定语气，是正确答案。"}, {"text": "冰", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。"}, {"text": "饼", "is_correct": false, "explanation": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。"}, {"text": "必", "is_correct": false, "explanation": "bì 没有 bìng 的韵尾 ng，意思是必定、一定。"}, {"text": "平", "is_correct": false, "explanation": "píng 与 bìng 声母不同（p 与 b）且声调不同，意思是平。"}], "explanations": {"并": "“并”（bìng）是副词，用在否定词前，加强否定语气，是正确答案。", "冰": "bīng（第一声）与 bìng（第四声）声调不同，意思是冰。", "饼": "bǐng（第三声）与 bìng（第四声）声调不同，意思是饼。", "必": "bì 没有 bìng 的韵尾 ng，意思是必定、一定。", "平": "píng 与 bìng 声母不同（p 与 b）且声调不同，意思是平。"}, "sentence_index": null, "correct_answer": "并"}, "level_3": {"options": [{"text": "并", "is_correct": true, "explanation": "“并没有”连用加强否定，表示事实并非如此，是正确答案。"}, {"text": "更", "is_correct": false, "explanation": "搭配：“更”表示程度加深，需要比较对象，这里没有比较，与“没有生病”搭配不当。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最”表示最高程度，与“没有生病”这一客观叙述不合。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是程度副词，不能修饰“没有”，“很没有生病”不成立。"}], "explanations": {"并": "“并没有”连用加强否定，表示事实并非如此，是正确答案。", "更": "搭配：“更”表示程度加深，需要比较对象，这里没有比较，与“没有生病”搭配不当。", "最": "语义：“最”表示最高程度，与“没有生病”这一客观叙述不合。", "很": "语法：“很”是程度副词，不能修饰“没有”，“很没有生病”不成立。"}, "sentence_index": 0, "correct_answer": "并"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我并知道这件事，你别瞒我。", "explanation": "“并”是加强否定语气的副词，只能用在“不”或“没有”前，肯定句中应说〈确实〉或〈的确〉。"}, {"text": "你并去吗？", "explanation": "“并”后面必须接“不”或“没有”等否定词，“你并去吗”缺少否定词，句子不成立；可说〈你并不想去吗？〉。"}, {"text": "我以为很难，其实并容易。", "explanation": "“并”只用在否定词前加强否定，“并容易”缺少否定词，应说〈并不难〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85710, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "并", "is_correct": true, "explanation": "“并”（bìng）是副词，用在否定词前，加强否定语气，是正确答案。"}, {"text": "兵", "is_correct": false, "explanation": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。"}, {"text": "另", "is_correct": false, "explanation": "lìng 与 bìng 声母不同（l 与 b），意思是另外。"}, {"text": "静", "is_correct": false, "explanation": "jìng 与 bìng 声母不同（j 与 b），意思是安静。"}, {"text": "鼻", "is_correct": false, "explanation": "bí 少了 ng 韵尾且声调不同，意思是鼻子。"}], "explanations": {"并": "“并”（bìng）是副词，用在否定词前，加强否定语气，是正确答案。", "兵": "bīng（第一声）与 bìng（第四声）声调不同，意思是士兵。", "另": "lìng 与 bìng 声母不同（l 与 b），意思是另外。", "静": "jìng 与 bìng 声母不同（j 与 b），意思是安静。", "鼻": "bí 少了 ng 韵尾且声调不同，意思是鼻子。"}, "sentence_index": null, "correct_answer": "并"}, "level_3": {"options": [{"text": "并", "is_correct": true, "explanation": "“并不”连用加强否定，强调不想休息的事实，是正确答案。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”多修饰突出的积极状态，与否定的“不想休息”连用不自然。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”是介词，表示被动，不能直接放在“不想休息”前面，句子不成立。"}, {"text": "愈", "is_correct": false, "explanation": "语域：“愈”是书面语，口语中不用，且“愈不想休息”与前面的转折语气不合。"}], "explanations": {"并": "“并不”连用加强否定，强调不想休息的事实，是正确答案。", "格外": "搭配：“格外”多修饰突出的积极状态，与否定的“不想休息”连用不自然。", "被": "语法：“被”是介词，表示被动，不能直接放在“不想休息”前面，句子不成立。", "愈": "语域：“愈”是书面语，口语中不用，且“愈不想休息”与前面的转折语气不合。"}, "sentence_index": 6, "correct_answer": "并"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他并很想念我。", "explanation": "“并”是加强否定语气的副词，不能修饰肯定的“很想念”，这里应说〈确实〉。"}, {"text": "你这道题并会做吗？", "explanation": "“并”后面必须接否定词，“并会做”缺少否定词，句子不成立；可说〈你并不会做吗？〉。"}, {"text": "天气很好，我们并在公园散步。", "explanation": "这里是肯定句，没有否定语境，“并”只用来加强否定语气，不能用在这里，应删去〈并〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85710, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我并听说这件事。", "corrected_sentence": "我并没有听说这件事。", "error_description": "“并”是加强否定语气的副词，后面必须接否定词，应说“并没有听说”；“我并听说”缺少否定词，句意不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85710, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个消息并意外。", "corrected_sentence": "这个消息并不意外。", "error_description": "“并”是加强否定语气的副词，必须与“不”连用，应说“并不意外”；“并意外”缺少否定词，句意不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45db2146-e6f5-4ac2-bf13-2e3f875dc61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
