INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85711, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“从”是说事情是从哪里或者什么时候开始的。", "primary_collocate": null, "pronunciation": "cóng", "ipa": "tsʰʊŋ˧˥", "syllable_count": 1, "sentences": [{"text": "我从早上八点开始工作。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从明天起，我每天早起。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从三月开始学汉语。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从上个月开始，他不抽烟了。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从北京来看我。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从窗户吹进来。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从书店出来，我去了公园。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从家里拿了一把伞。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从星期一到星期五，我都上班。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从朋友那里听说了这件事。", "target_word": "从", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "從", "label": "繁体"}, {"form": "从前", "label": "复合"}, {"form": "从来", "label": "复合"}], "register": "中性", "sense_fingerprint": "从：介词，引出事情开始的时间或地点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e58ebd77-3151-49ee-b9a9-0c05033cddf5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85711, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从”读 cóng（第二声），表示起点或来源。"}, {"text": "葱", "is_correct": false, "explanation": "cōng（第一声）与 cóng（第二声）声调不同，“葱”的意思是葱。"}, {"text": "虫", "is_correct": false, "explanation": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“虫”的意思是虫子。"}, {"text": "同", "is_correct": false, "explanation": "tóng 与 cóng 声母不同（t 与 c），声调相同，“同”的意思是相同。"}, {"text": "层", "is_correct": false, "explanation": "céng 与 cóng 韵母不同（e 与 o），声调相同，“层”的意思是层次。"}], "explanations": {"从": "正确：“从”读 cóng（第二声），表示起点或来源。", "葱": "cōng（第一声）与 cóng（第二声）声调不同，“葱”的意思是葱。", "虫": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“虫”的意思是虫子。", "同": "tóng 与 cóng 声母不同（t 与 c），声调相同，“同”的意思是相同。", "层": "céng 与 cóng 韵母不同（e 与 o），声调相同，“层”的意思是层次。"}, "sentence_index": null, "correct_answer": "从"}, "level_3": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从……开始”表示起点时间，与句意相符。"}, {"text": "到", "is_correct": false, "explanation": "语义：“到”表示终点，与“开始”所表示的起点义相反。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”引出方向或对象，不能引出动作开始的时间。"}, {"text": "对", "is_correct": false, "explanation": "配价：“对”引出对象，不能引出动作开始的时间。"}], "explanations": {"从": "正确：“从……开始”表示起点时间，与句意相符。", "到": "语义：“到”表示终点，与“开始”所表示的起点义相反。", "向": "配价：“向”引出方向或对象，不能引出动作开始的时间。", "对": "配价：“对”引出对象，不能引出动作开始的时间。"}, "sentence_index": 0, "correct_answer": "从"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们从操场玩。", "explanation": "这里应该用〈在〉。表示动作发生的场所要用“在”，“从”只表示起点或来源，不能引出动作发生的地点。"}, {"text": "这里从车站很近。", "explanation": "这里应该用〈离〉。表示距离要用“离”，“从”不表示距离。"}, {"text": "杯子从他打破了。", "explanation": "这里应该用〈被〉。表示被动要用“被”，“从”不能表示被动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85711, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从”读 cóng（第二声），表示起点或来源。"}, {"text": "铜", "is_correct": false, "explanation": "tóng 与 cóng 声母不同（t 与 c），声调相同，“铜”的意思是金属铜。"}, {"text": "曾", "is_correct": false, "explanation": "céng 与 cóng 韵母不同（e 与 o），声调相同，“曾”的意思是曾经。"}, {"text": "重", "is_correct": false, "explanation": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“重”读 chóng 时的意思是重复。"}], "explanations": {"从": "正确：“从”读 cóng（第二声），表示起点或来源。", "铜": "tóng 与 cóng 声母不同（t 与 c），声调相同，“铜”的意思是金属铜。", "曾": "céng 与 cóng 韵母不同（e 与 o），声调相同，“曾”的意思是曾经。", "重": "chóng 与 cóng 声母不同（ch 与 c），声调相同，“重”读 chóng 时的意思是重复。"}, "sentence_index": null, "correct_answer": "从"}, "level_3": {"options": [{"text": "从", "is_correct": true, "explanation": "正确：“从”表示离开的起点，与“出来”搭配。"}, {"text": "往", "is_correct": false, "explanation": "语义：“往”表示朝向，不表示离开某地。"}, {"text": "同", "is_correct": false, "explanation": "配价：“同”引出共同行动的人，不能引出离开的地点。"}, {"text": "朝", "is_correct": false, "explanation": "语义：“朝”表示朝着某个方向，与“出来”的离开义不合。"}], "explanations": {"从": "正确：“从”表示离开的起点，与“出来”搭配。", "往": "语义：“往”表示朝向，不表示离开某地。", "同": "配价：“同”引出共同行动的人，不能引出离开的地点。", "朝": "语义：“朝”表示朝着某个方向，与“出来”的离开义不合。"}, "sentence_index": 6, "correct_answer": "从"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从老师请了假。", "explanation": "这里应该用〈向〉。请假是向人提出请求，要用“向”；“从”不能引出请求的对象。"}, {"text": "他从我说了实话。", "explanation": "这里应该用〈对〉。引出说话的对象要用“对”，“从”不能这样用。"}, {"text": "我从朋友一起去。", "explanation": "这里应该用〈跟〉。表示和某人一起做事要用“跟”或“和”，“从”不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85711, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从从屋里走出来。", "corrected_sentence": "他从屋里走出来。", "error_description": "“从”重复出现了两次，“从从屋里”是重复错误。表示动作起点只用一个“从”，应说成“他从屋里走出来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85711, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从九点读向十二点。", "corrected_sentence": "我从九点读到十二点。", "error_description": "“从……到……”表示时间的起点和终点，“到”引出终点，不能用“向”代替。“向”表示方向，应说成“我从九点读到十二点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c77f923-ef68-4ed7-867a-938d8a19ded9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
