INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85714, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，表示凭借、使用某种工具、方式或根据，相当于“用”“拿”。", "primary_collocate": null, "pronunciation": "yǐ", "ipa": "i˨˩˦", "syllable_count": 1, "sentences": [{"text": "他以最快的速度跑到了终点。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师以讲故事的方式教我们汉字。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们以电话的方式联系。", "target_word": "以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家公司以质量赢得了客户。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以真诚的态度向大家道歉。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她以优秀的成绩考上了大学。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想以朋友的身份给你一个建议。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王以笑脸迎接每一位客人。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生以耐心的话安慰了病人。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们以投票的方法选出班长。", "target_word": "以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "以……的方式", "label": "常用结构"}], "register": "书面", "sense_fingerprint": "介词，引出凭借的方式、手段或依据，相当于“用”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c41e43-d819-4200-99d8-f4259434702f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
