INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85716, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "第三人称代词，指称说话双方以外的女性。", "primary_collocate": null, "pronunciation": "tā", "ipa": "tʰa˥", "syllable_count": 1, "sentences": [{"text": "王老师很好，她教我们中文。", "target_word": "她", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我给她送了一本书。", "target_word": "她", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她昨天去过上海。", "target_word": "她", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的妹妹比她高。", "target_word": "她", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玛丽说她下个月要回家。", "target_word": "她", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不知道她叫什么名字。", "target_word": "她", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈回来了，她把门关上了。", "target_word": "她", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生告诉她多喝水。", "target_word": "她", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一边走路一边听音乐。", "target_word": "她", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都很喜欢她，因为她很热情。", "target_word": "她", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "她们", "label": "复数"}], "register": "通用", "sense_fingerprint": "第三人称女性代词，作主语、宾语或定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e09e1671-b6a6-4032-8b8c-f04eced1b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85716, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "她", "is_correct": true, "explanation": "正确答案：她（tā），第三人称女性代词，指说话双方以外的女性。"}, {"text": "塔", "is_correct": false, "explanation": "tǎ（第三声）与 tā（第一声）声调不同，塔指高耸的建筑。"}, {"text": "搭", "is_correct": false, "explanation": "dā 与 tā 声母不同（d 与 t），搭指搭建或搭配。"}, {"text": "拉", "is_correct": false, "explanation": "lā 与 tā 声母不同（l 与 t），拉指用力使物体向自己移动。"}, {"text": "踏", "is_correct": false, "explanation": "tà（第四声）与 tā（第一声）声调不同，踏指脚踩上去。"}], "explanations": {"她": "正确答案：她（tā），第三人称女性代词，指说话双方以外的女性。", "塔": "tǎ（第三声）与 tā（第一声）声调不同，塔指高耸的建筑。", "搭": "dā 与 tā 声母不同（d 与 t），搭指搭建或搭配。", "拉": "lā 与 tā 声母不同（l 与 t），拉指用力使物体向自己移动。", "踏": "tà（第四声）与 tā（第一声）声调不同，踏指脚踩上去。"}, "sentence_index": null, "correct_answer": "她"}, "level_3": {"options": [{"text": "她", "is_correct": true, "explanation": "正确：“她”指老师，作“教我们中文”的主语，符合句意。"}, {"text": "它", "is_correct": false, "explanation": "语义：“它”指事物，“王老师”是人，不能用来指代。"}, {"text": "我", "is_correct": false, "explanation": "语义：“我”指说话人，此处指的是王老师，这样读会改变句子的主语。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”包含说话人，而“王老师”是另一个人，不能指代。"}], "explanations": {"她": "正确：“她”指老师，作“教我们中文”的主语，符合句意。", "它": "语义：“它”指事物，“王老师”是人，不能用来指代。", "我": "语义：“我”指说话人，此处指的是王老师，这样读会改变句子的主语。", "我们": "语义：“我们”包含说话人，而“王老师”是另一个人，不能指代。"}, "sentence_index": 0, "correct_answer": "她"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爸爸很好，她教我英语。", "explanation": "这里应该用〈他〉。“她”指女性，爸爸是男性，应说“他教我英语”。"}, {"text": "这本书很好看，她的封面很漂亮。", "explanation": "这里应该用〈它的〉。“她”只指女性，书是事物，应说“它的封面”。"}, {"text": "我很累，她想早点休息。", "explanation": "这里应该用〈我〉。“她”指说话双方以外的人，说话人自己不能用“她”指代，应说“我想早点休息”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85716, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "她", "is_correct": true, "explanation": "正确答案：她（tā），第三人称女性代词，指说话双方以外的女性。"}, {"text": "塔", "is_correct": false, "explanation": "tǎ（第三声）与 tā（第一声）声调不同，塔指高耸的建筑。"}, {"text": "趴", "is_correct": false, "explanation": "pā 与 tā 声母不同（p 与 t），趴指身体伏在某物上。"}, {"text": "哈", "is_correct": false, "explanation": "hā 与 tā 声母不同（h 与 t），哈指张口呼气的声音或笑声。"}, {"text": "踏", "is_correct": false, "explanation": "tà（第四声）与 tā（第一声）声调不同，踏指脚踩上去。"}], "explanations": {"她": "正确答案：她（tā），第三人称女性代词，指说话双方以外的女性。", "塔": "tǎ（第三声）与 tā（第一声）声调不同，塔指高耸的建筑。", "趴": "pā 与 tā 声母不同（p 与 t），趴指身体伏在某物上。", "哈": "hā 与 tā 声母不同（h 与 t），哈指张口呼气的声音或笑声。", "踏": "tà（第四声）与 tā（第一声）声调不同，踏指脚踩上去。"}, "sentence_index": null, "correct_answer": "她"}, "level_3": {"options": [{"text": "它", "is_correct": false, "explanation": "语义：“它”指事物或动物，句中指的是妈妈，是人。"}, {"text": "她", "is_correct": true, "explanation": "正确：“她”指一位女性，作“把门关上了”的主语，符合句意。"}, {"text": "它们", "is_correct": false, "explanation": "语义：“它们”指多个事物，句中指的是一个人。"}, {"text": "他", "is_correct": false, "explanation": "语义：“他”指男性，与前文的“妈妈”不符。"}], "explanations": {"它": "语义：“它”指事物或动物，句中指的是妈妈，是人。", "她": "正确：“她”指一位女性，作“把门关上了”的主语，符合句意。", "它们": "语义：“它们”指多个事物，句中指的是一个人。", "他": "语义：“他”指男性，与前文的“妈妈”不符。"}, "sentence_index": 6, "correct_answer": "她"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个苹果很甜，她很好吃。", "explanation": "这里应该用〈它〉。“她”只指女性，苹果是事物，应说“它很好吃”。"}, {"text": "他是我哥哥，她今年二十岁。", "explanation": "这里应该用〈他〉。“她”只指女性，哥哥是男性，应说“他今年二十岁”。"}, {"text": "三个学生都来了，她都很认真。", "explanation": "这里应该用〈她们〉。指多人要用复数“她们”，“她”只指一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85716, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我送她了一本书。", "corrected_sentence": "我送了她一本书。", "error_description": "“了”应紧跟动词“送”，写成“送她了”是错误的。正确应为“送了她一本书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85716, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "也她喜欢音乐。", "corrected_sentence": "她也喜欢音乐。", "error_description": "“也”是副词，应放在主语“她”后面。写成“也她”是错误的，正确应为“她也喜欢音乐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
