INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "代词，指代前面提到的人本身；也指说话人本身。", "primary_collocate": null, "pronunciation": "zì jǐ", "ipa": "tsɨ˥˩ tɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "小明告诉我，他自己也不知道。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说她要自己照顾自己。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我对自己很有信心。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他总是只想着自己。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家介绍自己。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈说，自己的事要自己做。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟生自己的气了。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把自己关在房间里。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事是我自己的错。", "target_word": "自己", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着看了看自己的手。", "target_word": "自己", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自己人", "label": "复合"}], "register": "通用", "sense_fingerprint": "反身代词，回指前面提到的人或说话人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e09e1671-b6a6-4032-8b8c-f04eced1b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "别人", "is_correct": false, "explanation": "语法：「他别人也不知道」不成句；这里需要回指“他”本人的反身代词。"}, {"text": "自己", "is_correct": true, "explanation": "反身代词，指代前句的“他”本人，意思是他也不知道。"}, {"text": "我们", "is_correct": false, "explanation": "语法：「他我们也不知道」不成句；这里需要回指“他”的「自己」。"}, {"text": "你们", "is_correct": false, "explanation": "语法：「他你们也不知道」不成句；这里需要回指“他”的「自己」。"}], "explanations": {"别人": "语法：「他别人也不知道」不成句；这里需要回指“他”本人的反身代词。", "自己": "反身代词，指代前句的“他”本人，意思是他也不知道。", "我们": "语法：「他我们也不知道」不成句；这里需要回指“他”的「自己」。", "你们": "语法：「他你们也不知道」不成句；这里需要回指“他”的「自己」。"}, "sentence_index": 0, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他总是只想着本人。", "explanation": "这里应该用〈自己〉。「本人」多作定语或状语（本人签字、本人到场），不宜作“想着”的宾语，口语中应用“自己”。"}, {"text": "他总是只想着自我。", "explanation": "这里应该用〈自己〉。「自我」偏抽象或专业用语，“想着自我”语感生硬，指具体的人想着自己时应用“自己”。"}, {"text": "他总是只想着自身。", "explanation": "这里应该用〈自己〉。「自身」偏书面，多指事物本身的属性（自身条件），不用于口语中指人作“想着”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自我", "is_correct": false, "explanation": "语域：「自我」是抽象概念，不说“生自我的气”，应说「生自己的气」。"}, {"text": "自己", "is_correct": true, "explanation": "反身代词，指弟弟自己，「生自己的气」表示对自己不满。"}, {"text": "本身", "is_correct": false, "explanation": "语法：「本身」须跟在名词后（如“事情本身”），不能单独作“生……的气”的对象。"}, {"text": "自身", "is_correct": false, "explanation": "语域：「自身」偏书面，多指事物本身，不说“生自身的气”。"}], "explanations": {"自我": "语域：「自我」是抽象概念，不说“生自我的气”，应说「生自己的气」。", "自己": "反身代词，指弟弟自己，「生自己的气」表示对自己不满。", "本身": "语法：「本身」须跟在名词后（如“事情本身”），不能单独作“生……的气”的对象。", "自身": "语域：「自身」偏书面，多指事物本身，不说“生自身的气”。"}, "sentence_index": 6, "correct_answer": "自己"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他笑着看了看自我的手。", "explanation": "这里应该用〈自己〉。「自我」指抽象的自我意识，不能修饰具体的身体部位。"}, {"text": "他笑着看了看本人的手。", "explanation": "这里应该用〈自己〉。「本人」修饰身体部位时语感生硬，看自己的身体部位应用“自己的手”。"}, {"text": "他笑着看了看手本身。", "explanation": "这里应该用〈自己〉。「本身」指事物自身，“手本身”指手这个东西，不能表示“看自己的手”中的所属关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该多为自己的着想。", "corrected_sentence": "我们应该多为自己着想。", "error_description": "错误：「为……着想」中「着想」是动词，「自己」后面不能加「的」。正确：应为「为自己着想」，去掉「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把自己书放回了书架上。", "corrected_sentence": "他把自己的书放回了书架上。", "error_description": "错误：「自己」修饰名词「书」时漏掉「的」。正确：应为「自己的书」，「自己」与「的」连用后修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "正确：“给”是交出去，“收”是接受过来，二者为反义。"}, {"text": "唱", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}, {"text": "想", "is_correct": false, "explanation": "与“给”的任何义项都不构成反义关系。"}], "correct_answer": "收", "explanations": {"收": "正确：“给”是交出去，“收”是接受过来，二者为反义。", "唱": "与“给”的任何义项都不构成反义关系。", "跑": "与“给”的任何义项都不构成反义关系。", "想": "与“给”的任何义项都不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
