INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“给”是把东西交到别人手里，让别人有。", "primary_collocate": null, "pronunciation": "gěi", "ipa": "kei˨˩˦", "syllable_count": 1, "sentences": [{"text": "他给我一本书。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请给我一杯水。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈给了我一个苹果。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给我们很多作业。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钥匙在这儿，给你。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸每个月给我五百块钱。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你给我一张纸，我写个名字。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给过我一件很漂亮的礼物。", "target_word": "给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给了他一瓶药，让他按时吃。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天朋友给了我两张电影票。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "给了", "label": "体标"}, {"form": "给过", "label": "体标"}, {"form": "給", "label": "繁体"}], "register": "口语", "sense_fingerprint": "动词给：把东西交到别人手里，让对方得到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "给", "is_correct": true, "explanation": "正确答案：给（gěi），动词，把东西交到别人手里。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 gěi 声母不同（b 对 g），意思是北方。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 gěi 声母不同（m 对 g），意思是美丽。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gěi 韵母不同（ai 对 ei），意思是改变。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 gěi 韵母不同（多出 u 介音，ui 对 ei），意思是鬼。"}], "explanations": {"给": "正确答案：给（gěi），动词，把东西交到别人手里。", "北": "běi（第三声）与 gěi 声母不同（b 对 g），意思是北方。", "美": "měi（第三声）与 gěi 声母不同（m 对 g），意思是美丽。", "改": "gǎi（第三声）与 gěi 韵母不同（ai 对 ei），意思是改变。", "鬼": "guǐ（第三声）与 gěi 韵母不同（多出 u 介音，ui 对 ei），意思是鬼。"}, "sentence_index": null, "correct_answer": "给"}, "level_3": {"options": [{"text": "给", "is_correct": true, "explanation": "正确：动词“给”表示把东西交给“我”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能接“一本书”。"}, {"text": "笑", "is_correct": false, "explanation": "配价：“笑”是不及物动词，不能带“我”和“一本书”两个宾语。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣服，不能接“书”。"}], "explanations": {"给": "正确：动词“给”表示把东西交给“我”。", "吃": "搭配：“吃”的宾语是食物，不能接“一本书”。", "笑": "配价：“笑”是不及物动词，不能带“我”和“一本书”两个宾语。", "穿": "搭配：“穿”的宾语是衣服，不能接“书”。"}, "sentence_index": 0, "correct_answer": "给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师给我们英语。", "explanation": "这里应该用〈教〉。“教”指传授知识，“给”表示交付实物，不能把“英语”当作可以交付的东西。"}, {"text": "我给你吃饭了。", "explanation": "这里应该用〈请〉。“请你吃饭”表示邀请，“给”表示交付或为了某人，不能表示邀请。"}, {"text": "我给你回家了。", "explanation": "这里应该用〈送〉。“送你回家”表示陪同送行，“给”表示交付，不能表示送行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "给", "is_correct": true, "explanation": "正确：动词“给”表示把纸交给“我”。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮品，不能接“一张纸”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带宾语。"}, {"text": "闻", "is_correct": false, "explanation": "搭配：“闻”的宾语是气味，不能接“纸”。"}], "explanations": {"给": "正确：动词“给”表示把纸交给“我”。", "喝": "搭配：“喝”的宾语是饮品，不能接“一张纸”。", "哭": "配价：“哭”是不及物动词，不能带宾语。", "闻": "搭配：“闻”的宾语是气味，不能接“纸”。"}, "sentence_index": 6, "correct_answer": "给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我起床了。", "explanation": "这里应该用〈叫〉。“叫某人做某事”表示使令，“给”表示交付，不能用于使令。"}, {"text": "他给老人过马路。", "explanation": "这里应该用〈扶〉。搀扶别人做某事用“扶”，“给”不能表示搀扶。"}, {"text": "老师给我们跑步了。", "explanation": "这里应该用〈带〉。“带某人做某事”表示领着别人一起做，“给”表示交付，不能表示带领。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐给我了一支笔。", "corrected_sentence": "姐姐给了我一支笔。", "error_description": "错误：动态助词“了”放在了宾语“我”之后，“给我了”不成立。正确：“了”紧跟动词，写作“给了我”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给我过一张地图。", "corrected_sentence": "他给过我一张地图。", "error_description": "错误：体标“过”放在了宾语“我”之后，“给我过”不成立。正确：“过”紧跟动词，写作“给过我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
