INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85724, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，引出动作的受益者或对象，表示为了某人或对某人。", "primary_collocate": null, "pronunciation": "gěi", "ipa": "kei˨˩˦", "syllable_count": 1, "sentences": [{"text": "我每天晚上给妈妈打电话。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给我讲了一个故事。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员给我们拿来了菜单。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给孩子做了早饭。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你给我们拍一张照片。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小王给客人倒了一杯茶。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想给朋友写一封信。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天早上给花浇水。", "target_word": "给", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "医生正在给病人检查身体，他很认真。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们给老师送了一束花。", "target_word": "给", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "給", "label": "繁体"}], "register": "口语", "sense_fingerprint": "介词给：引出动作的受益者或对象，为某人做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85724, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "给", "is_correct": true, "explanation": "正确答案：给（gěi），介词，表示为了某人或对某人。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 gěi 声母不同（b 对 g），意思是北方。"}, {"text": "美", "is_correct": false, "explanation": "měi（第三声）与 gěi 声母不同（m 对 g），意思是美丽。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gěi 韵母不同（ai 对 ei），意思是改变。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 gěi 韵母不同（多出 u 介音，ui 对 ei），意思是鬼。"}], "explanations": {"给": "正确答案：给（gěi），介词，表示为了某人或对某人。", "北": "běi（第三声）与 gěi 声母不同（b 对 g），意思是北方。", "美": "měi（第三声）与 gěi 声母不同（m 对 g），意思是美丽。", "改": "gǎi（第三声）与 gěi 韵母不同（ai 对 ei），意思是改变。", "鬼": "guǐ（第三声）与 gěi 韵母不同（多出 u 介音，ui 对 ei），意思是鬼。"}, "sentence_index": null, "correct_answer": "给"}, "level_3": {"options": [{"text": "给", "is_correct": true, "explanation": "正确：“给妈妈打电话”中，介词“给”引出接电话的对象。"}, {"text": "把", "is_correct": false, "explanation": "配价：“打电话”不能用“把”引出对象，“把妈妈打电话”不成立。"}, {"text": "在", "is_correct": false, "explanation": "语法：“在”引出处所，“在妈妈打电话”不成立，不能用“在”引出通话的对象。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，“从妈妈打电话”不表示打电话的对象。"}], "explanations": {"给": "正确：“给妈妈打电话”中，介词“给”引出接电话的对象。", "把": "配价：“打电话”不能用“把”引出对象，“把妈妈打电话”不成立。", "在": "语法：“在”引出处所，“在妈妈打电话”不成立，不能用“在”引出通话的对象。", "从": "语义：“从”表示起点，“从妈妈打电话”不表示打电话的对象。"}, "sentence_index": 0, "correct_answer": "给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我给朋友吃饭了。", "explanation": "这里应该用〈请〉。“请朋友吃饭”表示邀请，“给”表示为了某人，不能表示邀请。"}, {"text": "我给朋友一起去旅行。", "explanation": "这里应该用〈跟〉。“跟……一起”表示与某人共同做事，“给”表示为了某人，不能表示共同。"}, {"text": "我给朋友回家了。", "explanation": "这里应该用〈送〉。“送朋友回家”表示陪同送行，“给”表示为了某人，不能表示送行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "给", "is_correct": true, "explanation": "正确：“写信给某人”中，“给”引出收信人。"}, {"text": "在", "is_correct": false, "explanation": "语义：“在”表示处所，“在朋友写一封信”不通，收信人不能用“在”引出。"}, {"text": "按", "is_correct": false, "explanation": "语义：“按”表示依据，“按朋友写一封信”不通。"}, {"text": "被", "is_correct": false, "explanation": "配价：“被”后面要引出施事，而“写信”的施事是“我”，“被朋友写一封信”意思颠倒。"}], "explanations": {"给": "正确：“写信给某人”中，“给”引出收信人。", "在": "语义：“在”表示处所，“在朋友写一封信”不通，收信人不能用“在”引出。", "按": "语义：“按”表示依据，“按朋友写一封信”不通。", "被": "配价：“被”后面要引出施事，而“写信”的施事是“我”，“被朋友写一封信”意思颠倒。"}, "sentence_index": 6, "correct_answer": "给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们给老师请教问题。", "explanation": "这里应该用〈向〉。“向……请教”引出求教的对象，“给”不能用于请教的对象。"}, {"text": "孩子们给老师聊天。", "explanation": "这里应该用〈和〉。“和……聊天”表示与某人交谈，“给”不表示共同交谈。"}, {"text": "孩子们给书上学到了很多知识。", "explanation": "这里应该用〈从〉。“从……学到”表示知识的来源，“给”不能引出来源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上给了爸爸发短信。", "corrected_sentence": "我每天晚上给爸爸发短信。", "error_description": "错误：介词“给”后面加了“了”，“给了爸爸”不能作为介词短语使用。正确：“给爸爸发短信”，“了”不能附在介词“给”上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天晚上给了女儿讲故事。", "corrected_sentence": "他每天晚上给女儿讲故事。", "error_description": "错误：介词“给”后面加了“了”，“给了女儿讲故事”不成立。正确：“给女儿讲故事”，“了”不能附在介词“给”上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
