INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85725, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "“把”是说拿起一个东西，对它做一件事。", "primary_collocate": null, "pronunciation": "bǎ", "ipa": "pa˨˩˦", "syllable_count": 1, "sentences": [{"text": "请把书放在桌子上。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把杯子拿起来。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我把行李箱拿起来，放进了车里。", "target_word": "把", "complexity_tier": "T3", "furigana": "wǒ bǎ xíng lǐ xiāng ná qǐ lái, fàng jìn le chē lǐ.", "sentence_source": "generated"}, {"text": "妈妈把菜放进冰箱里。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小明把球捡起来，扔到了房子后面。", "target_word": "把", "complexity_tier": "T3", "furigana": "xiǎo míng bǎ qiú jiǎn qǐ lái, rēng dào le fáng zi hòu miàn.", "sentence_source": "generated"}, {"text": "请把地上的鞋拿起来，放进柜子里。", "target_word": "把", "complexity_tier": "T3", "furigana": "qǐng bǎ dì shàng de xié ná qǐ lái, fàng jìn guì zi lǐ.", "sentence_source": "generated"}, {"text": "她把衣服挂在椅子上。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把手机放进包里。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "服务员把汤端到桌子上。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我把伞放在门口，别忘了拿。", "target_word": "把", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "介词把：拿起具体物品，对它做放、拿、关等动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 2 above tier T1: 3 words above tier T1 (max 2): 行李箱 (Zipf 3.49), 放进 (Zipf 3.8), 车里 (Zipf 3.84)']::text[], 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85725, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "把", "is_correct": true, "explanation": "正确答案：把（bǎ），介词，表示拿起物品后对它做动作。"}, {"text": "打", "is_correct": false, "explanation": "dǎ（第三声）与 bǎ 声母不同（d 对 b），意思是打。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 bǎ 声母不同（m 对 b），意思是马。"}, {"text": "哪", "is_correct": false, "explanation": "nǎ（第三声）与 bǎ 声母不同（n 对 b），意思是哪。"}], "explanations": {"把": "正确答案：把（bǎ），介词，表示拿起物品后对它做动作。", "打": "dǎ（第三声）与 bǎ 声母不同（d 对 b），意思是打。", "马": "mǎ（第三声）与 bǎ 声母不同（m 对 b），意思是马。", "哪": "nǎ（第三声）与 bǎ 声母不同（n 对 b），意思是哪。"}, "sentence_index": null, "correct_answer": "把"}, "level_3": {"options": [{"text": "把", "is_correct": true, "explanation": "正确：“把”引出被移动的“书”，构成“把书放在……”。"}, {"text": "用", "is_correct": false, "explanation": "语义：“用”引出工具，“用书放在桌子上”不通。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“放”的对象不用“向”引出，“向书放”不通。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，“从书放在桌子上”不通。"}], "explanations": {"把": "正确：“把”引出被移动的“书”，构成“把书放在……”。", "用": "语义：“用”引出工具，“用书放在桌子上”不通。", "向": "搭配：“放”的对象不用“向”引出，“向书放”不通。", "从": "语义：“从”表示起点，“从书放在桌子上”不通。"}, "sentence_index": 0, "correct_answer": "把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把他很喜欢。", "explanation": "这里不能用〈把〉。“喜欢”是心理动词，不能用“把”提宾语，应说“我很喜欢他”。"}, {"text": "他把北京是首都。", "explanation": "这里不能用〈把〉。“是”表示判断，不能用“把”提宾语，应说“北京是首都”。"}, {"text": "她把很高兴。", "explanation": "这里不能用〈把〉。“高兴”是形容词，不能用“把”提宾语，应说“她很高兴”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85725, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "把", "is_correct": true, "explanation": "正确答案：把（bǎ），介词，表示拿起物品后对它做动作。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）与 bǎ 声调不同，意思是爸爸。"}, {"text": "八", "is_correct": false, "explanation": "bā（第一声）与 bǎ 声调不同，意思是八。"}, {"text": "拔", "is_correct": false, "explanation": "bá（第二声）与 bǎ 声调不同，意思是拔出。"}], "explanations": {"把": "正确答案：把（bǎ），介词，表示拿起物品后对它做动作。", "爸": "bà（第四声）与 bǎ 声调不同，意思是爸爸。", "八": "bā（第一声）与 bǎ 声调不同，意思是八。", "拔": "bá（第二声）与 bǎ 声调不同，意思是拔出。"}, "sentence_index": null, "correct_answer": "把"}, "level_3": {"options": [{"text": "把", "is_correct": true, "explanation": "正确：“把”引出被挂的“衣服”，构成“把衣服挂在……”。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“挂”的处置对象要用“把”引出，“对衣服挂”不通。"}, {"text": "被", "is_correct": false, "explanation": "语义：“被”表示被动，“她被衣服挂在椅子上”意思颠倒。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“挂”的处置对象不用“向”引出，“向衣服挂”不通。"}], "explanations": {"把": "正确：“把”引出被挂的“衣服”，构成“把衣服挂在……”。", "对": "搭配：“挂”的处置对象要用“把”引出，“对衣服挂”不通。", "被": "语义：“被”表示被动，“她被衣服挂在椅子上”意思颠倒。", "向": "搭配：“挂”的处置对象不用“向”引出，“向衣服挂”不通。"}, "sentence_index": 6, "correct_answer": "把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把伞很重。", "explanation": "这里不能用〈把〉。“重”是形容词，不能用“把”引出宾语，应说“伞很重”。"}, {"text": "我把妈妈害怕了。", "explanation": "这里不能用〈把〉。“害怕”是心理动词，不能用“把”提宾语，应说“我怕妈妈”。"}, {"text": "他把这件事明白了。", "explanation": "这里不能用〈把〉。“明白”表示状态，不能用“把”处置，应说“他明白这件事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85725, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把箱子搬房间。", "corrected_sentence": "她把箱子搬进房间。", "error_description": "错误：把字句中的动词“搬”后缺少方向补语，“搬房间”不成立。正确：“搬进房间”，动词后要带方向补语“进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85725, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把杯子端。", "corrected_sentence": "他把杯子端起来。", "error_description": "错误：把字句的动词“端”后面什么都没有，“把杯子端”不完整。正确：动词后要带补语，写作“把杯子端起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
