INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85726, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "介词，用来把宾语提到动词前面，表示对某物进行处置。", "primary_collocate": null, "pronunciation": "bǎ", "ipa": "pa˨˩˦", "syllable_count": 1, "sentences": [{"text": "请把作业做完。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我已经把问题解决了。", "target_word": "把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这件事告诉了老师。", "target_word": "把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把声音放小一点。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把名字写错了。", "target_word": "把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把工作做好。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师把课文讲得很清楚。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把你的想法说出来。", "target_word": "把", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈把房间打扫得干干净净。", "target_word": "把", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有把话说完，就走了。", "target_word": "把", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "介词把：把事情或宾语提前，表示对其处置并带出结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa09a39c-1dc4-4f09-8ce9-0310badb768d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85726, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "把", "is_correct": true, "explanation": "正确答案：把（bǎ），介词，用来把宾语提到动词前面。"}, {"text": "爸", "is_correct": false, "explanation": "bà（第四声）与 bǎ 声调不同，意思是爸爸。"}, {"text": "八", "is_correct": false, "explanation": "bā（第一声）与 bǎ 声调不同，意思是八。"}, {"text": "拔", "is_correct": false, "explanation": "bá（第二声）与 bǎ 声调不同，意思是拔出。"}], "explanations": {"把": "正确答案：把（bǎ），介词，用来把宾语提到动词前面。", "爸": "bà（第四声）与 bǎ 声调不同，意思是爸爸。", "八": "bā（第一声）与 bǎ 声调不同，意思是八。", "拔": "bá（第二声）与 bǎ 声调不同，意思是拔出。"}, "sentence_index": null, "correct_answer": "把"}, "level_3": {"options": [{"text": "把", "is_correct": true, "explanation": "正确：“把”引出被处置的“作业”，构成“把……做完”。"}, {"text": "对", "is_correct": false, "explanation": "搭配：“对……做完”不成立，表示处置要用“把”引出宾语。"}, {"text": "被", "is_correct": false, "explanation": "语义：“被”表示被动，“请被作业做完”意思颠倒，不符合请求。"}, {"text": "从", "is_correct": false, "explanation": "语义：“从”表示起点，“请从作业做完”不通。"}], "explanations": {"把": "正确：“把”引出被处置的“作业”，构成“把……做完”。", "对": "搭配：“对……做完”不成立，表示处置要用“把”引出宾语。", "被": "语义：“被”表示被动，“请被作业做完”意思颠倒，不符合请求。", "从": "语义：“从”表示起点，“请从作业做完”不通。"}, "sentence_index": 0, "correct_answer": "把"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把饭很好吃。", "explanation": "这里不能用〈把〉。“好吃”是形容词谓语，不能用“把”提宾语，应说“饭很好吃”。"}, {"text": "他把说明书组装了椅子。", "explanation": "这里应该用〈按照〉。“按照说明书”表示依据，“把”表示处置，不能引出依据。"}, {"text": "我把你签了名。", "explanation": "这里应该用〈替〉。“替你签名”表示代理，“把”表示处置，不能用“把你”表示替你做事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85726, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "把", "is_correct": true, "explanation": "正确答案：把（bǎ），介词，用来把宾语提到动词前面。"}, {"text": "打", "is_correct": false, "explanation": "dǎ（第三声）与 bǎ 声母不同（d 对 b），意思是打。"}, {"text": "马", "is_correct": false, "explanation": "mǎ（第三声）与 bǎ 声母不同（m 对 b），意思是马。"}, {"text": "哪", "is_correct": false, "explanation": "nǎ（第三声）与 bǎ 声母不同（n 对 b），意思是哪。"}], "explanations": {"把": "正确答案：把（bǎ），介词，用来把宾语提到动词前面。", "打": "dǎ（第三声）与 bǎ 声母不同（d 对 b），意思是打。", "马": "mǎ（第三声）与 bǎ 声母不同（m 对 b），意思是马。", "哪": "nǎ（第三声）与 bǎ 声母不同（n 对 b），意思是哪。"}, "sentence_index": null, "correct_answer": "把"}, "level_3": {"options": [{"text": "把", "is_correct": true, "explanation": "正确：“把”引出被处置的“课文”，构成“把……讲得很清楚”。"}, {"text": "向", "is_correct": false, "explanation": "搭配：“讲”的对象是学生，“向课文讲”不说。"}, {"text": "在", "is_correct": false, "explanation": "语法：“在”引出处所或时间，“在课文讲得很清楚”不通。"}, {"text": "替", "is_correct": false, "explanation": "语义：“替”表示代替某人，“替课文讲”不通。"}], "explanations": {"把": "正确：“把”引出被处置的“课文”，构成“把……讲得很清楚”。", "向": "搭配：“讲”的对象是学生，“向课文讲”不说。", "在": "语法：“在”引出处所或时间，“在课文讲得很清楚”不通。", "替": "语义：“替”表示代替某人，“替课文讲”不通。"}, "sentence_index": 6, "correct_answer": "把"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把老师请教了问题。", "explanation": "这里应该用〈向〉。“向老师请教”表示求教的对象，“把”不能引出求教的对象。"}, {"text": "我把图书馆借了一本书。", "explanation": "这里应该用〈从〉。“从图书馆借”表示来源，“把”不能引出借书的来源。"}, {"text": "我把朋友玩了一下午。", "explanation": "这里应该用〈跟〉。“跟朋友玩”表示与某人共同做事，“把”表示处置，不能引出共同做事的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把门关。", "corrected_sentence": "请把门关上。", "error_description": "错误：把字句中的动词“关”后缺少补语，“把门关”不完整。正确：“把门关上”，动词后要带结果补语“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3fae165c-4e90-45b4-af7b-6681f22484a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
