INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85727, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“或”是说在两样东西里选一样。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xwɔ˥˩", "syllable_count": 1, "sentences": [{"text": "我想喝茶或水。", "target_word": "或", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天或后天我有空。", "target_word": "或", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你可以坐车或走路去学校。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周六或周日我们去公园。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买一本或两本书都可以。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他会在三点或四点到。", "target_word": "或", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请用红笔或黑笔写名字。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想吃米饭或面条。", "target_word": "或", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你可以打电话或发短信给我。", "target_word": "或", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去北京或上海都很好玩。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "或者", "label": "复合"}], "register": "通用", "sense_fingerprint": "连接并列的选项，表示二者选其一", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e09e1671-b6a6-4032-8b8c-f04eced1b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "或", "is_correct": true, "explanation": "目标词，读 huò（第四声），表示二者选一。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是“火”。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是“活着、活动”。"}, {"text": "豁", "is_correct": false, "explanation": "huō（第一声）与 huò（第四声）声调不同，意思是“裂开、豁口”。"}], "explanations": {"或": "目标词，读 huò（第四声），表示二者选一。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是“火”。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是“活着、活动”。", "豁": "huō（第一声）与 huò（第四声）声调不同，意思是“裂开、豁口”。"}, "sentence_index": null, "correct_answer": "或"}, "level_3": {"options": [{"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进或并列，不表示二者选一。"}, {"text": "或", "is_correct": true, "explanation": "连词，表示选择，“茶或水”是二选一。"}, {"text": "但是", "is_correct": false, "explanation": "搭配：「但是」要求前后转折，“想喝茶”与“水”之间没有转折关系。"}, {"text": "所以", "is_correct": false, "explanation": "语义：「所以」表示因果，句中没有因果关系。"}], "explanations": {"而且": "语义：「而且」表示递进或并列，不表示二者选一。", "或": "连词，表示选择，“茶或水”是二选一。", "但是": "搭配：「但是」要求前后转折，“想喝茶”与“水”之间没有转折关系。", "所以": "语义：「所以」表示因果，句中没有因果关系。"}, "sentence_index": 0, "correct_answer": "或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他或她都想参加，结果两个人都报名了。", "explanation": "这里应该用〈和〉。“或”表示二选一，而句中两个人都报名了，应用「和」。"}, {"text": "我昨天去了北京或上海，两个城市都玩了。", "explanation": "「或」表示二选一，两个地方都去了就不能用「或」，应该用「和」。"}, {"text": "我今天买了笔或本子，两样都买了。", "explanation": "这里应该用〈和〉。「或」表示二选一，两样都买了要用「和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85727, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "因而", "is_correct": false, "explanation": "语义：「因而」表示结果，这里说的是二选一，不是因果关系。"}, {"text": "或", "is_correct": true, "explanation": "连词，表示选择，“红笔或黑笔”是二选一。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：「然而」要求前后转折，“用红笔”和“用黑笔”之间没有转折。"}, {"text": "而是", "is_correct": false, "explanation": "搭配：「而是」需与前面的否定词「不是」搭配，这里没有否定。"}], "explanations": {"因而": "语义：「因而」表示结果，这里说的是二选一，不是因果关系。", "或": "连词，表示选择，“红笔或黑笔”是二选一。", "然而": "搭配：「然而」要求前后转折，“用红笔”和“用黑笔”之间没有转折。", "而是": "搭配：「而是」需与前面的否定词「不是」搭配，这里没有否定。"}, "sentence_index": 6, "correct_answer": "或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想喝茶或咖啡，两样都想喝。", "explanation": "这里应该用〈和〉。「或」表示二选一，说两样都想喝要用「和」。"}, {"text": "他今天去北京或上海，两个城市都去了。", "explanation": "这里应该用〈和〉。「或」表示二选一，两个城市都去了要用「和」。"}, {"text": "我想吃饭或睡觉，结果两样都做了。", "explanation": "这里应该用〈和〉。「或」表示二选一，两样都做了要用「和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周六或和周日都可以，你选一天吧。", "corrected_sentence": "周六或周日都可以，你选一天吧。", "error_description": "错误：「或」与「和」连用，「或」已表示二选一，不能再加「和」。正确：应为「周六或周日都可以」，去掉「和」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我们去公园或或爬山。", "corrected_sentence": "周末我们去公园或爬山。", "error_description": "错误：「或」重复出现，只需用一个。正确：应为「去公园或爬山」，删去多余的「或」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
