INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示选择关系，相当于“或者”。", "primary_collocate": null, "pronunciation": "huò", "ipa": "xwo˥˩", "syllable_count": 1, "sentences": [{"text": "你可以坐地铁或坐公交车去。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我想去看电影或爬山。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请用笔或电脑写下你的名字。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早饭我常吃面包或鸡蛋。", "target_word": "或", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天或后天，我给你打电话。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有问题的话，请发邮件或打电话。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个星期里，他会去两次或三次健身房。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想喝茶或咖啡的人，请在这里排队。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以现在来，或明天早上来都行。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管是白天或晚上，这里都很安静。", "target_word": "或", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "或者", "label": "复合"}], "register": "通用", "sense_fingerprint": "或|连词|表示选择关系，相当于或者", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e09e1671-b6a6-4032-8b8c-f04eced1b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "或", "is_correct": true, "explanation": "目标词，读 huò（第四声），表示选择关系。"}, {"text": "火", "is_correct": false, "explanation": "huǒ（第三声）与 huò（第四声）声调不同，意思是“火”。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huò（第四声）声调不同，意思是“活着、活动”。"}, {"text": "豁", "is_correct": false, "explanation": "huō（第一声）与 huò（第四声）声调不同，意思是“裂开、豁口”。"}], "explanations": {"或": "目标词，读 huò（第四声），表示选择关系。", "火": "huǒ（第三声）与 huò（第四声）声调不同，意思是“火”。", "活": "huó（第二声）与 huò（第四声）声调不同，意思是“活着、活动”。", "豁": "huō（第一声）与 huò（第四声）声调不同，意思是“裂开、豁口”。"}, "sentence_index": null, "correct_answer": "或"}, "level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "搭配：「而是」需与前面的否定词「不是」搭配，这里没有否定。"}, {"text": "或", "is_correct": true, "explanation": "连词，表示选择，“坐地铁或坐公交车”是二选一。"}, {"text": "但是", "is_correct": false, "explanation": "语义：「但是」表示转折，句中两种交通方式之间没有转折。"}, {"text": "因此", "is_correct": false, "explanation": "语义：「因此」表示因果，句中没有因果关系。"}], "explanations": {"而是": "搭配：「而是」需与前面的否定词「不是」搭配，这里没有否定。", "或": "连词，表示选择，“坐地铁或坐公交车”是二选一。", "但是": "语义：「但是」表示转折，句中两种交通方式之间没有转折。", "因此": "语义：「因此」表示因果，句中没有因果关系。"}, "sentence_index": 0, "correct_answer": "或"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "早饭我常吃面包或鸡蛋，两样都吃。", "explanation": "「或」表示二选一，说两样都吃就与它的选择意义矛盾，应该用「和」。"}, {"text": "我今天买了笔或本子，两样都买了。", "explanation": "「或」表示二选一，两样都买了应该用「和」，不能用「或」。"}, {"text": "我昨天吃了米饭或面条，两样都吃了。", "explanation": "这里应该用〈和〉。「或」表示二选一，两样都吃了要用「和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而且", "is_correct": false, "explanation": "语义：「而且」表示递进或并列，这里需要的是选择关系。"}, {"text": "或", "is_correct": true, "explanation": "连词，表示选择，“两次或三次”表示次数在两者之间二选一。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：「然而」要求前后转折，“两次”和“三次”之间没有转折。"}, {"text": "从而", "is_correct": false, "explanation": "语义：「从而」连接原因和结果，“两次”与“三次”之间是选择关系，不是因果。"}], "explanations": {"而且": "语义：「而且」表示递进或并列，这里需要的是选择关系。", "或": "连词，表示选择，“两次或三次”表示次数在两者之间二选一。", "然而": "搭配：「然而」要求前后转折，“两次”和“三次”之间没有转折。", "从而": "语义：「从而」连接原因和结果，“两次”与“三次”之间是选择关系，不是因果。"}, "sentence_index": 6, "correct_answer": "或"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我白天或晚上都去那里，每次两个时间都去。", "explanation": "「或」表示二选一，两个时间都去应该用「和」。"}, {"text": "我问了老师或同学，两个人都回答了。", "explanation": "这里应该用〈和〉。“或”表示二选一，而句中两个人都回答了，应用「和」。"}, {"text": "我周末或周一都去过，两天都去过。", "explanation": "这里应该用〈和〉。「或」表示二选一，说两天都去过要用「和」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末你可以去公园或和爬山。", "corrected_sentence": "周末你可以去公园或爬山。", "error_description": "错误：「或」已表示二选一，后面不能再加「和」。正确：应为「去公园或爬山」，去掉「和」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85728, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周一或周二或，你都可以来。", "corrected_sentence": "周一或周二，你都可以来。", "error_description": "错误：句末多了一个「或」。「或」是连词，需连接两个成分，不能悬空。正确：应为「周一或周二，你都可以来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
