INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "“因为”是用来说事情为什么会这样的。", "primary_collocate": null, "pronunciation": "yīn wèi", "ipa": "in˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "我没去，因为我生病了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么哭？因为我的手机丢了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑了，因为大家都夸他。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太贵，我没有买。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这座城市，因为这里的人很热情。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天没来上课，因为家里有事。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雪，飞机晚点了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很高兴，因为考试得了第一名。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不去了，因为时间太晚。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，因为他想妈妈了。", "target_word": "因为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "因为：回答“为什么”，单独引出原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5414130c-939f-47d2-a1d8-a425c962efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，而“我生病了”是原因，这样说因果颠倒。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，放在“我生病了”前，与原句的因果方向相反。"}, {"text": "如果", "is_correct": false, "explanation": "搭配：“如果”要与“就”呼应，且句子说的是已经发生的事，不能用假设。"}, {"text": "因为", "is_correct": true, "explanation": "“因为”引出原因，与“我没去”构成因果，解释没去的理由。"}], "explanations": {"所以": "语义：“所以”引出结果，而“我生病了”是原因，这样说因果颠倒。", "因此": "语义：“因此”引出结果，放在“我生病了”前，与原句的因果方向相反。", "如果": "搭配：“如果”要与“就”呼应，且句子说的是已经发生的事，不能用假设。", "因为": "“因为”引出原因，与“我没去”构成因果，解释没去的理由。"}, "sentence_index": 0, "correct_answer": "因为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "因为天冷，但是他没穿外套。", "explanation": "这里应该用〈虽然〉。“但是”表示转折，要与让步的“虽然”呼应；“因为”引出原因，两者不能这样配合。"}, {"text": "他没有努力，因为没有通过考试。", "explanation": "这里应该用〈因此〉。“没有努力”是原因，“没有通过考试”是结果，结果应说“因此没有通过考试”。"}, {"text": "因为下雨，我们还是去了公园。", "explanation": "这里应该用〈虽然〉。“还是”要与让步的“虽然”呼应，用“因为”会使前后句意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "而是", "is_correct": false, "explanation": "搭配：“而是”要与前面的否定呼应，句中没有否定词，不能这样用。"}, {"text": "因而", "is_correct": false, "explanation": "语义：“因而”表示结果，不能用来引出“下雪”这一原因。"}, {"text": "以致", "is_correct": false, "explanation": "语义：“以致”表示结果，与“下雪”和“飞机晚点”的因果方向相反。"}, {"text": "因为", "is_correct": true, "explanation": "“因为”引出“下雪”这一原因，说明飞机晚点的理由。"}], "explanations": {"而是": "搭配：“而是”要与前面的否定呼应，句中没有否定词，不能这样用。", "因而": "语义：“因而”表示结果，不能用来引出“下雪”这一原因。", "以致": "语义：“以致”表示结果，与“下雪”和“飞机晚点”的因果方向相反。", "因为": "“因为”引出“下雪”这一原因，说明飞机晚点的理由。"}, "sentence_index": 6, "correct_answer": "因为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "因为努力，才能成功。", "explanation": "这里应该用〈只有〉。“只有……才……”表示唯一条件；“因为”只能引出已经发生的原因，不能接条件。"}, {"text": "他很高，因为很瘦。", "explanation": "这里应该用〈而且〉。“而且”把两个特点并列起来；“因为”要求后半句是前半句的原因，“很瘦”解释不了“很高”。"}, {"text": "她很聪明，因为成绩不好。", "explanation": "这里应该用〈然而〉。“然而”表示转折，前后意思相反；“因为”表示原因，这里不能说成因果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你怎么不吃饭？因为我因为不饿。", "corrected_sentence": "你怎么不吃饭？因为我不饿。", "error_description": "连词重复：“因为”只用一次，“我因为不饿”里又加了一个“因为”，应只说“因为我不饿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85729, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没去，因为因为她生病了。", "corrected_sentence": "她没去，因为她生病了。", "error_description": "连词重复：“因为”只用一次，句中多出一个“因为”，应说“她没去，因为她生病了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
