INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85731, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "“下”是说在低一点的地方，或者在东西的底下。", "primary_collocate": null, "pronunciation": "xià", "ipa": "ɕja˥˩", "syllable_count": 1, "sentences": [{"text": "小猫睡在桌子下。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐在大树下看书。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的鞋在床下。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山下有一条小河。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在雨伞下说话。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把箱子放在桌子下。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在桥下休息。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗藏在椅子下，不出来。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在山下的小房子里。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯下坐着一个老人。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下面", "label": "复合"}, {"form": "楼下", "label": "复合"}], "register": "中性", "sense_fingerprint": "方位词：在某物的下面、较低的位置（树下、桌子下）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85731, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下", "is_correct": true, "explanation": "下（xià）指较低的位置，是本题的目标词。"}, {"text": "虾", "is_correct": false, "explanation": "xiā（第一声）与 xià（第四声）声调不同，意思是虾。"}, {"text": "霞", "is_correct": false, "explanation": "xiá（第二声）与 xià（第四声）声调不同，意思是云霞。"}, {"text": "价", "is_correct": false, "explanation": "jià 与 xià 声母不同（j/x），意思是价格。"}], "explanations": {"下": "下（xià）指较低的位置，是本题的目标词。", "虾": "xiā（第一声）与 xià（第四声）声调不同，意思是虾。", "霞": "xiá（第二声）与 xià（第四声）声调不同，意思是云霞。", "价": "jià 与 xià 声母不同（j/x），意思是价格。"}, "sentence_index": null, "correct_answer": "下"}, "level_3": {"options": [{"text": "下", "is_correct": true, "explanation": "“下”表示桌子的底下，与小猫睡觉的情境相符。"}, {"text": "右", "is_correct": false, "explanation": "搭配：“右”作方位词要说“右边”，不能说“桌子右”单用。"}, {"text": "内", "is_correct": false, "explanation": "搭配：“内”单用时不能说“桌子内”，须说“桌子内部”。"}, {"text": "左", "is_correct": false, "explanation": "搭配：“左”作方位词要说“左边”，不能说“桌子左”。"}], "explanations": {"下": "“下”表示桌子的底下，与小猫睡觉的情境相符。", "右": "搭配：“右”作方位词要说“右边”，不能说“桌子右”单用。", "内": "搭配：“内”单用时不能说“桌子内”，须说“桌子内部”。", "左": "搭配：“左”作方位词要说“左边”，不能说“桌子左”。"}, "sentence_index": 0, "correct_answer": "下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在房间下看书。", "explanation": "这里应该用〈里〉。“在……里”指在某个空间的内部；“下”指低处的底下，“在房间下看书”意思是在房间的下面，与“在房间里看书”不符。"}, {"text": "这个问题在会议下讨论了。", "explanation": "这里应该用〈上〉。“在……上”用于会议等场合；“下”只用于具体事物的低处。"}, {"text": "这件事在大家下传开了。", "explanation": "这里应该用〈中〉。“在大家中”指范围，“下”不能表示人群的范围。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85731, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "下", "is_correct": true, "explanation": "下（xià）指较低的位置，是本题的目标词。"}, {"text": "瞎", "is_correct": false, "explanation": "xiā（第一声）与 xià（第四声）声调不同，意思是看不见。"}, {"text": "狭", "is_correct": false, "explanation": "xiá（第二声）与 xià（第四声）声调不同，意思是狭窄。"}, {"text": "嫁", "is_correct": false, "explanation": "jià 与 xià 声母不同（j/x），意思是出嫁。"}], "explanations": {"下": "下（xià）指较低的位置，是本题的目标词。", "瞎": "xiā（第一声）与 xià（第四声）声调不同，意思是看不见。", "狭": "xiá（第二声）与 xià（第四声）声调不同，意思是狭窄。", "嫁": "jià 与 xià 声母不同（j/x），意思是出嫁。"}, "sentence_index": null, "correct_answer": "下"}, "level_3": {"options": [{"text": "下", "is_correct": true, "explanation": "“下”指桥的下面，与在桥下休息的情境相符。"}, {"text": "间", "is_correct": false, "explanation": "语义：“间”表示两者或多者之间，一座桥不能说“桥间”。"}, {"text": "里", "is_correct": false, "explanation": "语义：桥不是可以进入休息的容器，“桥里”不合常理。"}, {"text": "去", "is_correct": false, "explanation": "语法：“去”是动词，不是方位词，不能说“在桥去休息”。"}], "explanations": {"下": "“下”指桥的下面，与在桥下休息的情境相符。", "间": "语义：“间”表示两者或多者之间，一座桥不能说“桥间”。", "里": "语义：桥不是可以进入休息的容器，“桥里”不合常理。", "去": "语法：“去”是动词，不是方位词，不能说“在桥去休息”。"}, "sentence_index": 6, "correct_answer": "下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在老师下学习，进步很快。", "explanation": "这里应该用〈在……的指导下〉。“下”后不能直接接人，要说“在老师的指导下”。"}, {"text": "这本书在生活下很有用。", "explanation": "这里应该用〈里〉。“在……里”可以表示范围，“下”不能接“生活”这样的抽象名词。"}, {"text": "我在门下等你。", "explanation": "这里应该用〈前〉。“在门前”指门口的前方；“下”指低处的底下，“门下等你”不是正常的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85731, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书在桌子下里。", "corrected_sentence": "书在桌子下。", "error_description": "错误：“下”已表示方位，后面不能再加“里”。正确说法是“书在桌子下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85731, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗在树的下睡觉。", "corrected_sentence": "小狗在树下睡觉。", "error_description": "错误：“下”作方位词时，前面不加“的”。正确说法是“树下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85732, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上", "is_correct": true, "explanation": "“上”与“下”构成反义，上车与下车相对。"}, {"text": "出", "is_correct": false, "explanation": "“出”与“下”不构成反义，指从里向外。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”与“下”不构成反义，指快速移动。"}, {"text": "站", "is_correct": false, "explanation": "“站”与“下”不构成反义，指直立不动。"}], "correct_answer": "上", "explanations": {"上": "“上”与“下”构成反义，上车与下车相对。", "出": "“出”与“下”不构成反义，指从里向外。", "跑": "“跑”与“下”不构成反义，指快速移动。", "站": "“站”与“下”不构成反义，指直立不动。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85732, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上", "is_correct": true, "explanation": "“上”与“下”构成反义，“上台阶”与“下台阶”相对。"}, {"text": "进", "is_correct": false, "explanation": "“进”与“下”不构成反义，指向内移动。"}, {"text": "走", "is_correct": false, "explanation": "“走”与“下”不构成反义，指一般的行走。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”与“下”不构成反义，指腾空的动作。"}], "correct_answer": "上", "explanations": {"上": "“上”与“下”构成反义，“上台阶”与“下台阶”相对。", "进": "“进”与“下”不构成反义，指向内移动。", "走": "“走”与“下”不构成反义，指一般的行走。", "跳": "“跳”与“下”不构成反义，指腾空的动作。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85732, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，表示由高处到低处；也指从车、船等上离开。", "primary_collocate": null, "pronunciation": "xià", "ipa": "ɕja˥˩", "syllable_count": 1, "sentences": [{"text": "我们慢慢下山，天快黑了。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下楼去买水。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷下床去开门。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请在前面下车。", "target_word": "下", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人下船后，我们坐车去酒店。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳下山以后，天黑了。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你下楼的时候，请关灯。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟怕高，不敢下楼梯。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了学校门口，我下车了。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人腿疼，不敢下台阶。", "target_word": "下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了", "label": "体标"}, {"form": "下过", "label": "体标"}, {"form": "下楼", "label": "复合"}, {"form": "下车", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：由高处到低处（下山、下楼、下车）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a266faf8-e42e-483b-9de3-08d044cde7d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85732, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下", "is_correct": true, "explanation": "下（xià）表示由高处到低处，是本题的目标词。"}, {"text": "虾", "is_correct": false, "explanation": "xiā（第一声）与 xià（第四声）声调不同，意思是虾。"}, {"text": "霞", "is_correct": false, "explanation": "xiá（第二声）与 xià（第四声）声调不同，意思是云霞。"}, {"text": "价", "is_correct": false, "explanation": "jià 与 xià 声母不同（j/x），意思是价格。"}], "explanations": {"下": "下（xià）表示由高处到低处，是本题的目标词。", "虾": "xiā（第一声）与 xià（第四声）声调不同，意思是虾。", "霞": "xiá（第二声）与 xià（第四声）声调不同，意思是云霞。", "价": "jià 与 xià 声母不同（j/x），意思是价格。"}, "sentence_index": null, "correct_answer": "下"}, "level_3": {"options": [{"text": "下", "is_correct": true, "explanation": "“下山”指从高处走到低处，与“慢慢”和“天快黑了”相符。"}, {"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不表示走路下山的动作，“拿山”不通，不能说“慢慢拿山”。"}, {"text": "摔", "is_correct": false, "explanation": "搭配：“摔”不表示走路下来的动作，不能说“慢慢摔山”。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖山”指挖掘山体，不能用来表示慢慢走下山。"}], "explanations": {"下": "“下山”指从高处走到低处，与“慢慢”和“天快黑了”相符。", "拿": "搭配：“拿”不表示走路下山的动作，“拿山”不通，不能说“慢慢拿山”。", "摔": "搭配：“摔”不表示走路下来的动作，不能说“慢慢摔山”。", "挖": "搭配：“挖山”指挖掘山体，不能用来表示慢慢走下山。"}, "sentence_index": 0, "correct_answer": "下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下学校上课。", "explanation": "这里应该用〈到〉。“到”表示抵达某地；“下”表示由高处向低处移动，学校不是要下去的地方，“下学校”不通。"}, {"text": "他下山顶看日出。", "explanation": "这里应该用〈登〉。“登上山顶”指向上攀登；“下”表示由高向低，“下山顶”与“登上山顶”的方向相反。"}, {"text": "他下美国留学了。", "explanation": "这里应该用〈去〉。“去”表示前往某地；“下”只表示由高处到低处，不能用于国家这类地点，“下美国”不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85732, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "下", "is_correct": true, "explanation": "下（xià）表示由高处到低处，是本题的目标词。"}, {"text": "瞎", "is_correct": false, "explanation": "xiā（第一声）与 xià（第四声）声调不同，意思是看不见。"}, {"text": "狭", "is_correct": false, "explanation": "xiá（第二声）与 xià（第四声）声调不同，意思是狭窄。"}, {"text": "嫁", "is_correct": false, "explanation": "jià 与 xià 声母不同（j/x），意思是出嫁。"}], "explanations": {"下": "下（xià）表示由高处到低处，是本题的目标词。", "瞎": "xiā（第一声）与 xià（第四声）声调不同，意思是看不见。", "狭": "xiá（第二声）与 xià（第四声）声调不同，意思是狭窄。", "嫁": "jià 与 xià 声母不同（j/x），意思是出嫁。"}, "sentence_index": null, "correct_answer": "下"}, "level_3": {"options": [{"text": "下", "is_correct": true, "explanation": "“下楼”指从楼上走到楼下，与“请关灯”的情境相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”不能与“楼”搭配，“喝楼”不通。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住楼”不能单说，需说“住在楼里”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“楼”搭配，“吃楼”不通。"}], "explanations": {"下": "“下楼”指从楼上走到楼下，与“请关灯”的情境相符。", "喝": "搭配：“喝”不能与“楼”搭配，“喝楼”不通。", "住": "搭配：“住楼”不能单说，需说“住在楼里”。", "吃": "搭配：“吃”不能与“楼”搭配，“吃楼”不通。"}, "sentence_index": 6, "correct_answer": "下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他下公园锻炼身体。", "explanation": "这里应该用〈去〉。“去”表示前往某地；“下”表示由高向低，公园不是要下去的地方，“下公园”不通。"}, {"text": "气球下到了天上。", "explanation": "这里应该用〈升〉。“升”表示由低向高；“下”表示由高向低，气球飞向天上应是向上运动，不能用“下”。"}, {"text": "他从一楼下到五楼。", "explanation": "这里应该用〈上〉。从一楼到五楼是由低处到高处；“下”表示由高处到低处，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85732, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他楼下去拿东西。", "corrected_sentence": "他下楼去拿东西。", "error_description": "错误：“下楼”是动词加宾语的结构，“楼下”是方位名词，不能倒过来说。正确说法是“下楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85732, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人慢慢走下来台阶。", "corrected_sentence": "老人慢慢走下台阶。", "error_description": "错误：“下来”不能直接带处所宾语“台阶”；“走下台阶”中“下”作补语，应为“走下台阶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '631a1c77-d455-47a6-a96a-c1e5004784e0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
