INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "动词，表示否定判断，不等于，与“是”相对。", "primary_collocate": null, "pronunciation": "bú shì", "ipa": "pu˧˥ ʂɨ˥˩", "syllable_count": 2, "sentences": [{"text": "她不是医生，是护士。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在不是睡觉的时候。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说的不是真话。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买书不是我今天的目的。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个办法不是最好的办法。", "target_word": "不是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不是坏人，请你放心。", "target_word": "不是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看电视不是学习。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "北京不是中国最大的城市。", "target_word": "不是", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这不是你的错。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "钱不是最重要的东西。", "target_word": "不是", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "是不是", "label": "正反疑问形式"}], "register": "通用", "sense_fingerprint": "否定判断动词，与“是”相对，表示不等于、不属于", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '35c41e43-d819-4200-99d8-f4259434702f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确答案：不是（bú shì），表示否定判断。"}, {"text": "不识", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“不认识”。"}, {"text": "不使", "is_correct": false, "explanation": "shǐ（第三声）与 shì（第四声）声调不同，意思是“不使用”。"}, {"text": "不失", "is_correct": false, "explanation": "shī（第一声）与 shì（第四声）声调不同，意思是“没有失去”。"}, {"text": "部室", "is_correct": false, "explanation": "“部”读 bù（第四声），与“不是”的“不”（bú，第二声）声调不同，意思是部门的办公室。"}], "explanations": {"不是": "正确答案：不是（bú shì），表示否定判断。", "不识": "shí（第二声）与 shì（第四声）声调不同，意思是“不认识”。", "不使": "shǐ（第三声）与 shì（第四声）声调不同，意思是“不使用”。", "不失": "shī（第一声）与 shì（第四声）声调不同，意思是“没有失去”。", "部室": "“部”读 bù（第四声），与“不是”的“不”（bú，第二声）声调不同，意思是部门的办公室。"}, "sentence_index": null, "correct_answer": "不是"}, "level_3": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确：“不是”否定“医生”这一身份判断，与后句“是护士”形成对比。"}, {"text": "变成", "is_correct": false, "explanation": "语义：“变成”表示发生变化，与“是护士”的身份判断相矛盾，前后语义不通。"}, {"text": "当", "is_correct": false, "explanation": "搭配：“当”后接的职务表示担任，与后句“是护士”的身份判断冲突，两者不能并列。"}, {"text": "有", "is_correct": false, "explanation": "配价：“有”带的是所有物，不能直接用“医生”这类身份名词来说明“她是……”。"}], "explanations": {"不是": "正确：“不是”否定“医生”这一身份判断，与后句“是护士”形成对比。", "变成": "语义：“变成”表示发生变化，与“是护士”的身份判断相矛盾，前后语义不通。", "当": "搭配：“当”后接的职务表示担任，与后句“是护士”的身份判断冲突，两者不能并列。", "有": "配价：“有”带的是所有物，不能直接用“医生”这类身份名词来说明“她是……”。"}, "sentence_index": 0, "correct_answer": "不是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服不是漂亮。", "explanation": "否定形容词谓语应用“不”，“不是”只用于判断，这里应说“这件衣服不漂亮”。"}, {"text": "你不是说话，安静一点。", "explanation": "表示禁止某事应用“不要”或“别”，“不是”不能用于禁止，这里应说“你别说话，安静一点”。"}, {"text": "他从来不是去过上海。", "explanation": "表示没有某种经历应用“没”，“不是”不能和“过”搭配否定经历，这里应说“他从来没去过上海”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确答案：不是（bú shì），表示否定判断。"}, {"text": "博士", "is_correct": false, "explanation": "bó 与 bú 韵母不同（o 与 u），意思是学位“博士”。"}, {"text": "不时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是“时常”。"}, {"text": "不似", "is_correct": false, "explanation": "sì 与 shì 声母不同（s 与 sh），声调相同，意思是“不像”。"}, {"text": "不致", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是“不会导致”。"}], "explanations": {"不是": "正确答案：不是（bú shì），表示否定判断。", "博士": "bó 与 bú 韵母不同（o 与 u），意思是学位“博士”。", "不时": "shí（第二声）与 shì（第四声）声调不同，意思是“时常”。", "不似": "sì 与 shì 声母不同（s 与 sh），声调相同，意思是“不像”。", "不致": "zhì 与 shì 声母不同（zh 与 sh），声调相同，意思是“不会导致”。"}, "sentence_index": null, "correct_answer": "不是"}, "level_3": {"options": [{"text": "不是", "is_correct": true, "explanation": "正确：“不是”否定“看电视”属于“学习”，与句意一致。"}, {"text": "成为", "is_correct": false, "explanation": "语义：“成为”表示转变为某种状态，“看电视”与“学习”之间不存在转变关系。"}, {"text": "讨厌", "is_correct": false, "explanation": "搭配：“讨厌”要求有情感的人作主语，“看电视”作主语无法表达厌恶。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”需要有意志的主体，“看电视”不能对“学习”表示反对。"}], "explanations": {"不是": "正确：“不是”否定“看电视”属于“学习”，与句意一致。", "成为": "语义：“成为”表示转变为某种状态，“看电视”与“学习”之间不存在转变关系。", "讨厌": "搭配：“讨厌”要求有情感的人作主语，“看电视”作主语无法表达厌恶。", "反对": "语义：“反对”需要有意志的主体，“看电视”不能对“学习”表示反对。"}, "sentence_index": 6, "correct_answer": "不是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间不是干净。", "explanation": "否定形容词谓语应用“不”，“不是”只用于判断，这里应说“这个房间不干净”。"}, {"text": "我今天不是迟到了。", "explanation": "表示没有迟到应用“没”，“不是”不能与“了”搭配否定动作，这里应说“我今天没迟到”。"}, {"text": "他不是会跑步。", "explanation": "表示不会做某事应用“不会”或“不能”，“不是”只表示判断，这里应说“他不会跑步”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他不是是中国人。", "corrected_sentence": "他不是中国人。", "error_description": "错误：“是”多写了一遍，成了“不是是”。应为“不是中国人”，判断句的否定只用一个“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85734, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我不是了学生。", "corrected_sentence": "我不是学生。", "error_description": "错误：“不是”后面不能加“了”，“不是”是否定判断的固定格式。应说“我不是学生”，不能说“我不是了学生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b3042e5-b35f-462e-9b42-3d0f42ef5c59') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
