INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85736, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "结构助词，相当于“的”，用在定语和中心语之间。", "primary_collocate": null, "pronunciation": "zhī", "ipa": "ʈʂɻ̩˥", "syllable_count": 1, "sentences": [{"text": "这是一本开启智慧之门的书。", "target_word": "之", "complexity_tier": "T3", "furigana": "zhī", "sentence_source": "generated"}, {"text": "他选择了一条改革之路。", "target_word": "之", "complexity_tier": "T3", "furigana": "zhī", "sentence_source": "generated"}, {"text": "他有一颗爱国之心。", "target_word": "之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "健康是幸福之本。", "target_word": "之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里是艺术之都。", "target_word": "之", "complexity_tier": "T3", "furigana": "zhī", "sentence_source": "generated"}, {"text": "孩子们的笑声是我们快乐之源。", "target_word": "之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是他十年心血之作。", "target_word": "之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们班的学习之星。", "target_word": "之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一次学习之旅，我们学到了很多。", "target_word": "之", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子是全家的希望之光。", "target_word": "之", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "结构助词“的”，连接定语和中心语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85736, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "之", "is_correct": true, "explanation": "正确：之（zhī）在这里是结构助词，相当于“的”，连接定语和中心语。"}, {"text": "只", "is_correct": false, "explanation": "声调不同：zhǐ（第三声）与 zhī（第一声），意思是只有。"}, {"text": "吃", "is_correct": false, "explanation": "声母不同：chī 的声母是 ch，zhī 的声母是 zh，意思是吃。"}, {"text": "诗", "is_correct": false, "explanation": "声母不同：shī 的声母是 sh，zhī 的声母是 zh，意思是诗歌。"}, {"text": "直", "is_correct": false, "explanation": "声调不同：zhí（第二声）与 zhī（第一声），意思是笔直。"}], "explanations": {"之": "正确：之（zhī）在这里是结构助词，相当于“的”，连接定语和中心语。", "只": "声调不同：zhǐ（第三声）与 zhī（第一声），意思是只有。", "吃": "声母不同：chī 的声母是 ch，zhī 的声母是 zh，意思是吃。", "诗": "声母不同：shī 的声母是 sh，zhī 的声母是 zh，意思是诗歌。", "直": "声调不同：zhí（第二声）与 zhī（第一声），意思是笔直。"}, "sentence_index": null, "correct_answer": "之"}, "level_3": {"options": [{"text": "之", "is_correct": true, "explanation": "正确：“智慧之门”中的“之”是结构助词，连接定语和中心语。"}, {"text": "所", "is_correct": false, "explanation": "配价：“所”后要接动词，“智慧所门”不成立。"}, {"text": "地", "is_correct": false, "explanation": "搭配：“地”修饰动词，不能放在“智慧”和“门”之间。"}, {"text": "得", "is_correct": false, "explanation": "配价：“得”用在动词或形容词后作补语，不能连接名词。"}], "explanations": {"之": "正确：“智慧之门”中的“之”是结构助词，连接定语和中心语。", "所": "配价：“所”后要接动词，“智慧所门”不成立。", "地": "搭配：“地”修饰动词，不能放在“智慧”和“门”之间。", "得": "配价：“得”用在动词或形容词后作补语，不能连接名词。"}, "sentence_index": 0, "correct_answer": "之"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是我之书包，很重。", "explanation": "这里应该用〈的〉。“之”是书面语中的结构助词，与“的”同义，但口语中修饰“我”这类人称代词时说“我的书包”，不说“我之书包”。"}, {"text": "这家商店之衣服很好看，大家都想买。", "explanation": "这里应该用〈的〉。“之”多用于书面，口语中要说“这家商店的衣服”，此句用“之”不自然。"}, {"text": "学校之食堂很大，我们每天都去吃饭。", "explanation": "这里应该用〈的〉。“之”多用于书面，口语中要说“学校的食堂”，此句用“之”不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85736, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "之", "is_correct": true, "explanation": "正确：之（zhī）在这里是结构助词，相当于“的”，连接定语和中心语。"}, {"text": "指", "is_correct": false, "explanation": "声调不同：zhǐ（第三声）与 zhī（第一声），意思是指向。"}, {"text": "志", "is_correct": false, "explanation": "声调不同：zhì（第四声）与 zhī（第一声），意思是志向。"}, {"text": "资", "is_correct": false, "explanation": "声母不同：zī 的声母是 z，zhī 的声母是 zh，意思是资金。"}, {"text": "职", "is_correct": false, "explanation": "声调不同：zhí（第二声）与 zhī（第一声），意思是职业。"}], "explanations": {"之": "正确：之（zhī）在这里是结构助词，相当于“的”，连接定语和中心语。", "指": "声调不同：zhǐ（第三声）与 zhī（第一声），意思是指向。", "志": "声调不同：zhì（第四声）与 zhī（第一声），意思是志向。", "资": "声母不同：zī 的声母是 z，zhī 的声母是 zh，意思是资金。", "职": "声调不同：zhí（第二声）与 zhī（第一声），意思是职业。"}, "sentence_index": null, "correct_answer": "之"}, "level_3": {"options": [{"text": "之", "is_correct": true, "explanation": "正确：“心血之作”中的“之”是结构助词，连接定语和中心语。"}, {"text": "吗", "is_correct": false, "explanation": "配价：“吗”只用于句末表示疑问，不能放在定语和中心语之间。"}, {"text": "吧", "is_correct": false, "explanation": "语域：“吧”是口语语气词，书面的定语结构中不用。"}, {"text": "呢", "is_correct": false, "explanation": "配价：“呢”用于句末或停顿处，不能连接“心血”和“作”。"}], "explanations": {"之": "正确：“心血之作”中的“之”是结构助词，连接定语和中心语。", "吗": "配价：“吗”只用于句末表示疑问，不能放在定语和中心语之间。", "吧": "语域：“吧”是口语语气词，书面的定语结构中不用。", "呢": "配价：“呢”用于句末或停顿处，不能连接“心血”和“作”。"}, "sentence_index": 6, "correct_answer": "之"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校之操场很大，大家都喜欢来玩。", "explanation": "这里应该用〈的〉。“之”多用于书面，口语中要说“学校的操场”，此句用“之”不自然。"}, {"text": "爸爸之车很新，大家都想坐。", "explanation": "这里应该用〈的〉。“之”是书面语，口语中修饰“爸爸”这类称谓要说“爸爸的车”，不说“爸爸之车”。"}, {"text": "这本书之作者很有名，大家都读过他的书。", "explanation": "这里应该用〈的〉。“之”多用于书面，口语中要说“这本书的作者”，此处用“之”不自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他走上了一条幸福之的路。", "corrected_sentence": "他走上了一条幸福之路。", "error_description": "重复标记：“幸福之路”中“之”已标记定语，不能再加“的”，应说“幸福之路”，不说“幸福之的路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个充满欢笑之的家。", "corrected_sentence": "这是一个充满欢笑之家。", "error_description": "重复标记：“之”和“的”不能同时标记同一定语，只用“之”即可，应说“欢笑之家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。"}, {"text": "清晨", "is_correct": false, "explanation": "“清晨”指一天中早上的时段，与“现在”不构成相对关系。"}, {"text": "深夜", "is_correct": false, "explanation": "“深夜”指夜深的时段，与“现在”没有时间上的相对关系。"}, {"text": "傍晚", "is_correct": false, "explanation": "“傍晚”指太阳快落山的时段，与“现在”不构成反义关系。"}], "correct_answer": "过去", "explanations": {"过去": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。", "清晨": "“清晨”指一天中早上的时段，与“现在”不构成相对关系。", "深夜": "“深夜”指夜深的时段，与“现在”没有时间上的相对关系。", "傍晚": "“傍晚”指太阳快落山的时段，与“现在”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "将来", "is_correct": true, "explanation": "“将来”指说话之后的时间，与“现在”构成时间上的反义关系。"}, {"text": "凌晨", "is_correct": false, "explanation": "“凌晨”指天亮前的一段时间，与“现在”没有相对关系。"}, {"text": "午后", "is_correct": false, "explanation": "“午后”指中午以后的时段，与“现在”不构成反义关系。"}, {"text": "午夜", "is_correct": false, "explanation": "“午夜”指夜间十二点前后，与“现在”不构成相对关系。"}], "correct_answer": "将来", "explanations": {"将来": "“将来”指说话之后的时间，与“现在”构成时间上的反义关系。", "凌晨": "“凌晨”指天亮前的一段时间，与“现在”没有相对关系。", "午后": "“午后”指中午以后的时段，与“现在”不构成反义关系。", "午夜": "“午夜”指夜间十二点前后，与“现在”不构成相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "“现在”是说说话的这个时候。", "primary_collocate": null, "pronunciation": "xiàn zài", "ipa": "ɕjɛn˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "现在几点了？", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在在学校，不在家。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他现在不忙，你可以来。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在外面在下雨，带把伞吧。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你现在在做什么？", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在要出门了，再见。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭做好了，现在我们去吃吧。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸现在正在家看书。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在是晚上八点。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她现在很累，想回家休息。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現在", "label": "繁体"}], "register": "通用", "sense_fingerprint": "说话的这个时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb7735c-2a9b-4b0a-9aa5-30409c5f4706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在”指说话的此刻，与“几点了”的询问相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指前一天，与询问当前钟点的“几点了”冲突。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指第二天，无法用来询问说话时刻的钟点。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指上一年，是时间名词，不能用来询问说话时刻的钟点，与“几点了”不能搭配。"}], "explanations": {"现在": "“现在”指说话的此刻，与“几点了”的询问相符。", "昨天": "语义：“昨天”指前一天，与询问当前钟点的“几点了”冲突。", "明天": "语义：“明天”指第二天，无法用来询问说话时刻的钟点。", "去年": "语义：“去年”指上一年，是时间名词，不能用来询问说话时刻的钟点，与“几点了”不能搭配。"}, "sentence_index": 0, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "1990年，我现在在上海读书。", "explanation": "这里应该用〈当时〉。“现在”指说话的这一时刻，不能用来指1990年这样的过去时间。"}, {"text": "明天，我现在出发去北京。", "explanation": "这里的时间只应由〈明天〉表示。“现在”指说话的此刻，与“明天”这样的未来时间冲突，应去掉“现在”。"}, {"text": "去年，我们现在决定搬家。", "explanation": "这里应只保留〈去年〉表示过去的时间，去掉“现在”。“现在”指说话的此刻，不能与“去年”同时指示同一事件的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在”指说话的此刻，饭已做好，正适合此刻去吃。"}, {"text": "以前", "is_correct": false, "explanation": "语义：“以前”指过去，与“饭做好了”后提议去吃的语境不符。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指不久前，与“饭做好了”后提议去吃的语境不符。"}, {"text": "早先", "is_correct": false, "explanation": "语义：“早先”指很早以前，与“饭做好了”的当下语境冲突。"}], "explanations": {"现在": "“现在”指说话的此刻，饭已做好，正适合此刻去吃。", "以前": "语义：“以前”指过去，与“饭做好了”后提议去吃的语境不符。", "刚才": "语义：“刚才”指不久前，与“饭做好了”后提议去吃的语境不符。", "早先": "语义：“早先”指很早以前，与“饭做好了”的当下语境冲突。"}, "sentence_index": 6, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小时候，我现在很怕狗。", "explanation": "这里不能用〈现在〉。“现在”指说话的此刻，与表示过去的“小时候”冲突，应只保留〈小时候〉，去掉“现在”。"}, {"text": "上个月，他现在生病了。", "explanation": "这里不能用〈现在〉。“现在”指说话时刻，不能指上个月发生的事，应只用〈上个月〉。"}, {"text": "以后，我现在去上海工作。", "explanation": "这里不能用〈现在〉。“现在”指说话时刻，与表示将来的〈以后〉冲突，应只保留〈以后〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹在现在睡觉，别吵她。", "corrected_sentence": "妹妹现在在睡觉，别吵她。", "error_description": "时间词“现在”作状语，应放在主语后、“在”之前。错误形式“在现在睡觉”把“现在”与“在”的顺序颠倒，应说“妹妹现在在睡觉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85737, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子现在的在写作业。", "corrected_sentence": "孩子现在在写作业。", "error_description": "“现在”作状语修饰动词时不带“的”，“的”只用于“现在的”后接名词作定语，如“现在的孩子”。错误形式“现在的在写作业”不成立，应说“孩子现在在写作业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "过去", "is_correct": true, "explanation": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。"}, {"text": "黎明", "is_correct": false, "explanation": "“黎明”指天将亮的时候，与“现在”不构成相对关系。"}, {"text": "中午", "is_correct": false, "explanation": "“中午”指一天中午前后的时段，与“现在”不是反义关系。"}, {"text": "夜间", "is_correct": false, "explanation": "“夜间”指夜里的时段，与“现在”不构成时间上的相对关系。"}], "correct_answer": "过去", "explanations": {"过去": "“过去”指说话时刻之前的时间，与“现在”构成时间上的反义关系。", "黎明": "“黎明”指天将亮的时候，与“现在”不构成相对关系。", "中午": "“中午”指一天中午前后的时段，与“现在”不是反义关系。", "夜间": "“夜间”指夜里的时段，与“现在”不构成时间上的相对关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "将来", "is_correct": true, "explanation": "“将来”指说话之后的时间，与“过去”“现在”构成时间上的对照。"}, {"text": "黄昏", "is_correct": false, "explanation": "“黄昏”指日落前后的时段，与“现在”不构成相对关系。"}, {"text": "下午", "is_correct": false, "explanation": "“下午”指中午到晚上之间的时段，与“现在”没有反义关系。"}, {"text": "半夜", "is_correct": false, "explanation": "“半夜”指深夜的一段时间，与“现在”不构成相对关系。"}], "correct_answer": "将来", "explanations": {"将来": "“将来”指说话之后的时间，与“过去”“现在”构成时间上的对照。", "黄昏": "“黄昏”指日落前后的时段，与“现在”不构成相对关系。", "下午": "“下午”指中午到晚上之间的时段，与“现在”没有反义关系。", "半夜": "“半夜”指深夜的一段时间，与“现在”不构成相对关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "名词，指当前这一阶段、如今，与“过去”“将来”相对。", "primary_collocate": null, "pronunciation": "xiàn zài", "ipa": "ɕjɛn˥˩ tsaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "以前他很瘦，现在很胖。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去我喜欢跑步，现在喜欢游泳。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不学，将来会后悔。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候我住乡下，现在住城里。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年他还不会说汉语，现在说得很好。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过去的事别想了，想想现在吧。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前没有手机，现在的孩子都有。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我现在工作很忙，以后会有时间。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前这里是田，现在是学校。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过去在上海，现在在广州。", "target_word": "现在", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "現在", "label": "繁体"}], "register": "通用", "sense_fingerprint": "与过去、将来相对的当前阶段或如今", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1eb7735c-2a9b-4b0a-9aa5-30409c5f4706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在”与“以前”构成对照，表示当下的状态，填入后句意通顺。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”与“以前”同指过去，无法与“很瘦”形成今昔对照。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“以前他很瘦”对照时句意矛盾。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”指不久前，不能表示与“以前”相对的当前阶段。"}], "explanations": {"现在": "“现在”与“以前”构成对照，表示当下的状态，填入后句意通顺。", "从前": "语义：“从前”与“以前”同指过去，无法与“很瘦”形成今昔对照。", "明天": "语义：“明天”指将来，与“以前他很瘦”对照时句意矛盾。", "刚才": "语义：“刚才”指不久前，不能表示与“以前”相对的当前阶段。"}, "sentence_index": 0, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那时的现在，我很害怕。", "explanation": "这里不能用〈现在〉。“现在”指当前这一阶段，不能用来指过去的某段时间，应改用〈当时〉。"}, {"text": "过去我现在喜欢跑步。", "explanation": "这里应只用〈过去〉。“现在”与“过去”指向不同时间，不能同时修饰“喜欢跑步”。"}, {"text": "我现在将来要当医生。", "explanation": "这里应只用〈将来〉。“现在”指当前阶段，与“将来”同时修饰同一动作，时间指向冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "现在", "is_correct": true, "explanation": "“现在的孩子”指当今的孩子，与“以前没有手机”形成对照。"}, {"text": "清早", "is_correct": false, "explanation": "语义：“清早”指一天的早晨，无法与“以前没有手机”的对照语境搭配，句意不通。"}, {"text": "傍晚", "is_correct": false, "explanation": "语义：“傍晚”指白天将尽的时段，与“以前没有手机”的对照语境不通。"}, {"text": "夜里", "is_correct": false, "explanation": "语义：“夜里”指夜间，不能作为“孩子”的时间定语来对照“以前”。"}], "explanations": {"现在": "“现在的孩子”指当今的孩子，与“以前没有手机”形成对照。", "清早": "语义：“清早”指一天的早晨，无法与“以前没有手机”的对照语境搭配，句意不通。", "傍晚": "语义：“傍晚”指白天将尽的时段，与“以前没有手机”的对照语境不通。", "夜里": "语义：“夜里”指夜间，不能作为“孩子”的时间定语来对照“以前”。"}, "sentence_index": 6, "correct_answer": "现在"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "去年他现在在广州。", "explanation": "这里不能用〈现在〉。“现在”指当前阶段，与表示过去的〈去年〉冲突，应只保留〈去年〉。"}, {"text": "上周他现在在广州。", "explanation": "这里不能用〈现在〉。“现在”指当前阶段，不能指上周的状况，应只保留〈上周〉。"}, {"text": "当时他现在在广州。", "explanation": "这里不能用〈现在〉。“当时”指过去的某一时间，与“现在”同时使用时时间指向冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们以前住在山里，在现在城里住。", "corrected_sentence": "我们以前住在山里，现在在城里住。", "error_description": "“现在”作时间状语，应放在主语后、“在”之前。错误形式“在现在城里住”把“在”放到“现在”前，语序不通，应说“现在在城里住”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我以前很胖，现在我的很瘦。", "corrected_sentence": "我以前很胖，现在的我很瘦。", "error_description": "“现在的”修饰代词“我”，“的”应紧跟在“现在”后。错误形式把“的”放到“我”后，成了“现在我的很瘦”，句子不通。应说“现在的我很瘦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '730d9adb-f06d-478e-b06a-7cec07ec77a1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
