INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85741, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "“里”是说在一个东西的里面。", "primary_collocate": null, "pronunciation": "lǐ", "ipa": "li˨˩˦", "syllable_count": 1, "sentences": [{"text": "糖放在杯子里，看不见了。", "target_word": "里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包里装着三本书。", "target_word": "里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把钥匙藏在盒子里。", "target_word": "里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里很冷，牛奶不会坏。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小猫钻进箱子里睡觉。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "口袋里有一张小纸条。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把零钱放进钱包里。", "target_word": "里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子里的水喝完了。", "target_word": "里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我听见箱子里有声音。", "target_word": "里", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "鱼缸里养着三条小鱼。", "target_word": "里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "里面", "label": "复合"}, {"form": "里头", "label": "复合"}, {"form": "裡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "里|方位词|东西的里面，容器内部", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T1: 3 words above tier T1 (max 2): 小猫 (Zipf 3.7), 钻进 (Zipf 3.44), 箱子 (Zipf 3.78)','sentence 9 above tier T1: 3 words above tier T1 (max 2): 缸 (Zipf 3.54), 三条 (Zipf 3.95), 小鱼 (Zipf 3.58)']::text[], 'e09e1671-b6a6-4032-8b8c-f04eced1b808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85741, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "里", "is_correct": true, "explanation": "目标词，读 lǐ（第三声），表示在某物的内部。"}, {"text": "你", "is_correct": false, "explanation": "nǐ 与 lǐ 只有声母不同（n 与 l），意思是“你”。"}, {"text": "力", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，意思是“力量”。"}, {"text": "梨", "is_correct": false, "explanation": "lí（第二声）与 lǐ（第三声）声调不同，意思是“梨子”。"}], "explanations": {"里": "目标词，读 lǐ（第三声），表示在某物的内部。", "你": "nǐ 与 lǐ 只有声母不同（n 与 l），意思是“你”。", "力": "lì（第四声）与 lǐ（第三声）声调不同，意思是“力量”。", "梨": "lí（第二声）与 lǐ（第三声）声调不同，意思是“梨子”。"}, "sentence_index": null, "correct_answer": "里"}, "level_3": {"options": [{"text": "上", "is_correct": false, "explanation": "语义：「上」指表面，糖放在杯子表面就能看见，与“看不见了”矛盾。"}, {"text": "里", "is_correct": true, "explanation": "方位词，表示在杯子内部，糖在里面才会看不见。"}, {"text": "外", "is_correct": false, "explanation": "搭配：「杯子外」不如「杯子外面」自然，且“外”指外部，与“看不见”不合。"}, {"text": "旁", "is_correct": false, "explanation": "语义：「旁」指旁边，糖放在杯子旁边不会“看不见了”。"}], "explanations": {"上": "语义：「上」指表面，糖放在杯子表面就能看见，与“看不见了”矛盾。", "里": "方位词，表示在杯子内部，糖在里面才会看不见。", "外": "搭配：「杯子外」不如「杯子外面」自然，且“外”指外部，与“看不见”不合。", "旁": "语义：「旁」指旁边，糖放在杯子旁边不会“看不见了”。"}, "sentence_index": 0, "correct_answer": "里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冰箱上很冷，牛奶不会坏。", "explanation": "这里应该用〈里〉。「上」表示表面，说冰箱内部很冷要用「里」。"}, {"text": "我把牛奶放进冰箱旁，很快就坏了。", "explanation": "这里应该用〈里〉。「放进」表示进入内部，「冰箱旁」指旁边，二者搭配不成立，应说「放进冰箱里」。"}, {"text": "我把牛奶放进冰箱外，很快就坏了。", "explanation": "这里应该用〈里〉。「放进」表示进入内部，「冰箱外」指范围之外，二者矛盾，应说「放进冰箱里」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85741, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下", "is_correct": false, "explanation": "搭配：「放进」表示进入内部，「钱包下」不能与「放进」搭配。"}, {"text": "里", "is_correct": true, "explanation": "方位词，表示在钱包内部，“放进钱包里”表示零钱进入钱包内部。"}, {"text": "边", "is_correct": false, "explanation": "搭配：「钱包边」指旁侧，与「放进」表示进入内部不符。"}, {"text": "后", "is_correct": false, "explanation": "搭配：「后」指后方，「放进」表示进入内部，“放进钱包后”不表示放在钱包内部。"}], "explanations": {"下": "搭配：「放进」表示进入内部，「钱包下」不能与「放进」搭配。", "里": "方位词，表示在钱包内部，“放进钱包里”表示零钱进入钱包内部。", "边": "搭配：「钱包边」指旁侧，与「放进」表示进入内部不符。", "后": "搭配：「后」指后方，「放进」表示进入内部，“放进钱包后”不表示放在钱包内部。"}, "sentence_index": 6, "correct_answer": "里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我早上里喝了牛奶。", "explanation": "这里应该去掉〈里〉。「里」表示空间范围，不表示时间，早上喝牛奶直接说「早上」。"}, {"text": "他的脚里踩到了玻璃，很疼。", "explanation": "这里应该用〈上〉。“踩到”的东西在脚的外部，“脚里”搭配不成立，应说「脚上踩到」或「脚底踩到」。"}, {"text": "老师把三本书放进书包外。", "explanation": "这里应该用〈里〉。「放进」表示进入内部，「书包外」指范围之外，二者矛盾，应说「放进书包里」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85741, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冰箱在里很冷，所以牛奶不会坏。", "corrected_sentence": "冰箱里很冷，所以牛奶不会坏。", "error_description": "错误：「冰箱在里」中多加了「在」。「里」已表示位置，应直接说「冰箱里」。正确：应为「冰箱里很冷，所以牛奶不会坏」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85741, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师的书包上里有三本书。", "corrected_sentence": "老师的书包里有三本书。", "error_description": "错误：「书包上里」中多加了「上」。「里」已表示在某范围之内，不能再与「上」叠用。正确：应为「老师的书包里有三本书」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd36c74e0-1604-44fe-8b58-0e81438c5409') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
