INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85744, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，连接并列的词语，相当于“和”“以及”。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "本店出售电脑、手机及相机。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请填写姓名、年龄及电话。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的时间及地点已经定了。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的老师及学生都要参加。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京及上海是中国的大城市。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爱好是音乐、画画及运动。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的名字及地址写在这里。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里有床、桌子及椅子。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理及秘书下午去开会。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格及质量都要考虑。", "target_word": "及", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "及：连接并列的词语，相当于“和”“以及”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5414130c-939f-47d2-a1d8-a425c962efaa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85744, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "及", "is_correct": true, "explanation": "及（jí）：并列连接，相当于“和”“以及”。"}, {"text": "击", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是攻击。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, {"text": "饥", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是饥饿。"}, {"text": "既", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是既然。"}, {"text": "己", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。"}], "explanations": {"及": "及（jí）：并列连接，相当于“和”“以及”。", "击": "jī（第一声）与 jí（第二声）声调不同，意思是攻击。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。", "饥": "jī（第一声）与 jí（第二声）声调不同，意思是饥饿。", "既": "jì（第四声）与 jí（第二声）声调不同，意思是既然。", "己": "jǐ（第三声）与 jí（第二声）声调不同，意思是自己。"}, "sentence_index": null, "correct_answer": "及"}, "level_3": {"options": [{"text": "及", "is_correct": true, "explanation": "及：把“电脑、手机”和“相机”并列连接，相当于“和”。"}, {"text": "并且", "is_correct": false, "explanation": "搭配：“并且”连接动词或分句，不能连接名词“手机”和“相机”。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，这里的商品列举没有对立关系。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，这里是并列列举，没有因果关系。"}], "explanations": {"及": "及：把“电脑、手机”和“相机”并列连接，相当于“和”。", "并且": "搭配：“并且”连接动词或分句，不能连接名词“手机”和“相机”。", "然而": "语义：“然而”表示转折，这里的商品列举没有对立关系。", "因此": "语义：“因此”表示因果，这里是并列列举，没有因果关系。"}, "sentence_index": 0, "correct_answer": "及"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们及图书馆学习。", "explanation": "这里应该用〈在〉。及不能表示动作发生的地点，“在图书馆学习”要用〈在〉。"}, {"text": "他及公司出发。", "explanation": "这里应该用〈从〉。及不能表示动作的起点，“从公司出发”要用〈从〉。"}, {"text": "他们下周及上海。", "explanation": "这里应该用〈去〉。及不能表示前往某地，“去上海”要用〈去〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85744, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "及", "is_correct": true, "explanation": "及（jí）：并列连接，相当于“和”“以及”。"}, {"text": "积", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是积累。"}, {"text": "继", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是继续。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。"}], "explanations": {"及": "及（jí）：并列连接，相当于“和”“以及”。", "积": "jī（第一声）与 jí（第二声）声调不同，意思是积累。", "继": "jì（第四声）与 jí（第二声）声调不同，意思是继续。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是拥挤。"}, "sentence_index": null, "correct_answer": "及"}, "level_3": {"options": [{"text": "及", "is_correct": true, "explanation": "及：把“名字”和“地址”并列连接，相当于“和”。"}, {"text": "不但", "is_correct": false, "explanation": "搭配：“不但”要与“而且”配合，不能直接连接两个名词。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与“但是”“却”等配合，不能直接连接名词。"}, {"text": "可是", "is_correct": false, "explanation": "语义：“可是”表示转折，“名字”和“地址”之间没有对立关系。"}], "explanations": {"及": "及：把“名字”和“地址”并列连接，相当于“和”。", "不但": "搭配：“不但”要与“而且”配合，不能直接连接两个名词。", "虽然": "搭配：“虽然”要与“但是”“却”等配合，不能直接连接名词。", "可是": "语义：“可是”表示转折，“名字”和“地址”之间没有对立关系。"}, "sentence_index": 6, "correct_answer": "及"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "请及钥匙开门。", "explanation": "这里应该用〈用〉。及不能引出工具，“用钥匙开门”要用〈用〉。"}, {"text": "请及门关上。", "explanation": "这里应该用〈把〉。及不能引出被处置的对象，“把门关上”要用〈把〉。"}, {"text": "他及我高。", "explanation": "这里应该用〈比〉。及不能表示比较，“他比我高”要用〈比〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐及都喜欢这部电影。", "corrected_sentence": "姐姐及弟弟都喜欢这部电影。", "error_description": "错误：“及”后面缺少并列的第二项。正确：应补上第二个名词，写作“姐姐及弟弟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子及和老人都需要休息。", "corrected_sentence": "孩子及老人都需要休息。", "error_description": "错误：“及”后面又加了“和”，两个并列连接词叠用。正确：只用“及”，写作“孩子及老人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '74c239b0-d2e8-4da2-ab24-66804dbd2932') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
