INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85745, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "别人问你，你说“是的”，就是说对，是这样。", "primary_collocate": null, "pronunciation": "shì de", "ipa": "ʂɻ̩˥˩ tɤ", "syllable_count": 2, "sentences": [{"text": "“你是学生吗？”“是的，我是学生。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问：“你昨天去医院了吗？”我说：“是的，我去了。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这是你的书吗？”“是的，这是我的。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你住在北京吗？”“是的，我住在北京。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问我：“你是中国人吗？”我回答：“是的。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“今天是星期五吗？”“是的，明天不上班。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生问：“你头疼吗？”病人说：“是的，很疼。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你想喝茶吗？”“是的，请给我一杯。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈问：“你吃饭了吗？”我说：“是的，吃了。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你们是同学吗？”“是的，我们在一个班。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回答问题时说“是的”，表示事实就是这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85745, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "是的", "is_correct": true, "explanation": "是的（shì de）：正确答案，表示同意或肯定的回答。"}, {"text": "似的", "is_correct": false, "explanation": "似的（sì de）：声母 s 与 sh 只差一个音位，是最小对立对，意思是“像……似的”。"}, {"text": "湿的", "is_correct": false, "explanation": "湿的（shī de）：第一个音节只与 shì 声调不同（第一声），意思是“潮湿的（东西）”。"}, {"text": "使得", "is_correct": false, "explanation": "shǐ dé 与 shì de 声调都不同（shǐ 为第三声，dé 为第二声），意思是使得。"}], "explanations": {"是的": "是的（shì de）：正确答案，表示同意或肯定的回答。", "似的": "似的（sì de）：声母 s 与 sh 只差一个音位，是最小对立对，意思是“像……似的”。", "湿的": "湿的（shī de）：第一个音节只与 shì 声调不同（第一声），意思是“潮湿的（东西）”。", "使得": "shǐ dé 与 shì de 声调都不同（shǐ 为第三声，dé 为第二声），意思是使得。"}, "sentence_index": null, "correct_answer": "是的"}, "level_3": {"options": [{"text": "是的", "is_correct": true, "explanation": "正确答案：“是的”肯定了前面“你是学生吗”的问题。"}, {"text": "不对", "is_correct": false, "explanation": "语义：“不对”否定了问题，与后面的“我是学生”自相矛盾。"}, {"text": "对不起", "is_correct": false, "explanation": "语义：“对不起”是道歉语，不能用来回答“你是学生吗”。"}, {"text": "谢谢", "is_correct": false, "explanation": "搭配：“谢谢”是致谢语，不能用来回应一个提问。"}], "explanations": {"是的": "正确答案：“是的”肯定了前面“你是学生吗”的问题。", "不对": "语义：“不对”否定了问题，与后面的“我是学生”自相矛盾。", "对不起": "语义：“对不起”是道歉语，不能用来回答“你是学生吗”。", "谢谢": "搭配：“谢谢”是致谢语，不能用来回应一个提问。"}, "sentence_index": 0, "correct_answer": "是的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“你吃饭了吗？”“是的，我还没吃。”", "explanation": "这里误用了肯定义。“是的”表示肯定，但后面的“我还没吃”是否定，应改用否定的〈没有〉。"}, {"text": "“这样做对吗？”“是的，这样做会出问题。”", "explanation": "这里误用了肯定义。“是的”表示“对”，但后面说“会出问题”是否定判断，应改用否定的〈不对〉。"}, {"text": "“你同意吗？”“是的，我不同意。”", "explanation": "这里误用了肯定义。“是的”表示同意，但“我不同意”是否定，应改用〈不〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85745, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "是的", "is_correct": true, "explanation": "是的（shì de）：正确答案，表示同意或肯定的回答。"}, {"text": "失德", "is_correct": false, "explanation": "失德（shī dé）：两个音节的声调都与 shì de 不同，意思是“道德上有缺失”。"}, {"text": "似的", "is_correct": false, "explanation": "似的（sì de）：声母 s 与 sh 只差一个音位，是最小对立对，意思是“像……似的”。"}, {"text": "拾得", "is_correct": false, "explanation": "拾得（shí dé）：两个音节的声调都与 shì de 不同，意思是“捡到、拾到”。"}], "explanations": {"是的": "是的（shì de）：正确答案，表示同意或肯定的回答。", "失德": "失德（shī dé）：两个音节的声调都与 shì de 不同，意思是“道德上有缺失”。", "似的": "似的（sì de）：声母 s 与 sh 只差一个音位，是最小对立对，意思是“像……似的”。", "拾得": "拾得（shí dé）：两个音节的声调都与 shì de 不同，意思是“捡到、拾到”。"}, "sentence_index": null, "correct_answer": "是的"}, "level_3": {"options": [{"text": "是的", "is_correct": true, "explanation": "正确答案：“是的”肯定了医生的问题，承认自己头疼。"}, {"text": "嘻嘻", "is_correct": false, "explanation": "语义：“嘻嘻”是笑声，与“很疼”的感受矛盾。"}, {"text": "好耶", "is_correct": false, "explanation": "语义：“好耶”表示高兴，与“很疼”的感受矛盾。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是表示鄙视的粗俗叹词，不适用于医生与病人的正式问答。"}], "explanations": {"是的": "正确答案：“是的”肯定了医生的问题，承认自己头疼。", "嘻嘻": "语义：“嘻嘻”是笑声，与“很疼”的感受矛盾。", "好耶": "语义：“好耶”表示高兴，与“很疼”的感受矛盾。", "呸": "语域：“呸”是表示鄙视的粗俗叹词，不适用于医生与病人的正式问答。"}, "sentence_index": 6, "correct_answer": "是的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“我们今晚去看电影吧？”“是的，我要加班。”", "explanation": "这里“是的”表示同意去看电影，但“我要加班”表示去不了，前后矛盾，应改用〈不行〉。"}, {"text": "“你会说英语吗？”“是的，我一句也不会说。”", "explanation": "这里误用了肯定义。“是的”表示会说英语，但“一句也不会说”是否定，应改用〈不会〉。"}, {"text": "“你想去吗？”“是的，我一点也不想去。”", "explanation": "这里误用了肯定义。“是的”表示想去，但“我一点也不想去”是否定，前后矛盾，应改用〈不〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“你饿了吗？”“是的了，我们去吃饭吧。”", "corrected_sentence": "“你饿了吗？”“是的，我们去吃饭吧。”", "error_description": "错误：“是的”后多了“了”；正确：“是的”。“是的”是固定叹词，用于肯定回答，后面不能加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“你觉得冷吗？”“是的的，我们把门关上吧。”", "corrected_sentence": "“你觉得冷吗？”“是的，我们把门关上吧。”", "error_description": "错误：“是的”后多了一个“的”，写成“是的的”；正确：“是的”。“是的”是固定叹词，不能重复“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85746, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85746, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85746, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "表示同意或肯定的回答，意思是“对”“没错”。", "primary_collocate": null, "pronunciation": "shì de", "ipa": "ʂɻ̩˥˩ tɤ", "syllable_count": 2, "sentences": [{"text": "“今天天气真好。”“是的，很适合出去玩。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这个电影很好看。”“是的，我也喜欢。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“学汉语很有意思。”“是的，我也这么想。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“学习要努力。”学生们说：“是的！”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“他今天很忙。”“是的，他一直在工作。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这家饭馆的菜很好吃。”“是的，而且不贵。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我们该走了。”“是的，已经很晚了。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“坐地铁比开车快。”“是的，不用堵车。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“北京的冬天很冷。”“是的，我穿了很多衣服。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我们应该早点睡。”“是的，明天要早起。”", "target_word": "是的", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "同意别人的看法时说“是的”，表示没错", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85746, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "是的", "is_correct": true, "explanation": "是的（shì de）：正确答案，表示同意对方的看法，意思是“对”“没错”。"}, {"text": "似的", "is_correct": false, "explanation": "似的（sì de）：声母 s 与 sh 只差一个音位，是最小对立对，意思是“像……似的”。"}, {"text": "湿的", "is_correct": false, "explanation": "湿的（shī de）：第一个音节只与 shì 声调不同（第一声），意思是“潮湿的（东西）”。"}, {"text": "使得", "is_correct": false, "explanation": "使得（shǐ dé）：两个音节的声调都与 shì de 不同（shǐ 为第三声，dé 为第二声），意思是“使得”。"}], "explanations": {"是的": "是的（shì de）：正确答案，表示同意对方的看法，意思是“对”“没错”。", "似的": "似的（sì de）：声母 s 与 sh 只差一个音位，是最小对立对，意思是“像……似的”。", "湿的": "湿的（shī de）：第一个音节只与 shì 声调不同（第一声），意思是“潮湿的（东西）”。", "使得": "使得（shǐ dé）：两个音节的声调都与 shì de 不同（shǐ 为第三声，dé 为第二声），意思是“使得”。"}, "sentence_index": null, "correct_answer": "是的"}, "level_3": {"options": [{"text": "是的", "is_correct": true, "explanation": "正确答案：“是的”表示同意“天气真好”的看法。"}, {"text": "不行", "is_correct": false, "explanation": "语义：“不行”是否定的评价，与“天气真好”“适合出去玩”的看法相反。"}, {"text": "谢谢", "is_correct": false, "explanation": "搭配：“谢谢”是致谢语，不能用来回应对天气的评价。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”是让人安静的声音，与“很适合出去玩”的意思无关。"}], "explanations": {"是的": "正确答案：“是的”表示同意“天气真好”的看法。", "不行": "语义：“不行”是否定的评价，与“天气真好”“适合出去玩”的看法相反。", "谢谢": "搭配：“谢谢”是致谢语，不能用来回应对天气的评价。", "嘘": "语义：“嘘”是让人安静的声音，与“很适合出去玩”的意思无关。"}, "sentence_index": 0, "correct_answer": "是的"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“这次考试很难。”“是的，这次考试很容易。”", "explanation": "这里误用了同意义。“是的”表示同意“很难”，但“很容易”是相反的看法，应改用〈不对〉。"}, {"text": "“这是你的书。”“是的，这是他的。”", "explanation": "这里误用了肯定义。“是的”表示同意“这是你的书”，但“这是他的”是否定，应改用〈不是〉。"}, {"text": "“他很聪明。”“是的，他很笨。”", "explanation": "这里误用了同意义。“是的”表示同意“他很聪明”，但“他很笨”是相反的评价，应改用〈不〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85746, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "是的", "is_correct": true, "explanation": "是的（shì de）：正确答案，表示同意对方的看法，意思是“对”“没错”。"}, {"text": "失德", "is_correct": false, "explanation": "失德（shī dé）：两个音节的声调都与 shì de 不同，意思是“道德上有缺失”。"}, {"text": "实得", "is_correct": false, "explanation": "实得（shí dé）：两个音节的声调都与 shì de 不同，意思是“实际得到的（东西）”。"}, {"text": "拾得", "is_correct": false, "explanation": "拾得（shí dé）：两个音节的声调都与 shì de 不同，意思是“捡到、拾到”。"}], "explanations": {"是的": "是的（shì de）：正确答案，表示同意对方的看法，意思是“对”“没错”。", "失德": "失德（shī dé）：两个音节的声调都与 shì de 不同，意思是“道德上有缺失”。", "实得": "实得（shí dé）：两个音节的声调都与 shì de 不同，意思是“实际得到的（东西）”。", "拾得": "拾得（shí dé）：两个音节的声调都与 shì de 不同，意思是“捡到、拾到”。"}, "sentence_index": null, "correct_answer": "是的"}, "level_3": {"options": [{"text": "是的", "is_correct": true, "explanation": "正确答案：“是的”表示同意“我们该走了”的说法。"}, {"text": "早上好", "is_correct": false, "explanation": "语义：“早上好”是早晨的问候，与“已经很晚了”矛盾。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是粗俗的鄙视语，不适用于这种对话语境。"}, {"text": "好耶", "is_correct": false, "explanation": "语义：“好耶”表示高兴，与“已经很晚了”所表达的催促语气不合。"}], "explanations": {"是的": "正确答案：“是的”表示同意“我们该走了”的说法。", "早上好": "语义：“早上好”是早晨的问候，与“已经很晚了”矛盾。", "呸": "语域：“呸”是粗俗的鄙视语，不适用于这种对话语境。", "好耶": "语义：“好耶”表示高兴，与“已经很晚了”所表达的催促语气不合。"}, "sentence_index": 6, "correct_answer": "是的"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“他去过北京。”“是的，他从没去过北京。”", "explanation": "这里误用了同意义。“是的”表示同意“他去过北京”，但“从没去过”是相反的说法，应改用〈不对〉。"}, {"text": "“他会游泳。”“是的，他一次也没下过水。”", "explanation": "这里误用了同意义。“是的”表示同意“会游泳”，但“一次也没下过水”是否定，应改用〈不会〉。"}, {"text": "“这家店很贵。”“是的，东西很便宜。”", "explanation": "这里误用了同意义。“是的”表示同意“很贵”，但“很便宜”是相反的评价，应改用〈不贵〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85746, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“这道题不难。”“是是的，我会做。”", "corrected_sentence": "“这道题不难。”“是的，我会做。”", "error_description": "错误：“是是的”，多写了一个“是”；正确：“是的”。“是的”是一个词，不能在前面重复“是”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85746, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“要下雨了。”“是的了，快带伞吧。”", "corrected_sentence": "“要下雨了。”“是的，快带伞吧。”", "error_description": "错误：“是的”后多了“了”；正确：“是的”。“是的”是固定叹词，后面不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
