INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85749, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“怎么”是用来问事情怎样做，或者为什么会这样。", "primary_collocate": null, "pronunciation": "zěn me", "ipa": "tsən˨˩ mə", "syllable_count": 2, "sentences": [{"text": "你怎么去学校？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字怎么写？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天怎么没来？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜怎么做？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怎么哭了？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，去火车站怎么走？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么知道我在这儿？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机怎么用？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么黑，你怎么还不回家？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么不吃饭？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怎么样", "label": "复合"}, {"form": "怎么办", "label": "复合"}, {"form": "怎麼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "疑问代词，问做法或原因", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85749, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "配价：“你”已作主语，“谁”不能再作施事，“你谁去学校”不成句。"}, {"text": "怎么", "is_correct": true, "explanation": "“怎么”在此询问去学校的方式，符合句意。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，不能用来问去学校的方式。"}, {"text": "什么", "is_correct": false, "explanation": "搭配：“什么”作“去”的修饰成分时不成立，“什么去学校”不通。"}], "explanations": {"谁": "配价：“你”已作主语，“谁”不能再作施事，“你谁去学校”不成句。", "怎么": "“怎么”在此询问去学校的方式，符合句意。", "多少": "语义：“多少”问数量，不能用来问去学校的方式。", "什么": "搭配：“什么”作“去”的修饰成分时不成立，“什么去学校”不通。"}, "sentence_index": 0, "correct_answer": "怎么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天去怎么地方？", "explanation": "这里的“怎么”不能修饰处所名词；此处应用〈哪儿〉，应说“我们明天去哪儿”。"}, {"text": "他喝了怎么茶？", "explanation": "这里的“怎么”不能用来指定茶的种类；此处应用〈什么〉，应说“他喝了什么茶”。"}, {"text": "她穿了怎么衣服？", "explanation": "这里的“怎么”不能用来指定衣服的类别；此处应用〈什么〉，应说“她穿了什么衣服”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "配价：“你”已作主语，“谁”不能再作“知道”的主语，“你谁知道”不成句。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“这么”修饰性质或程度，不能直接修饰“知道”，“你这么知道”不通。"}, {"text": "怎么", "is_correct": true, "explanation": "“怎么”在此询问“知道”的途径，符合句意。"}, {"text": "那么", "is_correct": false, "explanation": "搭配：“那么”同样不能修饰“知道”，与句意不合。"}], "explanations": {"谁": "配价：“你”已作主语，“谁”不能再作“知道”的主语，“你谁知道”不成句。", "这么": "搭配：“这么”修饰性质或程度，不能直接修饰“知道”，“你这么知道”不通。", "怎么": "“怎么”在此询问“知道”的途径，符合句意。", "那么": "搭配：“那么”同样不能修饰“知道”，与句意不合。"}, "sentence_index": 6, "correct_answer": "怎么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想买怎么东西？", "explanation": "这里的“怎么”不能用来指代具体的东西；此处应该用〈什么〉，应说“我想买什么东西”。"}, {"text": "你是怎么学生？", "explanation": "这里的“怎么”不能直接修饰名词询问类别；此处应该用〈什么样的〉，应说“你是什么样的学生”。"}, {"text": "你喜欢怎么颜色？", "explanation": "这里的“怎么”不能用来询问颜色的种类；此处应该用〈哪种〉，应说“你喜欢哪种颜色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你想吃怎么东西？", "corrected_sentence": "你想吃什么东西？", "error_description": "错误：“怎么”不能直接修饰名词“东西”询问具体事物，应用“什么”。正确：应说“你想吃什么东西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
