INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85750, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "疑问代词，询问方式、原因或状况。", "primary_collocate": null, "pronunciation": "zěn me", "ipa": "tsən˨˩ mə", "syllable_count": 2, "sentences": [{"text": "这个词用英语怎么说？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么了？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的书怎么在我这儿？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怎么没带伞？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭的时候，盐怎么放？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门怎么打不开？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿到机场怎么坐车？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们怎么认识的？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈怎么不高兴了？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题该怎么回答？", "target_word": "怎么", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怎么样", "label": "复合"}, {"form": "怎么办", "label": "复合"}, {"form": "怎麼", "label": "繁体"}], "register": "口语", "sense_fingerprint": "疑问代词，问方式、原因、状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bef0ee9-0a67-4b24-a146-571f4a4b9cb5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "语义：“谁”问说话的人是谁，句中问的是“怎样说”，不是“谁说”。"}, {"text": "怎么", "is_correct": true, "explanation": "“怎么”在此询问表达的方式，符合句意。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，不能用来问“用英语说”的方式。"}, {"text": "哪儿", "is_correct": false, "explanation": "搭配：“哪儿”问处所，不与“说”构成搭配，“用英语哪儿说”不通。"}], "explanations": {"谁": "语义：“谁”问说话的人是谁，句中问的是“怎样说”，不是“谁说”。", "怎么": "“怎么”在此询问表达的方式，符合句意。", "多少": "语义：“多少”问数量，不能用来问“用英语说”的方式。", "哪儿": "搭配：“哪儿”问处所，不与“说”构成搭配，“用英语哪儿说”不通。"}, "sentence_index": 0, "correct_answer": "怎么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你在看怎么书？", "explanation": "这里的“怎么”不能直接修饰名词“书”询问种类；此处应用〈什么〉，应说“你在看什么书”。"}, {"text": "他去了怎么地方？", "explanation": "这里的“怎么”不能修饰处所名词；此处应用〈什么〉，应说“他去了什么地方”。"}, {"text": "你要喝怎么饮料？", "explanation": "这里的“怎么”不能直接修饰名词“饮料”；此处应用〈什么〉，应说“你要喝什么饮料”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么", "is_correct": false, "explanation": "配价：“什么”不能修饰动词“坐车”作状语，“什么坐车”不通。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“这么”指示方式须有前文或手势所指，此处无所指，“这么坐车”不自然。"}, {"text": "那么", "is_correct": false, "explanation": "语义：“那么”是指示程度或方式，不用来询问坐车的方式，句意不通。"}, {"text": "怎么", "is_correct": true, "explanation": "“怎么”在此询问去机场的乘车方式，符合句意。"}], "explanations": {"什么": "配价：“什么”不能修饰动词“坐车”作状语，“什么坐车”不通。", "这么": "搭配：“这么”指示方式须有前文或手势所指，此处无所指，“这么坐车”不自然。", "那么": "语义：“那么”是指示程度或方式，不用来询问坐车的方式，句意不通。", "怎么": "“怎么”在此询问去机场的乘车方式，符合句意。"}, "sentence_index": 6, "correct_answer": "怎么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想买怎么衣服。", "explanation": "这里的“怎么”不能用来指代衣服的种类；此处应该用〈什么〉，应说“他想买什么衣服”。"}, {"text": "她有怎么朋友？", "explanation": "这里的“怎么”不能用来询问朋友的类型；此处应该用〈什么样的〉，应说“她有什么样的朋友”。"}, {"text": "你喜欢怎么音乐？", "explanation": "这里的“怎么”不能用来询问音乐的类别；此处应该用〈哪种〉，应说“你喜欢哪种音乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事该怎么样办？", "corrected_sentence": "这件事该怎么办？", "error_description": "错误：“怎么样”是另一个词，不能直接修饰动词“办”。正确：只用“怎么”，应说“这件事该怎么办”，不能说“这件事该怎么样办”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道菜怎么样吃？", "corrected_sentence": "这道菜怎么吃？", "error_description": "错误：“怎么样”是另一个词，不能直接修饰动词“吃”。正确：只用“怎么”，应说“这道菜怎么吃”，不能说“这道菜怎么样吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1217ec02-3bc5-459e-ba44-22ee6f69046c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
