INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85751, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "“用”是拿一样东西来做事。", "primary_collocate": null, "pronunciation": "yòng", "ipa": "jʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "我用筷子吃饭。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用笔写字。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用刀切菜。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机给朋友打电话。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正用着电脑，你等一下。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩用铅笔画了一只猫。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用勺子喝汤。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用毛巾擦脸。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用剪刀剪纸。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用锤子在墙上钉钉子。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用了", "label": "完成体"}, {"form": "用过", "label": "经历体"}, {"form": "用着", "label": "持续体"}, {"form": "用用", "label": "重叠"}], "register": "通用", "sense_fingerprint": "拿具体的工具或物品来做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85751, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用", "is_correct": true, "explanation": "用（yòng）：正确答案，表示拿具体的工具或物品来做某件事。"}, {"text": "涌", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是涌出。"}, {"text": "孕", "is_correct": false, "explanation": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是怀孕。"}, {"text": "踊", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是踊跃。"}, {"text": "韵", "is_correct": false, "explanation": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是韵律。"}], "explanations": {"用": "用（yòng）：正确答案，表示拿具体的工具或物品来做某件事。", "涌": "yǒng（第三声）与 yòng（第四声）声调不同，意思是涌出。", "孕": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是怀孕。", "踊": "yǒng（第三声）与 yòng（第四声）声调不同，意思是踊跃。", "韵": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是韵律。"}, "sentence_index": null, "correct_answer": "用"}, "level_3": {"options": [{"text": "用", "is_correct": true, "explanation": "正确答案：“用筷子”表示拿筷子来吃饭。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”是脚部的动作，不能与“筷子”搭配。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”指书写，与“用筷子吃饭”的意思不符。"}, {"text": "看", "is_correct": false, "explanation": "语义：“看”指视觉动作，不能表示拿着筷子吃饭。"}], "explanations": {"用": "正确答案：“用筷子”表示拿筷子来吃饭。", "踢": "搭配：“踢”是脚部的动作，不能与“筷子”搭配。", "写": "语义：“写”指书写，与“用筷子吃饭”的意思不符。", "看": "语义：“看”指视觉动作，不能表示拿着筷子吃饭。"}, "sentence_index": 0, "correct_answer": "用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用着一件外套出门。", "explanation": "这里应该用〈披着〉。“用着”表示使用某物，外套披在身上要用“披着”，不能说“用着一件外套”。"}, {"text": "他用了一双新鞋出门。", "explanation": "这里应该用〈穿〉。“用”表示拿工具做事，鞋子要“穿”，不能说“用了一双新鞋出门”。"}, {"text": "他用着一顶帽子出门。", "explanation": "这里应该用〈戴着〉。“用着”表示使用某物，帽子戴在头上要用“戴着”，不能说“用着一顶帽子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85751, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "用", "is_correct": true, "explanation": "用（yòng）：正确答案，表示拿具体的工具或物品来做某件事。"}, {"text": "拥", "is_correct": false, "explanation": "yōng（第一声）与 yòng（第四声）声调不同，意思是拥抱。"}, {"text": "永", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是永远。"}, {"text": "勇", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是勇敢。"}, {"text": "泳", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是游泳。"}, {"text": "运", "is_correct": false, "explanation": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是运输。"}], "explanations": {"用": "用（yòng）：正确答案，表示拿具体的工具或物品来做某件事。", "拥": "yōng（第一声）与 yòng（第四声）声调不同，意思是拥抱。", "永": "yǒng（第三声）与 yòng（第四声）声调不同，意思是永远。", "勇": "yǒng（第三声）与 yòng（第四声）声调不同，意思是勇敢。", "泳": "yǒng（第三声）与 yòng（第四声）声调不同，意思是游泳。", "运": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是运输。"}, "sentence_index": null, "correct_answer": "用"}, "level_3": {"options": [{"text": "用", "is_correct": true, "explanation": "正确答案：“用勺子”表示拿勺子来喝汤。"}, {"text": "骂", "is_correct": false, "explanation": "语义：“骂”表示责骂，与“喝汤”的意思无关。"}, {"text": "跑", "is_correct": false, "explanation": "搭配：“跑”是移动的动作，不能与“勺子”搭配。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”的动作不能用于“勺子喝汤”。"}], "explanations": {"用": "正确答案：“用勺子”表示拿勺子来喝汤。", "骂": "语义：“骂”表示责骂，与“喝汤”的意思无关。", "跑": "搭配：“跑”是移动的动作，不能与“勺子”搭配。", "打": "搭配：“打”的动作不能用于“勺子喝汤”。"}, "sentence_index": 6, "correct_answer": "用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用着一副眼镜看书。", "explanation": "这里应该用〈戴着〉。眼镜戴在脸上要用“戴着”，不能说“用着一副眼镜”。"}, {"text": "她把书用在书架上。", "explanation": "这里应该用〈放〉。“用在”表示使用于某处，把书放到书架上要用“放”，不能说“用在书架上”。"}, {"text": "她用了一支笔吃饭。", "explanation": "这里误用了工具：“用”要搭配能完成该动作的工具，吃饭要“用筷子”，笔不能用来吃饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85751, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一块湿布擦了一下桌子。", "corrected_sentence": "她用一块湿布擦了一下桌子。", "error_description": "错误：“她一块湿布擦”，漏掉了“用”；正确：“她用一块湿布擦”，表示拿工具做事要用“用＋工具＋动词”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85751, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把剪刀用很好。", "corrected_sentence": "这把剪刀用得很好。", "error_description": "错误：“用很好”，漏掉了补语前的“得”；正确：“用得很好”，“用”后接程度补语要加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
