INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85752, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "动词，使物件、手段等发挥作用以达到目的。", "primary_collocate": null, "pronunciation": "yòng", "ipa": "jʊŋ˥˩", "syllable_count": 1, "sentences": [{"text": "你可以用这个办法解决问题。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用自己的钱开了一家小店。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要用好每一分钟。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用汉语跟老师说话。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用这种方法学会了游泳。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图片教孩子们认字。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用新技术提高了质量。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些钱我要用在学习上。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用这种药治好了他的病。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用一个简单的故事说明这件事。", "target_word": "用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "用了", "label": "完成体"}, {"form": "用过", "label": "经历体"}, {"form": "用着", "label": "持续体"}, {"form": "用用", "label": "重叠"}], "register": "通用", "sense_fingerprint": "运用方法、金钱、时间等来达到目的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85752, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "用", "is_correct": true, "explanation": "用（yòng）：正确答案，表示使物件、手段等发挥作用以达到目的。"}, {"text": "拥", "is_correct": false, "explanation": "yōng（第一声）与 yòng（第四声）声调不同，意思是拥抱。"}, {"text": "永", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是永远。"}, {"text": "勇", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是勇敢。"}, {"text": "泳", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是游泳。"}, {"text": "运", "is_correct": false, "explanation": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是运气、运输。"}], "explanations": {"用": "用（yòng）：正确答案，表示使物件、手段等发挥作用以达到目的。", "拥": "yōng（第一声）与 yòng（第四声）声调不同，意思是拥抱。", "永": "yǒng（第三声）与 yòng（第四声）声调不同，意思是永远。", "勇": "yǒng（第三声）与 yòng（第四声）声调不同，意思是勇敢。", "泳": "yǒng（第三声）与 yòng（第四声）声调不同，意思是游泳。", "运": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是运气、运输。"}, "sentence_index": null, "correct_answer": "用"}, "level_3": {"options": [{"text": "用", "is_correct": true, "explanation": "正确答案：“用这个办法”表示利用这个办法达到目的。"}, {"text": "买", "is_correct": false, "explanation": "搭配：“买”指购买，不能与“办法”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“办法”搭配，“吃这个办法”不成立。"}, {"text": "玩", "is_correct": false, "explanation": "语义：“玩”表示游戏或嬉戏，与“解决问题”的意思不符。"}], "explanations": {"用": "正确答案：“用这个办法”表示利用这个办法达到目的。", "买": "搭配：“买”指购买，不能与“办法”搭配。", "吃": "搭配：“吃”不能与“办法”搭配，“吃这个办法”不成立。", "玩": "语义：“玩”表示游戏或嬉戏，与“解决问题”的意思不符。"}, "sentence_index": 0, "correct_answer": "用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她用着一件红裙子去上学。", "explanation": "这里应该用〈穿着〉。“用着”表示使用某物，穿衣服要用“穿着”，不能说“用着一件裙子”。"}, {"text": "我用了两个包子。", "explanation": "这里应该用〈吃〉。“用”作“吃”讲只用于敬语，如“请慢用”，说自己吃东西不能用“用”。"}, {"text": "他用了一家小店。", "explanation": "这里应该用〈开〉。“用”表示使用，开店要用“开”，不能说“用了一家小店”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85752, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "用", "is_correct": true, "explanation": "用（yòng）：正确答案，表示使物件、手段等发挥作用以达到目的。"}, {"text": "涌", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是涌出、涌现。"}, {"text": "孕", "is_correct": false, "explanation": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是怀孕。"}, {"text": "韵", "is_correct": false, "explanation": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是韵律。"}, {"text": "踊", "is_correct": false, "explanation": "yǒng（第三声）与 yòng（第四声）声调不同，意思是踊跃。"}], "explanations": {"用": "用（yòng）：正确答案，表示使物件、手段等发挥作用以达到目的。", "涌": "yǒng（第三声）与 yòng（第四声）声调不同，意思是涌出、涌现。", "孕": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是怀孕。", "韵": "yùn（第四声）与 yòng 韵母不同（n 与 ng），意思是韵律。", "踊": "yǒng（第三声）与 yòng（第四声）声调不同，意思是踊跃。"}, "sentence_index": null, "correct_answer": "用"}, "level_3": {"options": [{"text": "用", "is_correct": true, "explanation": "正确答案：“用新技术”表示利用新技术达到提高质量的目的。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”指放置，不能说“放新技术提高了质量”。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”指燃烧或加热，不能与“新技术”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指唱歌，与“提高了质量”的意思无关。"}], "explanations": {"用": "正确答案：“用新技术”表示利用新技术达到提高质量的目的。", "放": "搭配：“放”指放置，不能说“放新技术提高了质量”。", "烧": "搭配：“烧”指燃烧或加热，不能与“新技术”搭配。", "唱": "语义：“唱”指唱歌，与“提高了质量”的意思无关。"}, "sentence_index": 6, "correct_answer": "用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用了一条项链去参加晚会。", "explanation": "这里应该用〈戴〉。“用”表示使用，项链戴在身上要用“戴”，不能说“用了一条项链”。"}, {"text": "她把菜用进冰箱。", "explanation": "这里应该用〈放〉。“用”表示使用某物达到目的，把菜放进冰箱要用“放”，不能说“用进冰箱”。"}, {"text": "她用了一个漂亮的辫子。", "explanation": "这里应该用〈扎〉或〈编〉。“用”不能表示做辫子，扎、编辫子要用“扎”或“编”，不能说“用了一个辫子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85752, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把这笔钱用买新电脑。", "corrected_sentence": "我们把这笔钱用来买新电脑。", "error_description": "错误：“用买新电脑”，漏掉了“来”；正确：“用来买新电脑”，“把……用来＋动词”表示用于某个目的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85752, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔钱我们用改善教室上。", "corrected_sentence": "这笔钱我们用在改善教室上。", "error_description": "错误：“用改善教室上”，漏掉了“在”；正确：“用在……上”，表示把东西用于某个方面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
