INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85753, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "“这些”是指离我们近的好几个人或东西。", "primary_collocate": null, "pronunciation": "zhè xiē", "ipa": "ʈʂɤ˥˩ ɕje˥", "syllable_count": 2, "sentences": [{"text": "这些是我的书。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些都是我的朋友。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些是什么？", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些我都喜欢。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些是妈妈买的水果。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些太贵了，我不买。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些都是今天要用的东西。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这些就是我家的照片。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些是谁的鞋？", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些我已经看过了。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "這些", "label": "繁体"}], "register": "通用", "sense_fingerprint": "单独作主语或宾语，指近处的多个人或东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这些", "is_correct": true, "explanation": "「这些」指近处的几个东西，与“是我的书”搭配，句意通顺。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”指说话人和别人，是人，不能指“书”。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，陈述句里不能说“谁是我的书。”"}, {"text": "此", "is_correct": false, "explanation": "语域：“此”是书面语，口语里不说“此是我的书”。"}], "explanations": {"这些": "「这些」指近处的几个东西，与“是我的书”搭配，句意通顺。", "我们": "语义：“我们”指说话人和别人，是人，不能指“书”。", "谁": "语义：“谁”是疑问代词，陈述句里不能说“谁是我的书。”", "此": "语域：“此”是书面语，口语里不说“此是我的书”。"}, "sentence_index": 0, "correct_answer": "这些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你看远处那座山上，这些是谁的房子？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，远处山上的房子离说话人很远，要用那些。"}, {"text": "这些是我的一支笔。", "explanation": "这里应该用〈这〉。这些指几个近处的人或东西，只有一支笔时要用这。"}, {"text": "你看河对岸远远的，这些是什么？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，河对岸远处的东西要用那些。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这些", "is_correct": true, "explanation": "「这些」指近处的多个东西，与“都是今天要用的东西”搭配。"}, {"text": "这个", "is_correct": false, "explanation": "语义：“这个”只指一个，与“都”和复数的“东西”说法不合。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指人，不能指“东西”。"}, {"text": "彼", "is_correct": false, "explanation": "语域：“彼”是书面语，口语里不说“彼都是……”。"}], "explanations": {"这些": "「这些」指近处的多个东西，与“都是今天要用的东西”搭配。", "这个": "语义：“这个”只指一个，与“都”和复数的“东西”说法不合。", "他们": "语义：“他们”指人，不能指“东西”。", "彼": "语域：“彼”是书面语，口语里不说“彼都是……”。"}, "sentence_index": 6, "correct_answer": "这些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你看马路对面很远的地方，这些是什么？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，马路对面很远的东西要用那些。"}, {"text": "这些是我在一万公里外的国家遇到过的情况。", "explanation": "这里应该用〈那些〉。这些指离说话人近的，一万公里外的国家离说话人很远，要用那些。"}, {"text": "你看天上远远的，这些是星星吗？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，天上远处的东西要用那些。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些都朋友我都认识。", "corrected_sentence": "这些朋友我都认识。", "error_description": "“都”不能插在“这些”和名词之间。应写作“这些朋友我都认识”，只保留谓语前的一个“都”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些的东西我都要带走。", "corrected_sentence": "这些东西我都要带走。", "error_description": "“这些”后面不能加“的”再直接接名词。应去掉“的”，写成“这些东西”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
