INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85754, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "指示代词，指较近的多个人或事物。", "primary_collocate": null, "pronunciation": "zhè xiē", "ipa": "ʈʂɤ˥˩ ɕje˥", "syllable_count": 2, "sentences": [{"text": "这些苹果很新鲜。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些学生都很努力。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢这些花。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些衣服是新买的。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这些书放在桌子上。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些孩子正在公园里玩。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你吃这些菜吧，我吃那些。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题老师都讲过了。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问你这些词是什么意思。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些歌我听了很多遍。", "target_word": "这些", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "這些", "label": "繁体"}], "register": "通用", "sense_fingerprint": "放在名词前，限定近处的多个人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec8071b-2a1d-4600-a16f-7fee21a7b3ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "这些", "is_correct": true, "explanation": "「这些」指近处的多个东西，放在“苹果”前限定，句意通顺。"}, {"text": "我们", "is_correct": false, "explanation": "语义：“我们”是人称代词，不能修饰“苹果”。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”是疑问代词，不能放在名词前限定“苹果”。"}, {"text": "此", "is_correct": false, "explanation": "语域：“此”是书面语，口语里不说“此苹果很新鲜”。"}], "explanations": {"这些": "「这些」指近处的多个东西，放在“苹果”前限定，句意通顺。", "我们": "语义：“我们”是人称代词，不能修饰“苹果”。", "谁": "语义：“谁”是疑问代词，不能放在名词前限定“苹果”。", "此": "语域：“此”是书面语，口语里不说“此苹果很新鲜”。"}, "sentence_index": 0, "correct_answer": "这些"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你看远处山上，这些房子是谁家的？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，远处山上的房子要用那些。"}, {"text": "这些是我的一件衣服。", "explanation": "这里应该用〈这〉。这些指几个近处的东西，只有一件衣服时要用这。"}, {"text": "你看马路对面远远的，这些车是谁的？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，马路对面远处的车要用那些。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "这些", "is_correct": true, "explanation": "「这些」指近处的多个东西，与句中的“那些”形成远近对比，句意通顺。"}, {"text": "他们", "is_correct": false, "explanation": "语义：“他们”指人，不能修饰“菜”。"}, {"text": "哪", "is_correct": false, "explanation": "语义：“哪”是疑问代词，这里是请对方吃，不能说“你吃哪菜吧”。"}, {"text": "彼", "is_correct": false, "explanation": "语域：“彼”是书面语，口语里不说“你吃彼菜吧”。"}], "explanations": {"这些": "「这些」指近处的多个东西，与句中的“那些”形成远近对比，句意通顺。", "他们": "语义：“他们”指人，不能修饰“菜”。", "哪": "语义：“哪”是疑问代词，这里是请对方吃，不能说“你吃哪菜吧”。", "彼": "语域：“彼”是书面语，口语里不说“你吃彼菜吧”。"}, "sentence_index": 6, "correct_answer": "这些"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你看天上远远的，这些鸟是什么鸟？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，天上远处的鸟要用那些。"}, {"text": "你看对面山上，这些树长得真高。", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，对面山上的树离得远，要用那些。"}, {"text": "你看河对岸远远的，这些船是谁的？", "explanation": "这里应该用〈那些〉。这些指离说话人近的东西，河对岸远处的船要用那些。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些一间房子都很旧。", "corrected_sentence": "这些房子都很旧。", "error_description": "错误：“这些”后直接加了数量词“一间”。“这些”是指示词，不能与数量词连用，应写作“这些房子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些的书都很贵。", "corrected_sentence": "这些书都很贵。", "error_description": "“这些”后面不能加“的”再直接接名词。应去掉“的”，写成“这些书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9bdf495-a56c-4bf5-af61-4cab2cbf9631') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
