INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (85755, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "“得”放在动作后面，用来说这件事做得怎么样。", "primary_collocate": null, "pronunciation": "de", "ipa": "tɤ", "syllable_count": 1, "sentences": [{"text": "他跑得很快。", "target_word": "得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈做饭做得很好。", "target_word": "得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她唱歌唱得真好听。", "target_word": "得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "弟弟睡得很晚。", "target_word": "得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你今天来得真早。", "target_word": "得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他汉语说得不太好。", "target_word": "得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师讲得很清楚，我们都听懂了。", "target_word": "得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她写字写得又快又漂亮。", "target_word": "得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们玩得很高兴。", "target_word": "得", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我昨天吃得太多了。", "target_word": "得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "得：用在动词后，引出对动作情况的评价", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
